window.__D("text/torat-chaim/c032",{"p":[[2300550546,"נמשך ממקיף דח\"ע הקדומה שלמעלה מקו המדה באו\"כ בנר\"נ דז\"א, וכן תפילין שמניח ממצות תפילין שלמטה נעשה מקיף דד' מוחין דז\"א יותר ממצות תפילין העליונים וכה\"ג בכל המצות בצדקה שמתעורר למעלה חסד עליון בדרועא ימינא כו' ע\"י מעשה הצדקה שלמטה דוקא כדין הצדקה מזה נמשך תוס' אור רב בחסד <span data-k=\"pg\">984</span> ּ דאצי' שלמעלה הרבה ממצות הצדקה הרוחני' דאצי' הנ\"ל וכה\"ג וד\"ל. וזהו כמו יתרון מעלת המצות שלנו על מצות ברוחניות שקיימו האבות שא' ושמי הוי' לא נודעתי להם<sup data-n=\"4336\">643</sup> כמ\"ש במ\"א הטעם באריכות מצד יתרון האור מן החושך דק\"נ ששרשו בתהו שקדם לתיקון וראי' מקרבן בהמה גשמיות ע\"ג המזבח שנעשה ריח ניחוח לשם הוי' דאצי' בתוס' מרובה על עיקר האור שהי' בתחלה וכה\"ג וד\"ל).\n<b>ונמצא</b> מובן מכל זה דע\"י המצות שלמטה בדברים גשמיי' דוקא נעשה בחי' תוס' אורות עליונים בכלים דע\"ס דאצי', כמו ע\"ד דוגמא ממזון דתורה למטה לנשמות כנ\"ל ומעשה המצות שיחי' האדם למטה שהוא הנשמה האלקי' והאדם נברא בצלם אלקי' באדם העליון, ע\"כ גם שאין לו גוף מ\"מ דברה תורה כלשון בנ\"א, וז\"ש אשר יעשה אותם האדם וחי בהם<sup data-n=\"4337\">644</sup> גם באדם העליון מעצמו' אוא\"ס ממש. ואע\"פ שאינו נק' רק חיזוק להחזיק האורות בכלים, אבל יש בזה עילוי גדול בתוס' מרובה על העיקר כנ\"ל בחכ' וחס\"ד שאדם עוסק בכל ימי חייו שמתגדל גם עי\"ז במעלה עליונה ביותר ממדתו. כך ע\"י החכמה דתורה שלמטה וחסד דצדקה שלמטה שמעורר לבחי' אור החכ' וחסד דאצי' יאיר עי\"ז ממקור החכ' וחסד דמקיף העליון שבעצמות המאציל דנק' חכים ולא בחכ' ידיעא כו' וכה\"ג. וזהו כמו שעושה המזון התחדשות בכל יום כענין חיבור וקשר בפנימי' דאדם העליון שיוחזק האור הפנימי ויתגדל בכלי כו' הרבה יותר מהפרש שבין בחי' גדלות דהקיץ ובין קטנות דשינה או עיבור ולידה שאינו רק בחיצוני' ולא בפנימי' כנ\"ל וכמובן מכל דמיון הנ\"ל בחומר וצורה בנפש וגוף וד\"ל.\n<b>והנה</b> יובן עוד ענין א' מכל מה שמבואר למעלה במשל דאורות וכלים למעלה באו\"פ ואו\"מ שע\"י המצות דוקא, והוא מה שאנו רואים שיש בחי' ההתכללות באברים החיצונים מראש עד הרגל כא' עד מבלי שימצא ראש וסוף<sup data-n=\"4338\">645</sup> כלל, כי ע\"י הגידול מהעורקים בדם ההולך בכל אבר, אע\"פ שיש עי\"ז טבע מיוחדת לכל אבר ואבר מובדל מזולתו בכחו ובפעולתו כידוע כמו העין לראות והרגל להילוך והמוח לשכל וכה\"ג באברים אחרי', מ\"מ כל א' וא' מתכלל עם זולתו והיו לאחדים ממש עד שכל א' מקבל מזולתו ומשפיע לזולתו ובאמצעות חיבורם כא' יחד דוקא נק' אדם שלם ובלא אבר א' נק' פגם בכולו. ולא עוד אלא שלא נמצא בכללותם בחי' ראש וסוף כלל, שהרי אנו רואים שהראש מקבל מן הרגל כמו ע\"י הקזת דם ברגל ירפא חולי",[["4336","643","<b>ושמי הוי' לא נודעתי להם</b>: נסמן לעיל פ' יתרו רנא, א הערה 16."],["4337","644","<b>אשר יעשה אותם האדם וחי בהם</b>: אחרי יח, ה."],["4338","645","<b>מבלי שימצא ראש וסוף</b>: ע\"פ קהלת ג, יא."]]],[2300550559,"הראש<sup data-n=\"4339\">646</sup> וכן ע\"י מזון שיהופך לדם יעלה למוח שבראש מגידי הרגל שהולכים מלמטה למעלה כידוע, ועד\"ז יש בכללות האברים התכללות מזה לזה דוקא עד שמתחברים כולם כא' והיו למהות א' ממש וד\"ל. וראי' לזה ממה שנראה בחוש בקלקול א' מן האברים הפנימי' והחיצונים יתקלקל כל מעמד ומצב הגוף כו', וכן בהמשכת החיות בפעולה אחת באבר א' בהילוך ברגל ובמלאכה ביד הרי משתתף ומתחבר בזה כל הכחות של כל האברים גם ממוח שבראש וראי' ושמיעה שבעין ואוזן <span data-k=\"pg\">תצב</span> ּ וכל האברי' פנימי' וחיצוני' כו' שמזה מורה עוצם בחי' ההתכללו' שלהם כא' ממש כנ\"ל וד\"ל.\n<b>והנה</b> כל סיבת ענין בחי' התכללות הזאת באברים דאדם הוטבעה בטבעיו' בתולדות בבטן אמו בבחי' ההעלם ויצא לגילוי גמור ע\"י גידים ועורקי' בדם הוא הנפש המסבבי' בכל האברים כא' כו', והיינו מצד בחי' התקשרות הנפש הרוחניו' באברי' כנ\"ל, ובנפש הרוחניו' אע\"פ שיש בה ג\"כ בחי' אברים רוחני' שהן כמו חומר לצורה ממש כנ\"ל כמו נשמות בג\"ע בראי' ושמיעה והילוך רוחני כנ\"ל, מ\"מ בבחי' הרוחניו' כל האברים הן כלולים כא' ממש בבחי' התכללות מראש לרגל וכמו ע\"ד דוגמא מענין ובחי' הרגשה רוחניות שמרגיש בחיו' נפשו בכל כחות האברי' בהתכללות מראש לרגל כא' מבלי שימצא ראש וסוף בהדרגה וסדר כלל. וכך הוא בנפש הרוחניו' שאין ברוחני הבדל מקום ושטח בחומר מיוחד לכל אבר כמו שיש באברי' הגשמי' כעין ואוזן ויד ורגל ממש כו', ולכך גם בהארת אור הנפש הרוחני' באברים גשמיי' כעין ואוזן כו' יש בכל האברים בחי' ההתכללות הזאת כנ\"ל. ואע\"פ שמצד האברים עצמן יש הפרש בין יד לרגל אבל בדם הוא הנפש כו' שהוא בחי' הרוחניות מערב ומחבר ומקשר כל אבר עם זולתו עד שלא יוכל להיות אחד בלא חבירו כאלו הן מהות א' ממש כנ\"ל לפי שברוחניות הדם הוא הנפש אין הפרש והבדל כלל ביניהם כו' וד\"ל. וזהו סיבת התכללו' מראש לרגל שהראש מקבל מרגל ברפואה ומזון כנ\"ל, ומה שמשתתף מכל כחות האברי' בפעולה א' אע\"פ שכל א' מיוחד ומובדל במזגו ופעולתו כנ\"ל, והיינו מצד התקשרות וחיבור כל האברים זע\"ז עד שבאמצעות כולם יחד הן כמו בנין קומה אחת קשורי' זע\"ז עד שבהמשך אבר א' כיד ורגל יתמשך כל קומת הגוף כא' כמו שממשיכים לכל קומת האדם בידו אחת וברגל א' שיקחנו חבירו וימשכנו אליו כו', וטעם קשר וחיבור חיצוני' הבנין של הקומה אינו בא רק מצד התקשרו' דצורה בחומר מנפש הרוחניות שמערב ומקשר כל חיות האברי' כא' מטעם הנ\"ל וד\"ל.\n<b>(אך</b> הנה באמת מבואר במ\"א בהיפוך גמור דבחי' ההתכללו' באברי' החיצוני' זהו בא מצד חומר האברים עצמן<sup data-n=\"4340\">647</sup> דוקא ולא מצד הגידים ועורקים שמסבבי' בהם בחי' שבדם לבד כנ\"ל,",[["4339","646","<b>ע\"י הקזת דם ברגל ירפא חולי הראש</b>: ראה גם שער האמונה סג, ב ובהערה 9."],["4340","647","<b>ההתכללו'. . האברים עצמן</b>: ראה גם לעיל פ' שמות מה, א ואילך."]]],[2300550572,"אלא מצד עצמות הרכבת האברים שמורכבי' וכלולים זמ\"ז כאשר נעשי' כלים לאור וחיות שבהם עד מבלי ימצא בהם ראש וסוף כלל, שזהו עיקר בחי' האדם דתיקון בהתכללו', שמחמתו יבא בחי' ההתכללו' דאורות בכחות האברי' ע\"י הגידי' ועורקי' המסבבי' בהם מלמעלה למטה מראש לרגל ומרגל לראש כו'. כמו שרואי' בשיתוף וחיבור מכל הכחות יחד משכל שבמוח עד חיות צפרני הרגל כו' בהרגשה ותנועה ופעולה א' כנ\"ל שכל זה אינו רק מצד בחי' ההתכללות שבאברים עצמן דוקא (לפי ששרשן למעלה יותר מאו\"פ שבכלים אעפ\"י שמגביל לאור כמ\"ש בע\"ח דבנין הכלים קודם כנ\"ל). ואדרבה באורות שהן כחות הנפש ואפי' <span data-k=\"pg\">986</span> ּ בכלים שלהן כמו שהן בנפש כלולי' כא' ואין הפרש כלל בין זה לזה ובהארתו בכלי הגוף הם מתחלקי' זה מזה מצד התחלקות האברים, ואמנם בחי' ריבוי התחלקו' הזאת בריבוי הכלים שהן האברים זהו הסיבה לריבוי ההתכללו' זה מזה דוקא וכמ\"ש במ\"א, דמטעם זה עיקר בחי' אדם שבציור קומה ראש וסוף הוא בחיצוני' האברים דוקא כו' שיש בו בחי' התכללו' מראש לסוף ומסוף לראש כנ\"ל שמפני זה דוקא נק' אדם אדמה לעליון<sup data-n=\"4341\">648</sup> ממש כו' שזהו עיקר שלימות דבחי' התיקון דשם מ\"ה שזהו ענין שם מ\"ה מלגיו דאיהו ארח כל האצי'<sup data-n=\"4342\">649</sup> כו' וד\"ל).\n<b>והנה</b> עפ\"י כל זה יובן ג\"כ בענין מעשה המצות שנקראים כלים ואברים כנ\"ל דרמ\"ח מ\"ע נק' רמ\"ח אברים דמלכא למעלה שזהו כמו בחי' הגבלת האברים באדם למטה, דאע\"פ דיש לכל מצוה ומצוה ענין וכוונה מיוחדת בפרטיו' שהיא בחי' כלי להכיל ולקבל את האור הפנימי' ועצמי' דבחי' רצון העליון וחכ' עילאה ומדות שמלובש באופן הגבלת הכלי ומעשה המצוה כך וכך דוקא, ומצוה האחרת זולתה הוא בחי' כלי מיוחדת לאור העליון דרצה\"ע במדרגה אחרת בפ\"ע ואין להם חיבור כלל זע\"ז, כמו שיש לכל אבר ואבר טבע מיוחדת בפ\"ע במזגו ופעולתו גם בתולדה בבטן כנ\"ל. מ\"מ הרי כל המצות מתכללי' זע\"ז דוקא והיו לאחדים ממש שבחסרון אבר א' לא נק' אדם שלם אלא בעל מום, כך ע\"י חסרון מצוה א' לא נק' אדם בצלם אלקי' דנשמה שנק' הוי' ואדם אדמה לעליון כמצות הוי' באו\"כ למעלה שקדשנו במצותיו ממש כנ\"ל, ולא עוד אלא שמקבל כל מצוה מזולתה ובאמצעות חיבורם יחד נק' אדם מבלי שימצא ראש וסוף כלל דראש מקבל מסוף. וראי' לזה ממצות ת\"ת שהיא בחכמה שבראש וכשעוסק במצות צדקה שהיא ברגל כמו במצות הכנסת כלה וכה\"ג נפטר מת\"ת ואפי' ממצות ק\"ש שהיא ביחו\"ע בחו\"ב שבראש כמובן בזוהר בעובדא דר\"י ור\"י<sup data-n=\"4343\">650</sup> כו', וכמ\"ש בצדקה תכונני<sup data-n=\"4344\">651</sup> וכן א' ומעשה ידינו כוננה עלינו<sup data-n=\"4345\">652</sup> ומעשה ידינו כוננהו שהוא ענין כל מעשה",[["4341","648","<b>אדם אדמה לעליון</b>: נסמן לעיל פ' יתרו רסב, א."],["4342","649","<b>שם מ\"ה מלגיו. . האצי'</b>: ראה ת\"ז בהקדמה (יז, א). הדרת מלך שם (ע' קיב). סידור אדה\"ז סדר מנחת ערב שבת."],["4343","650","<b>בעובדא דר\"י ור\"י</b>: זהר (ינוקא) בלק קפו, א. וראה לעיל פ' שמות מו, ג הערה 133."],["4344","651","<b>בצדקה תכונני</b>: ישעי' נד, יד."],["4345","652","<b>ומעשה ידינו כוננה עלינו</b>: תהלים צ, יז."]]],[2300550583,"הצדקה שהיא בחסד שביד שכל המצות נכללו בבחי' מעשה הצדקה ונק' צדקה כמ\"ש וצדקה תהי' לנו<sup data-n=\"4346\">653</sup> כי נשמור כו' ונק' עשי' בפו\"מ שמזה יכונן ויקומם לבחי' ראש, וכמשל הנ\"ל באברי' שהראש מקבל חיותו מן הרגל ע\"י גידים שברגל שיעלו למוחו. וכן ע\"י המזון דתורה שיחזק למוח החכמה יכול הוא שיקבל מחיזוק הרגל שהוא בהילוך כמו אחרי הוי' תלכו<sup data-n=\"4347\">654</sup> והוא ללכת בדרכי הוי' כו' וכילכו מחיל<sup data-n=\"4348\">655</sup> כו' שעי\"ז יתחזק כח החכ' שבראש, והוא מצד שיש התכללות במצות עד שכל א' מקבל מזולתה עד שבעשותו אחת ממצות ה' כמו בצדקה או ת\"ת או תפילין וכה\"ג מתחבר ומשתתף בזה מכל האורות העליוני' דרצה\"ע שבכל המצות יחד כמו שמתחבר הכל בפעולת אבר א' כנ\"ל. ובהיפוך בהעדר מ\"ע אחת ונתקלקל ונסתלק רוחניות האור העליון באבר זה המיוחד <span data-k=\"pg\">תצג</span> ּ למצוה זו נתקלקל ונפגם כל צלם אלקים דאדם בכל מעמד ומצב דציור אד\"ם ברוחניות דאור האלקי כנ\"ל במשל אברי' הגשמי'. וכמו החולי בגוף כך החולי ברוחניות שבנפש החוטא' ממש כידוע, והכל מטעם בחי' התכללות שיש במצות שנק' אברים חיצונים מבלי שימצא ראש וסוף אלא באמצעות כללותם יחד נק' אדם כו', לכן גזרו אומר דמצוה קלה כחמורה<sup data-n=\"4349\">656</sup> ממש ואין לחלק ביניהם כלל וכלל מטעם הנ\"ל. ולכך גם במצוה אחת כמו במצות צדקה וחסד שביד מעורר למעלה בחי' צדקה וחסד העליון באו\"כ דיד ימין כמו חסד דרועא ימינא כו' בחי' המשכות דאו\"מ דרב חסד שבעצמות ממש כנ\"ל, ה\"ז כאילו נמשך כל בנין קומת אדם העליון כמו שיומשך כל קומת אדם התחתון ע\"י שיקחנו בידו א' כנ\"ל. והיינו מה שנמשך כל עצמות אור א\"ס שבאו\"כ דאצי' במצוה אחת דצדקה שלמטה כמו בחסד וצדקה דאברהם שהמשיך גילוי עצמו' אלקו' בעולם, וכן באהבה רבה לישראל כמ\"ש אהבת עולם אהבתיך<sup data-n=\"4350\">657</sup> ע\"כ משכתיך חסד. וכן מלמטה למעלה משכני<sup data-n=\"4351\">658</sup> כו' וכמ\"ש ומעשה ידינו כוננה עלינו כו' כנ\"ל. וכך הוא בכל המצות שיעשה אותם האדם וחי בהם מחיי החיים דא\"ס ב\"ה ממש בבחי' התכללות דאדם אדמה לעליון ממש כו' וד\"ל.\nוהנה מבואר למעלה בענין סיבת ההתכללו' דאברי' באה מחמת בחי' ההתכללו' בעצמות הנפש כדוגמא דהרגשה בחיות הנפש בכל האברי' כו' והנפש וכחות שלה מתקשרי' באברי' ועושי' ג\"כ התכללות כו' כנ\"ל. וכך יובן ג\"כ במצות שנק' אדם בחיצוני' האברים שסיבת ההתכללו' שלהם בא רק מחמת ריבוי ההתכללו' באורות העליונים שברמ\"ח מ\"ע למעלה, והוא מבחי' שם מ\"ה דחכ' דתורה אור שמאיר בכל מצוה ומצוה בפרט ובכלל שעושה בחי' ההתכללו' באורות שהן מדות",[["4346","653","<b>שכל המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה לעיל פ' שמות יד, א. וש\"נ."],["4347","654","<b>אחרי הוי' תלכו</b>: פ' ראה יג, ה [בדילוג]."],["4348","655","<b>וכילכו מחיל</b>: תהלים פד, ח."],["4349","656","<b>דמצוה קלה כחמורה</b>: אבות רפ\"ב. ראה גם מאמרי אדה\"א במדבר ח\"ג ע' תתקפה."],["4350","657","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — ראה הנסמן לעיל בפ' וארא סב, ג]."],["4351","658","<b>משכני</b>: שה\"ש א, ד."]]],[2300550594,"העליוני' דאוריי' מח\"ע נפקת<sup data-n=\"4352\">659</sup>, ונמשך במדות הפנימי' דתורה כמו להבדיל ולהורות בין טו\"ט כו' ובפרטיות דמ\"ע איך ומה יעשה בחי' כלי לאור. וזהו והתורה והמצוה<sup data-n=\"4353\">660</sup> כו' שהן ב' דברים כמ\"ש כי נר מצוה שהמצוה נק' נר ותורה אור כללי ואור פרטי שנמשך בכל רמ\"ח מ\"ע במוח שבראש שמתפשט בכל האברי' בגידי' המחברי' ומקשרים לאברי' זע\"ז יחד כו'. וזהו הטעם דמצות ת\"ת כנגד כולם<sup data-n=\"4354\">661</sup> ותלמוד גדול מפני שמביא לידי מעשה<sup data-n=\"4355\">662</sup> דהיינו שמביא וממשיך האור בכלי כו' מזה נעשה בחי' ההתכללו' במצות כנ\"ל וד\"ל (וזהו שם מ\"ה מלגאו דאיהו אורח כל האצי' כו' שזהו עיקר בחי' התיקון דשם מ\"ה דחכ' לעשות ריבוי האורות בריבוי הכלים שמזה דוקא נעשה בחי' ההתכללו' דוקא גם באברים בהתקשרות צורה וחומר הנ\"ל).\n<b>(ואמנם</b> מבואר למעלה שיש אומרי' בהיפוך שעיקר בחי' ההתכללו' באברים בא רק מצד עצמן דוקא ולא מצד האורו' כו', והוא לפי ששרש החומר גבוה מן הצורה דבנין הכלים קודמי' לבנין האורות כו' שכאשר יתוקן החומר ממילא יומשך הצורה (וכמ\"ש במ\"א בענין אין ויש רוחניו' וגשמיו' דשרש היש דגשמיו' למעלה משרש האין הרוחני<sup data-n=\"4356\">663</sup> והוא <span data-k=\"pg\">988</span> ּ בבחי' מקיף שלמעלה מאו\"פ מאחר שביכולת החומר שהוא הכלי להחזיק האור בתוכו ומקיפו וסובבו מבחוץ כו'. ולכך גם בענין ההתכללות דמצות מראש לסוף ומא' לזולתו אינו רק מצד עצם מעשה המצוה שנעשה למטה בבחי' כלי חיצוני' דוקא ששרשו במקיף דמצוה בכתר שבכת\"ר שנק' תר\"ך עמודי אור<sup data-n=\"4357\">664</sup> שלמעלה מאורות דחו\"ב ומדות שבמוחא ולבא דבחי' אד\"ם באו\"פ דנר\"נ כו'. וזהו יתרון מעלת המצות שלנו על מצות הרוחניות דאצי' כנ\"ל לפי שעיקר בחי' ההתכללות דאדם מראש לרגל זהו בכלים ואברים החיצוני' יותר מהתכללות דאורות דאדם פנימי עד גם בחי' התכללות דאורות אינו בא רק מצד התלבשות שלהן בכלים כו' וד\"ל. וזהו סוף דבר כו' את מצותיו שמור במעשה דוקא כי זה כל האדם<sup data-n=\"4358\">665</sup> העליון בפנימי' דפנימי' וכמ\"ש ומעשה ידינו דוקא כוננהו כו', לפי שנעוץ תחב\"ס<sup data-n=\"4359\">666</sup> דוקא כידוע. והיינו ענין ג' מדרגות דראש תוך סוף דג' מיני אדם בכלל, אדם דבריאה ויצי' ועשי' שהוא אדם חיצוני באברים דרמ\"ח מ\"ע בפו\"מ שע\"ז א' עשיתיו<sup data-n=\"4360\">667</sup> לרבותא יותר מאדם הפנימי במוחין דחב\"ד. וכן בג' כלים דראש תוך סוף פנימי אמצעי וחיצון<sup data-n=\"4361\">668</sup> בחיצון דוקא נעוץ פנימי מטעם הנ\"ל. וזהו דסוף מעשה נה\"י דנה\"י בעקבות משיחא עכשיו עלה במחשבה הפנימי' ועצמי' והוא שא' במשיח וגבה מאד לפי שהקי' עולה של מצוה<sup data-n=\"4362\">669</sup> במעשה כו'. וראי' מהשתחווא' גשמי' בקומת אדם",[["4352","659","<b>דאוריי' מח\"ע נפקת</b>: נסמן לעיל פ' יתרו רסח, ד."],["4353","660","<b>והתורה והמצוה</b>: משפטים כד, יב."],["4354","661","<b>ת\"ת כנגד כולם</b>: פאה רפ\"א."],["4355","662","<b>ותלמוד גדול. . מעשה</b>: קדושין מ, ב."],["4356","663","<b>דשרש היש דגשמיו' למעלה משרש האין הרוחני</b>: ראה גם מאמרי אדה\"א נ\"ך ע' קכו. וש\"נ."],["4357","664","<b>בכתר. . תר\"ך עמודי אור</b>: ראה פרדס (שער מהות והנהגה) ש\"ח, פ\"ג. לעיל פ' שמות ח, א. וש\"נ."],["4358","665","<b>סוף דבר. . את. . כל האדם</b>: קהלת יב, יג [ושם: ואת]."],["4359","666","<b>שנעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["4360","667","<b>עשיתיו</b>: ישעי' מג, ז."],["4361","668","<b>בג' כלים. . וחיצון</b>: ראה גם לעיל פ' בא קכט, ד. וש\"נ."],["4362","669","<b>במשיח. . שהקי' עולה של מצוה</b>: ראה גם לעיל פ' בשלח קסט, ג. וש\"נ."]]],[2300550605,"חיצוני יותר עולה מהשתחווא' פנימי' דחכמה כו', וזהו וכל קומה כו' קומה דאדם קדמאה<sup data-n=\"4363\">670</sup> שמסתיי' בסוף העשי' בעקבות משיחא במצות בפו\"מ לבד. וזהו כי נר מצוה עי\"ז ותו' אור שבבחי' או\"ח המעשה גדול יותר שעי\"ז נעשה תורה אור בחכמה בראש מטעם הנ\"ל וד\"ל).\n<b>והנה</b> מעתה הרי יובן מכל הנ\"ל<sup data-n=\"4364\">671</sup> ענין הנ\"ל במה שאו' הוי' אלקינ\"ו ממש בברכות המצות, שזהו מה שישראל מייחדים שמו העצמי דשם הוי' הפנימי ועצמי דאור א\"ס ב\"ה בשם אלקי' להיות אלקינו ממש בלי העלם והסתר בלבושי' כלל, שאין החיצוני' מסתיר הפנימי' כלל כמו הוי' אלקיו עמו ממש כנ\"ל. הנה זהו ע\"י המצות דוקא שעושי' למטה בדברים גשמיי' כקלף דתפילין וצמר דציצית וכה\"ג שעולה מבירורי' דנוגה בבחי' או\"ח כנ\"ל, שזהו שנק' סוף מעשה בחיצוני' האברים כו', שעולה למעלה מעלה להוסיף אור פנימי דפנימיו' מבחי' עצמו' דא\"ס מקור כל המקיפי' דנר\"נ דאדם הנ\"ל להאיר בבחי' כלים פנימי' ועצמיי' דמצות העליונו' בבחי' רמ\"ח אברי' דמלכא בלא בחי' חיצוני' כלל, אלא כולו פנימי' ועצמיו' בכלי כמו באור, ולא כמו אורו' בכלים דאצי' עכשיו שיש בחי' חיצוניו' הכלים שהן מסתירי' על הפנימי' כו', משא\"כ בנר מצוה שהוא בחי' כלי פנימי' ועצמיו' לפנימי' האור דא\"ס ממש והיינו לבחי' רצון וח\"ע העצמי' דפנימי' מל' דא\"ס ופנימיו' מדותיו העצמיי' כמו שהוא בעצמיו' המלך הקדוש כו' (שנק' שעשועי המלך בעצמו ממש, ולמעלה יותר מח\"ע דתוה\"ק ומדות דא\"ס שקדם לעולם הנאצל, כי נתחב\"ס בתורה וישראל שלמטה באור דתו\"מ בגשמיו' דוקא שבזה נשלם שלימות דח\"ע הקדומה מטעם הנ\"ל (וראי' ממ\"ת שירדה על <span data-k=\"pg\">תצד</span> ּ הר סיני בגילוי אור פני חכמת אדם העליון ונתלבש בדברים גשמיי' במ\"ע ול\"ת באנכי ולא כו' שמזה עולה למעלה יותר מפנימי' דח\"ע שבאדם העליון מטעם הנ\"ל דנתחב\"ס דוקא כו') (אך עכשיו מלובש הפנימי' ועצמיות דאור א\"ס בכלים דמעשה המצות שלמטה בהעלם ולע\"ל יתגלה מבחי' ההעלם וכמ\"ש ולא יכנף עוד כו', וזהו כמו מתן בסתר<sup data-n=\"4365\">672</sup> ממש כמ\"ש במ\"א והוא העוה\"ב כמ\"ש למעלה), (וכן מה שא' בע\"ח דכל עיקר ענין המצות עכשיו אינו רק להוסיף אורות באצי'<sup data-n=\"4366\">673</sup> כו', תוספת זה בא מבחי' הפנימיות ועצמות דוקא בקשר וחיבור פנימיו' בכלים פנימי' כנ\"ל בענין מזון דתורה שמחזיק האור בכלי כו').\n<b>ומעתה</b> יובן ג\"כ בתוס' ביאור מ\"ש בפ' זו ואתה תצוה את בנ\"י, ואתה דוקא, שהוא בחי' פנימי' שם מ\"ה דחכמה",[["4363","670","<b>וכל קומה כו' קומה דאדם קדמאה</b>: ראה גם לעיל פ' בשלח קמו, ב."],["4364","671","<b>מכל הנ\"ל</b>: תיבות אלו נכתבו ממעל לתיבת ענין."],["4365","672","<b>מתן בסתר</b>: ראה גם לעיל פ' בשלח קעו, ג. וש\"נ."],["4366","673","<b>בע\"ח. . המצות. . להוסיף אורות באצי'</b>: ראה שם (שער מ\"ן ומ\"ד) של\"ט, דרוש יא כלל טז. לעיל פ' בשלח קנו, ב הערה 312."]]],[2300550614,"דתורה דמשה<sup data-n=\"4367\">674</sup> שנק' שושבינא דמלכא<sup data-n=\"4368\">675</sup> לחבר האורות הפנימי' בכלים פנימי' במצות למעלה ולמטה, ע\"ז או' ואתה תצוה דוקא לבנ\"י שהן בבחי' כלים לעצמיו' האורות לומר הוי' אלקינו ממש מטעם הנ\"ל, שיוכלו לייחד יחוד הפנימי ועצמי באו\"כ למעלה. אך זהו ע\"י משה שיצוה לבנ\"י משום דתורה אור כו' (וכמו שם מ\"ה מלגאו דאיהו אורח כל האצי' שרש התיקון בריבוי האורות בריבוי הכלים כנ\"ל), ועיקר הציווי הזה הוא שיקחו אליך דוקא שמן זית זך כתית דוקא למאור, פי' כדי להמשיך מעצמות דמאור מקור כל או\"פ ואו\"מ להאיר אור פנימי' ועצמי' בכלים דמצות שנק' נר מצוה. פי' שבהדלקת נרות המנורה צריך שיקבלו ממול פני המנורה דוקא מפנימית ועצמיו' דא\"ס כמו שהוא בעצמיו' חכמתו ומדותיו כנ\"ל, ומשם יאירו ז' הנרות דנש\"י<sup data-n=\"4369\">676</sup> בכלל להיות הוי' אלקינו ממש ע\"י נר מצוה דוקא כנ\"ל בלי העלם ולבוש ובלי הפסק כלל להיותו בבחי' פב\"פ פנימי' האור בפנימי' הכלי כנ\"ל, כמו יאר הוי' פניו אליך פניו ממש בפנימי' ועצמו' דא\"ס יאיר באור דתו\"מ למטה ובנשמות ישראל בלי מסך מבדיל כלל כמו הוי' אלקיו עמו כו', וכמו שאו' הוי' אלקינו שקדשנו במצותיו ממש. וזהו כדי להעלות נר תמיד וקאי על ב' מיני נר נר דמצוה ונר דנשמות ישראל שיהי' קיום נצחי לאור הפנימי' בפנימי' הכלים בתמידות גם בלילה כיום יאיר, לפי שאין מקום לחושך להחשיך שם כלל, והוא לפי שאל מול פני המנורה יאירו כו' שזהו בחי' מאור עצמו שנק' פנ\"י המנור\"ה יאירו בפנימיות הכלים דמצות שיאירו מן המאור. וזהו למאור דוקא להעלות נר ולא א' להעלות אור וכן בהעלותך את הנרות<sup data-n=\"4370\">677</sup> שהוא בחי' נר מצוה בכלים שיאיר בפנימי' האברים (כמו ענין הנ\"ל בחיזוק האור באברי' שכולו פנימי' בלא חיצוני' כלל כו' וד\"ל).\n<b>והנה</b> מעתה צריך להבין בדרך פרטיות מ\"ש ואתה תצוה כו', דלכאורה הרי עיקר הכוונה בציווי זה לבנ\"י שיקחו אליך שמן זית כו' הוא כדי להעלות נר תמיד לבד, וענינו הוא להיות נשמות ישראל שנק' נרות הוי' ע\"י נר מצוה שלהם כנ\"ל בבחי' יחוד פנימי דפב\"פ דוקא כנ\"ל ובתמידות בלי הפסק. <span data-k=\"pg\">990</span> ּ וזהו ענין מצוה דהדלקת נרות המנורה שיאירו אל מול פני המנורה דוקא כנ\"ל, וא\"כ לכאורה לא הי' שייך ענין מצוה זו שיקחו שמן זית זך כו' למשה שיצוה ע\"ז לבני ישראל רק לאהרן דוקא, כמו שנצטוה אהרן בהדלקת נרות המנורה כמ\"ש בהעלותך את הנרות כו' לפי שזה שייך לאהרן כהנא רבא שנק' שושבינא דמטרוניתא<sup data-n=\"4371\">678</sup> דוקא שביכולתו להעלות לנשמת ישראל שנק' נר הוי' למעלה כידוע. אבל בחי' מ\"ה דחכ' דמשה שנק' שוש' דמלכא דוקא שהוא בחי' ממוצע להמשיך אור א\"ס באו\"כ פנימי'",[["4367","674","<b>שם מ\"ה. . דמשה</b>: ראה גם לעיל פ' שמות מג, א. וש\"נ."],["4368","675","<b>דמשה שנק' שושבינא דמלכא</b>: נסמן לעיל פ' יתרו רסג, ב."],["4369","676","<b>ז' הנרות דנש\"י</b>: ראה מאמרי אדה\"א במדבר ח\"ג ע' תתפא ואילך (ובהנסמן בריש המאמר שם). ע' תתקעב. ש\"א מא, ב ובהערה 45. לקמן שמו, ג. פ' ויקהל תמ, א."],["4370","677","<b>בהעלותך את הנרות </b>: בהעלותך ח, ב."],["4371","678","<b>לאהרן. . שושבינא דמטרוניתא</b>: נסמן לעיל פ' יתרו רסט, ד."]]],[2300550621,"כנ\"ל, אין זה שייך למשה כלל שיצוה ליקח שמן כו' כדי להעלות נר תמיד כו' שאין מדריגתו רק בבחי' המשכה דאו\"י מלמעלה למטה דוקא ולא בבחי' או\"ח בהעלאה שזה שייך לאהרן דוקא כנ\"ל וא\"כ למה א' ויקחו אליך דוקא כו'. אך התירוץ לזה זהו מה שמפרש בטעם לקיחת שמן זית כתית שהוא למאו\"ר דוקא שממנו מקור כל המשכות אור במקבלי' שזה שייך למשה דוקא כנ\"ל, אך א\"כ מה הוא שמסיים בסיפא להעלות נר תמיד שזהו שייך לאהרן ולא למשה מטעם הנ\"ל וד\"ל. ואמנם הנה שרש הענין והכוונה בציווי זה למשה דוקא הוא שיצוה להביא שמן זית זך כו' כדי לעשות ולתקן הכלי דנר מצוה שיוכל לעלות למעלה להיות בחי' כלי קיבול ליחו\"ע הפנימי' שהוא להעלות נר תמיד כו', כי עיקר בחי' פנימית הכלי זהו השמן זית זך שלפי ערך צלילת השמן כך יהי' צלילת האור מן המאו\"ר כשיומשך אחר הפתילה (שהיא הנשמה והאור הוא אור דתורה כנ\"ל וכמ\"ש בזהר ע\"פ ושמן על ראשך אל יחסר דא עובדין טבאן<sup data-n=\"4372\">679</sup> כו' (כמשי\"ת). וזה תלוי במשה דוקא שהוא שם מ\"ה מקור התיקון שיתקן בחי' הכלים לאורות באופן שיהי' בבחי' פנימי' ולא בבחי' חיצוניו' כדי שיוכלו לקבל מבחי' המאור שהוא מול פני כו', כי גם בכלים יש בחי' פנימי' וחיצוניו' וכאשר יתקן בכלים ע\"י שמן זית שיקחו למשה כו' אזי יוכל להיות בחי' העלאות הנרות למעלה שיאירו בבחי' פב\"פ ע\"י אהרן דוקא וזהו כדי להעלות נר תמיד בפנימי' הכלים ע\"י אהרן וד\"ל.\n<b>וביאור</b> ענין זה היינו ענין הכח של המשפיע דוקא שהוא בחי' משה להחזיר למקבל שהן נשמות ישראל שנק' נר הוי' ובמצות שלהם שנק' נר מצוה שיהיו עומדים בבחי' פב\"פ, דהיינו אף שנסוגו אחור ועומדים למטה בבחי' אחור באחור יחזירם להיות בפב\"פ כו'. ואין כח הזה רק במשה שיצוה לבנ\"י ויקחו אליך כו' שבזה מחזירם פב\"פ להעלות נר תמיד בפנימי' הכלים דמצות ולא בבחי' אחוריי' וחיצוניות לבד שאינו עולה למעלה כלל (כמשי\"ת) (והיינו לפי שבחי' משה שנק' שושבינא דמלכא הוא בבחי' מאור מקור כל אור דתורה הפנימי' שמשם דוקא יוכל להיות כח החזרת פב\"פ מאחור באחור כו' (כענין שא' מאור שבה מחזירו למוטב<sup data-n=\"4373\">680</sup> להיות בבחי' פב\"פ בחי' מאור דוקא כו').\n<b>ולהבין</b> זה יש להקדים תחלה ביאור ענין <span data-k=\"pg\">תצה</span> ּ ההפרש בכלל בין בחי' פב\"פ ובין אב\"א (כמו בזמן הגלות שנק' שינה כו' או עיבור בקטנות המוחין בנה\"י שבנה\"י תלת גו תלת כנ\"ל) וכנ\"י הם בבחי' אב\"א אף במצות שלהם כו', כמו יען נגש העם הזה אלי בשפתיו<sup data-n=\"4374\">681</sup> כו' ותהי יראתם אותי מצות",[["4372","679","<b>ושמן על ראשך. . טבאן</b>: קהלת ט, ח. זהר בלק קפז, א. תניא פל\"ה."],["4373","680","<b>מאור שבה מחזירו למוטב</b>: ראה ירושלמי חגיגה פ\"א, סה\"ז. לקמן שמב, א. מאמרי אדה\"א בראשית ע' תקעא. וש\"נ. לעיל פ' שמות טז, ג הערה 689."],["4374","681","<b>יען נגש העם הזה אלי בשפתיו</b>: ישעי' כט, יג [ושם: יען כי נגש העם הזה בפיו ובשפתיו — ראה הנסמן לעיל פ' בשלח רג, ד]."]]],[2300550627,"אנשים מלומדה כו' כמשי\"ת) ובזמן בהמ\"ק בימי שלמה היו בנ\"י בבחי' פב\"פ וכמו במ\"ת שא' פב\"פ דיבר ה'<sup data-n=\"4375\">682</sup> כו' וכה\"ג) שזהו כמו בגשמיות למטה בשני בנ\"א עומדים יחד פב\"פ פנים של זה כנגד פנים של זה, זהו מורה על פנימי' אהבתם והתקשרותם הנאמנה בפנימי' המוח שבפני' ופנימי' הלב זע\"ז ע\"כ יחדיו ידובקו פב\"פ כמו במשה שידעו ה' פא\"פ<sup data-n=\"4376\">683</sup> וכה\"ג. אבל אב\"א זהו כשני ב\"א שאינם אוהבי' זא\"ז כלל שמצד שאין אהב' פנימי' בלב כלל לא יוכלו לעמוד פב\"פ כלל אלא מתרחקים זמ\"ז ופונה כ\"א פניו מחבירו ועומדי' אב\"א כו'. ואמנם יש להבין מאחר שעיקר הענין הזה אינו רק בענין קירוב וריחוק בפנימי' שהוא במוח ולב דוקא, שבאו\"נ<sup data-n=\"4377\">684</sup> יהי' קירוב פנימי' במוח ולב ובלתי אוהבים מרוחקים בלב זה מזה כו', וא\"כ אין זה תלוי בקירוב וריחוק בגשמיות שרחוקים זה מזה בגדר מקום או בפנותו עורף שגם בדברו עמדו ידבר בבחי' ריחוק בלב מן השפה ולחוץ ולצאת ידי חובתו בעול גדול אף שעומד פב\"פ זהו בחי' אב\"א ממש, ולהיפוך באה' פנימי' שבלב אף שרחוקי' יעמדו ואין פניהם קרוב זע\"ז נק' פב\"פ, ומה תלוי זה בגוף בעמדו פב\"פ או אב\"א ממש, העיקר הוא בנפשו אם קרובים בלב או רחוקים כו'. אך צריך לומר דענין הפנימי' וחיצוני' ברוחניות שבנפש זהו עצמו בגוף בפנים ואחוריי' דהפנים במוח ולב שם הוא משכן הפנימי' דוקא, והעורף ואחוריי' שם משכן החיצוני' שבנפש כי החומר דגוף נעשה בבחי' פנים ואחור לפי שהוא כלי לאור הנפש שמתחלק בפנימי' וחיצוני', וא\"כ כל בחי' הפנימי' דנפש תלוי בעמידה גשמית דגוף פב\"פ דוקא וכל חיצוניות הנפש היא באב\"א בגוף כו'. וראי' לזה דגם שבאמת אין הריחוק והקירוב במקום אינו מעלה ולא מוריד כלל לגוף ענין הקירוב והריחוק בפנימי' בהארת פנים שוחקות או להיפוך, מ\"מ נעשה זה בגוף בעמידתם פב\"פ או באב\"א, שהרי גם בריחוקם זמ\"ז במקום ושטח גשמי אם רואי' זה את זה פנים כנגד פנים דוקא אף שיעמדו מרחוק תגדל האהבה והקירוב בפנימי' בתשוקה נפלאה לראות ולהסתכל בפנים שוחקות ויפות זה בזה (כמו היונים זכר ונקבה שמסתכלים זה בזה באהבה נפלאה כמ\"ש במ\"א ע\"פ עיניך יונים כו'), ואדרבה תגדל האהבה והחשק זה לזה יותר בהארת פנים מחמת ראי' פני אהובו מרחוק שחומדו בפנימי' הלב כשרואה בפני' שלו דוקא ופנימי' הלב ניכר בפנים דוקא כי בפנים מתגלה וניכר אמיתי' פנימי' האדם ותוך לבבו כו', ולכך נק' פנים ע\"ש הפנימי'<sup data-n=\"4378\">685</sup> שבו שהוא מקום שבו ניכר ונגלה הפנימי' ועצמי' שלו דוקא כידוע.\n<b>וראי'</b> לזה מן הריקוד של או\"נ או חתן וכלה שמרקדי' זה כנגד זה מרחוק דוקא, ורק ראיי' פניהם זה על זה",[["4375","682","<b>פב\"פ דיבר ה'</b>: ואתחנן ה, ד."],["4376","683","<b>במשה שידעו ה' פא\"פ</b>: ברכה לד, י."],["4377","684","<b>שבאו\"נ</b>: שבאוהבים נאמנים."],["4378","685","<b>פנים ע\"ש הפנימי'</b>: ראה גם לעיל פ' בשלח קעד, ד. וש\"נ."]]],[2300550633,"דוקא ברוב אהבה ותשוקה ועונג נפלא להתקרב זע\"ז בריקוד וכשמתקרבי' <span data-k=\"pg\">992</span> ּ ועומדי' פב\"פ חוזרי' ומתרחקים בריקוד זה מזה אבל לא שיפנו עורף כלל זה מזה, אלא הכל פנים נגד פנים דוקא אף בריקוד לאחור, כי זהו עיקר התענוג בראות פניהם זא\"ז שמתגלה בחי' הפנימי' שבכל א' עם אהובו אף שירקדו לאחור פב\"פ כו', וכמו כשם שאני רוקד כנגד\"ך<sup data-n=\"4379\">686</sup> דוקא ובזה תגדל האהבה יותר כי ריחוק זה בשביל קירוב לבא פב\"פ כו'. ואף בעמדו בריחוק מקום ומסתכל בפנים תכסוף נפשו יותר בראי' והסתכלות זו כו', וכן להיפוך כשאין אהבה בלב כלל וכלל מזה לזה וקרוב לשנאה עד שלא יוכל לעמוד ולהביט פב\"פ (או יוכל להיות שלא מחמת שנאה אלא מפני הבושה או קטנות הערך בעיניו מאד כמו הכלה שהופכת פני'<sup data-n=\"4380\">687</sup> מן החתן ותלמיד בפני רבו ועבד לפני אדונו וכה\"ג) אז יעמדו אב\"א. ואמנם אע\"פ שאינם מתרחקי' זה מזה כלל אף בעמידה זו אב\"א אלא אדרבה הן עומדי' תכופי' וסמוכים זה אצל זה בקירוב, כמו שכתף זה עומד בקירוב גמור בדיבוק ממש לכתפו ואחוריו של חבירו בעמדם אב\"א כמו שהיו מקורבים זא\"ז בעמדם פב\"פ ממש, ועכ\"ז אין קירוב ודיבוק זה מועיל בעמדם אב\"א מאחר שפנה הפני' מחבירו ואינו מביט ורואה בפנים שלו וכן חבירו זהו עיקר הריחוק כמו שנתרחקו במקום והלכו זה מזה לגמרי (אך עכ\"ז כשעומדי' מחוברי' ודבוקי' בכתפיהם זע\"ז אף בחי' אב\"א עכ\"ז יוכל להיות קירוב בהחזרת פב\"פ מיד, משא\"כ בריחוק לגמרי שלא יחזור עוד לעולם כו') (וראי' מד\"ו פרצופי' דאדם וחוה<sup data-n=\"4381\">688</sup> שהיו נק' דיבוק ויחוד רק שהם דבוקי' בחיצוני' ואחוריי' כי גם ביחוד בחי' חיצוניות ואחוריים נק' יחוד וחיבור אף שאינו רק עורף ולא פנים הרי נחשב עכ\"פ מגופו ונגרר אחר הפנימי' שהעורף ואחוריי' נמשך אחר הפנים ונכלל בו, וגם מצד עצם דאחוריים ועורף יש בו יחוד וחיבור אף באו\"נ כזיווג אב\"א<sup data-n=\"4382\">689</sup> שנק' יחוד עכ\"פ (והגמלי' זיווגם אב\"א<sup data-n=\"4383\">690</sup> ), וממילא אף בבלתי אוהבים כשעומדי' אב\"א אין זה ריחוק לגמרי ונק' יחוד ויכולים להתקרב בפב\"פ בקל ע\"י יחוד זה החיצוני' דאב\"א כו' (כמו שבפב\"פ מרחוק יתקרבו מצד הפנים כך יוכל להיות הקירוב פב\"פ מסיבת הקירוב ביחוד ודיבוק חיצוני בבחי' אב\"א (וראי' מד\"ו פרצופי' דאדם וחוה שאח\"כ נבנה בנין חוה בפ\"ע ונעשה יחוד פב\"פ וא' זאת הפעם עצם מעצמי כו' לזאת יקרא אשה כי מאיש לוקחה זאת ע\"כ יעזוב<sup data-n=\"4384\">691</sup> כו', וא\"כ הרי מה שיש אהבה רבה ונפלאה ביחוד איש ואשתו לידבק בה יותר מאו\"א זהו לפי שהיא עצם מעצמי כו' והוא מה שהיתה תחלה כלולה ומתאחדת בעצמו ובשרו כו' שזהו שהיתה דבוקה בו מאחוריו אע\"פ שאין זה רק בבחי' אב\"א, מ\"מ נחשב מבחי' עצמו ובשרו עד שמפני זה לזאת תקרא אשה כו' שמחמת זה דוקא ימשוך אחרי' בבנין שלה בפרצוף בפ\"ע",[["4379","686","<b>כשם שאני רוקד כנגד\"ך</b>: סדר קידש לבנה."],["4380","687","<b>הכלה שהופכת פני'</b>: ראה פסחים פו, א (במשנה). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380106\" data-slug=\"likkutei-torah\" data-id=\"4001380106\">לקו\"ת צו ז, סע\"ג</a> ואילך. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרמו ואילך."],["4381","688","<b>מד\"ו פרצופי' דאדם וחוה</b>: ראה ברכות סא, א וברש\"י שם. לעיל פ' בא קכז, ב. וש\"נ. שע\"ת קכז, ב ובהערה 15."],["4382","689","<b>כזיווג אב\"א</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' רכג ואילך."],["4383","690","<b>והגמלים זיווגם אב\"א</b>: בכורות ח, א."],["4384","691","<b>זאת הפעם. . ע\"כ יעזוב</b>: בראשית ב, כג. כד."]]],[2300550639,"(וכן למ\"ד זנב הי'<sup data-n=\"4385\">692</sup> ע\"ז א' כי מאיש לוקחה זאת כו' (וכמשי\"ת).\n<b>והנה</b> הנמשל מכ\"ז יובן ג\"כ בענין יחוד וחיבור דנשמות ישראל שהן בחי' נוק' בחי' מקבל <span data-k=\"pg\">תצו</span> ּ ונק' כלה<sup data-n=\"4386\">693</sup> כידוע לגבי המשפיע שהוא בחי' שם הוי' דאצי' שנק' סוכ\"ע ונק' איש וכנ\"י נק' אשה<sup data-n=\"4387\">694</sup> כידוע. ויש בזה ב' מדרגות, א' בבחי' פב\"פ כשני בנ\"א או\"נ בנפשותם שפנימי' של כל א' ניכר בפנים שלו דוקא כנ\"ל. וכמו\"כ אהבה דכנ\"י להקב\"ה מלמטה למעלה הוא בבחי' פנים שלהם שהוא בחי' פנימי' הלב והמוח שלהם בעבוד\"ה שבלב ומוח בתפלה ובמס\"נ אמיתי' בק\"ש כמו בכל לבבך ובכל נפשך<sup data-n=\"4388\">695</sup> כו', כמ\"ש אליך הוי' נפשי אשא בפנימי' הרצון והלב שנק' נפשי ממש וכמו צמאה לך נפשי<sup data-n=\"4389\">696</sup> כו' נכספה וגם כלתה נפשי<sup data-n=\"4390\">697</sup> וכן נפשי אויתיך בלילה כו', שכל זה ניכר בפנים דבנ\"י אף בזמן שהם בבחי' ריחוק מאלקות כמו בזמן הגלות שנק' לילה בחשך והסתר כמו בעול שעבוד הפרנסה בקושי ביותר כידוע. ועכ\"ז לא נסוג אחור לבבם כלל וכלל, דהיינו שאין התקשרות פנימית הנפש בפנימי' הלב ומוח בעניני גופו כל היום רק ע\"י הכרח וכפי' שכופה א\"ע בזה העסק והטרדא רק כדי להחיות נפשו ונפשות ביתו כפי הסיפוק ההכרחי, שזהו מצד עול שמוטל עליו כרחיים בצוארו כידוע. ולכך כל עסקיו בצרכי גופו הוא בבחי' חיצוני' ואחוריי' בלבד שאין פנימי' רצונו בזה כלל וכלל, כי עיקר פנימית התקשרות הרצון והשכל ומדות שבלב הוא רק לה' לבדו שאליו ישא נפשו בכל פנימיות שבה בתפלה ותו\"מ ואוי\"ר כו' באה\"ר ותשוקה נפלאה, שזהו בחי' פנים דכנ\"י שתשוקתו רק לאסתכלא ביקרא דמלכא שהוא בפנימיות דשם הוי' באח\"פ ממש בבחי' פב\"פ דוקא, כמו לך א' לבי<sup data-n=\"4391\">698</sup> בקשו פנ\"י דוקא פנימי' הלב ואז את פניך הוי' אבקש. כי כמים הפא\"פ<sup data-n=\"4392\">699</sup> כו' כן יאיר ה' פניו דוקא לכנ\"י ג\"כ בפנים שוחקות וצהובו' בעוז אהבה רבה וחיבה יתירה מודעת להם גם הוא בראי' והסתכלות עליהם מבחי' הפנימי' ועצמיות שלו, וכמשל ב' או\"נ שמסתכלים בעיניהם זע\"ז ברוב אהבה רבה בתענוגי' ברשפי אש כו' (כמו היונים שמסתכלי' זע\"ז כנ\"ל וכמ\"ש עיניך יונים כו' וכמ\"ש הסיבי עינייך מנגדי כו' דמוקדין לי' בשלהובי דרחימותא<sup data-n=\"4393\">700</sup> כו' כמ\"ש במ\"א). וזהו שנק' יחוד פב\"פ כמו שהי' במ\"ת וכמו בג' רגלים שא' יראה כל זכורך את פני הוי'<sup data-n=\"4394\">701</sup> ממש וכשם שבא לראות בראי' פנימי' שבלב ומוח שניכר בפני' דוקא שכך יראה אור פני הוי' כו'.",[["4385","692","<b>למ\"ד זנב הי'</b>: ברכות שם."],["4386","693","<b>דנשמות ישראל. . ונק' כלה</b>: פסדר\"כ פסקא כב (שוש אשיש) וש\"נ. ראה גם לעיל פ' וארא עב, ג ובהערה 7."],["4387","694","<b>הוי'. . איש. . וכנ\"י נק' אשה</b>: ראה במדב\"ר פ\"ט, מד."],["4388","695","<b>בכל לבבך ובכל נפשך</b>: ואתחנן ו, ה."],["4389","696","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["4390","697","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["4391","698","<b>לך א' לבי</b>: תהלים כז, ח."],["4392","699","<b>כמים הפא\"פ</b>: ע\"פ משלי כז, יט."],["4393","700","<b>הסיבי עינייך. . דרחימותא</b>: שה\"ש ו, ה. ראה זהר קדושים פד, א. מאמרי אדה\"א שמות ח\"א ע' קלה, וש\"נ. לעיל פ' וארא פד, ב."],["4394","701","<b>יראה כל זכורך את פני הוי'</b>: פ' ראה טז, טז."]]],[2300550645,"<b>וכך</b> הוא גם בזמן הגלות שנתרחקו כנ\"י מאור פני הוי' שהי' בגילוי בזמן בהמ\"ק וכמ\"ש מרחוק הוי' נראה לי<sup data-n=\"4395\">702</sup> כו', דכל מה שמשיגי' ורואי' כנ\"י בעין השכל שבלב בשם הוי' סובב ואלקי' בחי' ממלא<sup data-n=\"4396\">703</sup> כו' הכל הוא מרחוק לבד ולא בגילוי גמור מקרוב כ\"כ, מ\"מ נכספה וגם כלתה נפשי לראות ולחזות בנועם הוי' להתענג על הוי' בראי' פניו מרחוק ביותר מבקרוב כמ\"ש נפשי אויתיך בלילה כו' כנ\"ל, וכן צמאה לך נפשי בארץ ציה כו', שתגדל רשפי אש האה\"ר מרחוק כשהוי' נראה לו מרחוק עכ\"פ יותר מבקרוב כמ\"ש כן בקדש חזיתיך הלואי<sup data-n=\"4397\">704</sup> כן בקדש חזיתיך ברשפי אש התלהבות תשוקה כזו כמ\"ש רשפי' רשפי אש<sup data-n=\"4398\">705</sup> בגלותא דוקא כמ\"ש במ\"א, וכן נפשי אויתיך יותר כו' וכמו הסיבי עינייך כו' כנ\"ל וד\"ל. וזהו כמשל הנ\"ל בריקוד ב' או\"נ כחתן וכלה זה כנגד זה דאע\"פ שמרוחקי' בריקוד זה תגדל אהבתם יותר רק כשרואי' פניהם זע\"ז כו', כי הריקוד הוא פנים כנגד פנים דוקא. וכך בזמן <span data-k=\"pg\">994</span> ּ הגלות נק' ריקוד כריקוד הלבנה בריחוקה מן השמש כמו שא' כשם שאני רוקד כנגדך כו' שהוא בשביל הקירוב, וכך הריחוק בגלות בשביל הקירוב אח\"כ שהרי פניהם איש אל אחיו גם בריחוק כמו בקירוב כנ\"ל כי זהו עיקר התענוג כו' וד\"ל.\n<b>אבל</b> הנה בחי' אב\"א בכנ\"י זהו להיפוך ממש, והיינו כאשר בחי' הפנימי' שלהם במוח ולב ורצון ומחשבה דו\"מ הכל הוא בעניני עוה\"ז דוקא בצרכי הגוף לבד, ואף בעסקם בפרנסה ישימו כל לבם ומוחם בבחי' הפנימי' בהתקשרות כל העצמיות ופנימיות דוקא כמו להשיג עושר וכבוד וכל הון יקר ולהתנהג בגדולות וזהו כל חיותו הפנימית שמשים נפשו בכפו בכל עוז במס\"נ ממש כל הימים. ונמצא שבחי' הפנים דכנ\"י הוא רק בהבלי עוה\"ז שם קשורים בשכלם בעומק ובמדות שבלב ובמעשיהם בתכלית הפנימי' בהתקשרות עבותות האהבה בחיי נפשו ממש בל תמוט לעולם לפי שנגעה עד הנפש כו', אבל לה' בק\"ש ותפלה ותו\"מ אין התעוררו' בנשמתם כלל במוח ולב בפנימי' וכמו אין קורא בשמך<sup data-n=\"4399\">706</sup> כו' שאין מתעורר להתחזק בעבודה האלקי' כלל. והיינו מה שלא יתן אדם אל לבו כלל וכלל להיות לו התעוררו' אף מעט במוחו ולבו בהתבוננו' אור האלקי בסובב וממלא בפנימיות שכלו, וכן לא ישים אל לבו להתפעל מזה כלל באהבה שבלב לדבקה בו ית' וכמ\"ש ישראל לא ידע<sup data-n=\"4400\">707</sup> עמי לא התבונ\"ן, פי' שלא ירצה לידע ולהתבונן מצד קרירות שלו שנתקררה דעתו ולבו בענין עבודת האלקי' לגמרי מצד שכל פנימי' לבו ודעתו בעומק נפשו אחוז וקשור רק בעניני",[["4395","702","<b>מרחוק הוי' נראה לי</b>: ירמי' לא, ב."],["4396","703","<b>הוי' סובב ואלקי' בחי' ממלא</b>: ראה גם לעיל עג, ב. וש\"נ."],["4397","704","<b>כן בקדש חזיתיך הלואי</b>: תהלים סג, ג. ראה זהר תרומה קמ, סע\"א ואילך. לעיל פ' משפטים רפח, ב. חצר, ד. לקמן פ' ויקהל תז, ג. מאמרי אדה\"א ויקרא ח\"א ע' קה, וש\"נ. קונטרסים ע' שכה. וש\"נ. ש\"א כט, ב. ובהערה 26."],["4398","705","<b>רשפי' רשפי אש</b>: שה\"ש ח, ו. ראה לקמן שעא, ד. פ' ויקהל תז, ג. מאמרי אדה\"א בראשית ע' תקג. וש\"נ. ולהעיר מיומא יח, ב: שאינו דומה מי שיש לו כו'."],["4399","706","<b>אין קורא בשמך</b>: ישעי' סד, ו [ושם ואין — נסמן לעיל פ' בא קכה, ג]."],["4400","707","<b>ישראל לא ידע</b>: ישעי' א, ג."]]],[2300550651,"גופו כנ\"ל. אך א\"כ לא הי' מתפלל ולומד ועושה מצוה כלל, ואנו רואים שגם בטרדות הפרנסה וכל עניני עוה\"ז כנ\"ל, מ\"מ כל איש מישראל אפי' הפחות שבהם מתחזק בנפשו להתפלל כפי יכולתו בסידור שבחו של מקום כמו בפסוד\"ז ובברכת דיוצר אור ובק\"ש לכוין באחד וכן בתפלה, וכה\"ג יכול לקבוע עתים לתורה ועושה מצות הרבה ובפרט במצות צדקה ות\"ת לבניו וכה\"ג כידוע. וא\"כ ודאי יש בזה איזה רצון וחפץ הלב בהתעוררות בכל א' וא' לפום שיעורא דילי', ואיך אמר אין קורא בשמך כו'.\n<b>אך</b> צריך לומר בזה דגם שקורא בשמך בתפלה וק\"ש וכה\"ג אין זה מבחי' פנימי' כלל אלא רק בבחי' חיצוני' ואחוריים לבד, דהיינו בחיצוניות הרצון וחיצוניות הלב ביותר כמו שא' כי פנו אלי עורף<sup data-n=\"4401\">708</sup> ולא פנים כו', פי' כי פנו אל\"י שפונים אלי ממש אבל זהו בעורף לבד בבחי' חיצוניות ואחוריים דרצון ולב ומוח ולא בבחי' פנימי' כלל וכלל, וכמו שא' יען נגש העם הזה אלי אלי ממש נגשו בתפלה ועבודה האלקי', כמו ואותי יום יום ידרושון<sup data-n=\"4402\">709</sup> כמו בתפלה כו' ודעת דרכי יחפצון בלימוד בד\"ת כו' אבל רק בפיו ובשפתיו כבדונ\"י ולבו רחק ממני<sup data-n=\"4403\">710</sup> כו', כמו גם בפסוד\"ז וברכת השחר שגם שבפיו ושפתיו כבדוני בשבחים והלל וברכה והודאה כו', אבל לבו רחק בפנימי' לגמרי כי בחי' פנימי' הלב בעומק נפשו נתקשר בחיי גופניי' כל היום ובבואו לדרוש ה' בתפלה אין זה רק לצאת י\"ח בלבד ומדבר רק מן השפה ולחוץ שזהו רק בפיו ושפתיו כבדוני לבד בלא לב ומוח כלל. ועכ\"ז הרי יש בזה מעט רצון <span data-k=\"pg\">תצז</span> ּ והתעוררות הלב לעבודת ה' שעכ\"פ לא יקל ראשו בפר\"ע לגמרי שלא להתפלל ולהניח תפילין ולקרות ק\"ש כו', אלא מקבל ע\"ע ברצון לקיים מצות ה' בטו\"ת וק\"ש לצאת י\"ח עכ\"פ, וכן לסדר שבחו ש\"מ בפסוד\"ז כמוטל על העבד לאדון כו', רק שכל זה אינו בא מהתעוררות פנימית הלב והמוח רק בחיצוני' הרצון בקרירות גדולה. וזהו כי פנו אלי פי' אע\"פ שפונים אלי בעבודה האלקי' כאשר נגשי' בתפלה מ\"מ פנימיותם זה אינו אלא בבחי' עורף בחיצוניו' הרצון והלב ולא בפנים בפנימי' הרצון והלב כלל וכמ\"ש ולבו רחוק ממני לגמרי כנ\"ל וד\"ל.\n<b>ואמנם</b> מבואר במשל עמידה דב' בני אדם אב\"א שזהו בא מצד הריחוק לגמרי רק שאין בלבם אהבה לגמרי אף לא בחיצוני' הרצון והלב ע\"כ אינו מדבר עמו אף מן השפה ולחוץ בקרירות לצאת י\"ח לבד כנ\"ל, כי גם בחיצוניות הרצון יש רצון וחפץ עכ\"פ ורחוק הוא מן השנאה. אבל עיקר ענין אב\"א היינו מה שפונה עורף דוקא, שזהו פי' הפשוט דכי פנו אלי עורף שנסוגו אחור ופנו עורף ממש כו', ולא שהם פונים עכ\"פ בחיצוניות הרצון כנ\"ל במ\"ש בפיו ושפתיו כבדוני כו'. וזהו כמו בפורק עול מל' שמים מצד הטנאה שבלבו שמאס בדרכי הטוב",[["4401","708","<b>כי פנו אלי עורף</b>: ירמי' ב, כז."],["4402","709","<b>ואותי יום יום ידרושון</b>: ישעי' נח, ב."],["4403","710","<b>בפיו ובשפתיו. . ממני</b>: ישעי' כט, יג."]]],[2300550657,"כו' וחפץ לילך בשרירות לבו דוקא כבן סורר ומורה שאינו שומע בקול אביו שפונה עורף כו', וזהו כמו בב' בנ\"א שבלתי אוהבי' שבלתי יכולים לדבר פב\"פ כלל, וכמו גם בבוא שונאו אליו לקבל טובה ממנו ומוכרח להשפיע לו טובה אף בלתי רצון בלבו כלל רק מצד כדי שלא יעמוד אצלו משפיע לו מאחוריו כמאן דשדי בתר כתפוי<sup data-n=\"4404\">711</sup> כו' וכה\"ג, זהו בבחי' ריחוק אמיתי בלב עד שמחמתו יראה גם בגופו כן לפנות עורף זה מזה שזהו שנק' אב\"א כו'. והנה באמת אנו רואים שגם בזמן הגלות בעומק הטרדא ועומק ההתקשרות בלו\"נ<sup data-n=\"4405\">712</sup> בעניני העוה\"ז לא ימצא בישראל ענין הריחוק האמיתי מאלקים חיים שיסוגו אחור בפר\"ע ממש כמו בריחוק שמצד השנאה ח\"ו כי אין זה אפי' בקלים שבישראל, שהרי בעת צרתו יצעק אל ה' במרת נפשו ויתענה על חטאיו וגם מקבל עליו עול תורה ומצות ותפלה בכל יום ואינו סר ממצות ה' כלל, ואדרבה חזקים רובם ככולם במעשה המצות בפו\"מ וחביבים עליהם המצות בתוקף וחוזק גדול באופן שלא יסורו מהם כל הימים אפי' בנסיונות רבים, כמו שעמדו בנסיונות בימי אסתר ובימי חשמונאי ובניו וכה\"ג, שרבים מסרו נפשם על קדה\"ש וגם בנשים וטף כמו טבע בנפשם לחבב המצות בכל לב ונפש כו'. וא\"כ איך א' כי פנו אלי עורף כפשוטו, שאין זה רק בפורק עול מ\"ש לגמרי כמו ויאמרו לאל סור<sup data-n=\"4406\">713</sup> כו', ולא באלה חלק יעקב<sup data-n=\"4407\">714</sup> ח\"ו כי דורשים וחפצים בדרכי ה' בתו\"מ ומחזיקים בהם באמת דור אחר דור בלי שינוי כלל ויכולים לבא למס\"נ על שינוי הדת אפי' במנהג כו', וכן בתפלה ותפילי' וק\"ש ושבת ומילה וסוכה ולולב וכה\"ג בכל המצות אין איש מישראל שלא יקיים בלב שלם ומדריך בניו <span data-k=\"pg\">996</span> ּ לת\"ת ומצות ודרך הישר באמת ובאמונה ואפי' בקלים שעוברים ג\"כ על איזה ל\"ת מצד תאותם ופר\"ע מ\"מ חזק הוא בכל המצות כידוע.\n<b>אך</b> הענין הוא דמ\"ש כי פנו אלי עורף כו' זהו מדבר בזמן שעבדו ישראל כל מיני ע\"ז ופרקו עול מ\"ש לגמרי כמו בבית ראשון שהי' בהם עון ע\"ז וג\"ע וש\"ד<sup data-n=\"4408\">715</sup> וכתיב אותי עזבו<sup data-n=\"4409\">716</sup> כו', אבל בבית שני היו עוסקים בתו\"מ ותפלה רק עון שנאת חנם<sup data-n=\"4410\">717</sup> לבד. וגם עכשיו בזמן הגלות כן דתומ\"צ ותפלה נוהג בישראל כמו טבע בנפשם (רק שנאת חנם ומלשינות ופר\"ע באנשים ריקי' במיעוטא דמיעוטא לפ\"ע רוב ההמון כו'), ועכ\"ז א' ע\"ז יען נגש העם הזה אלי שנגשו בתפלה בפיו ושפתיו כבדוני כו' שזהו רק בקרירות מן השפה ולחוץ ולבו רחוק ולא רחוק ממש בפר\"ע במזיד אלא שלבו בל עמו בדברו השבח והלל או בק\"ש ותפלה אינו מקירת הלב. ואמנם בחיצוניות הלב מתעורר עכ\"פ ומקבל עומ\"ש ברצון חיצוני עכ\"פ להיות סו\"מ וע\"ט כל היום, וזהו כל חיזוק ההמון במצות בפו\"מ מגדול ועד קטן כנ\"ל גם בלא פנימי' הלב בכוונה ורעותא דלבא רק שמקיים",[["4404","711","<b>כמאן דשדי בתר כתפוי</b>: ראה תניא פכ\"ב."],["4405","712","<b>בלו\"נ</b>: בלב ונפש."],["4406","713","<b>ויאמרו לאל סור</b>: איוב כא, יד."],["4407","714","<b>ולא באלה חלק יעקב</b>: ע\"פ ירמי' י, טז. נא, יט."],["4408","715","<b>בבית ראשון. . ע\"ז וג\"ע וש\"ד</b>: יומא ט, ב."],["4409","716","<b>אותי עזבו</b>: ירמי' ב, יג."],["4410","717","<b>בבית שני. . שנאת חנם</b>: יומא שם. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רכד. וש\"נ."]]],[2300550663,"בפו\"מ לצאת י\"ח בעול מ\"ש עכ\"פ כו'. ומה בכך שאין בזה פנימי' הכוונה הלא יש מאן דאמר דמצות אין צריכות כוונה<sup data-n=\"4411\">718</sup> (אפי' כוונה לצאת י\"ח), ועכ\"פ גם בלא כוונת הלב העיקר הוא המעשה מצד עצמה וכמו שא' שמואל לשאול החפץ לה' בעולות וזבחים<sup data-n=\"4412\">719</sup> שזהו כמו העלאת פנימי' הלב בתפלה כו' כ\"א שמוע מזבח טוב כו' וכל יסוד התורה אינו רק על השמיעה לעשות המצו' בפו\"מ לבד וכמו והי' אם שמוע<sup data-n=\"4413\">720</sup> כו' כידוע. אך הנה באמת אם הי' ענין עסק המצות בכלל ישראל בכולם עד\"ז רק מצד קבלת עומ\"ש באוי\"ר עכ\"פ רק שהוא בחיצוניות ובקרירות אין זה בחי' אב\"א כפנו עורף ממש, שהרי עמידה זו פב\"פ רק שאין זה בפנימי' הלב ולא יש מס\"נ באהבה רבה לפנימי' שם הוי' רק לענין מעשה לבד (וזהו כמו אחרי ה' תלכו אחרי ה' לבד כו' משא\"כ את פניך הוי' אבקש וכמו התהלך לפני<sup data-n=\"4414\">721</sup> כו' וכמו ביו\"כ לפני הוי' תטהרו<sup data-n=\"4415\">722</sup> כו' וכה\"ג).\n<b>אך</b> מ\"ש ותהי יראתם אותי מצות אנשים מלומדה<sup data-n=\"4416\">723</sup> כו' זהו רק כמו מצד הרגילות שמלומדים במעשה זו דמצות מאבותיהם שלמדום והרגילום בזה מקטנותם, וכל רגילות עושה טבע שני<sup data-n=\"4417\">724</sup> כידוע כמו חנוך לנער<sup data-n=\"4418\">725</sup> כו' עד שקשה לו לפרוש מהדרך הזה כו', כמו שאוהב הדבר הזה בעצם בטבע ראשון כו'. וזהו שנק' מצות אנשים ולא מצות הוי' מצד קבלת עומ\"ש ברצון מצד עצם יהדותו שנק' טבע ראשון כמו מצד הירושה מאבות שהאמינו בה' אמונה פשוטה ועצמי' וטבעי', אלא רק מצד הלימוד והרגילות שהורגלו במצות כמו מעשה אבותיהם בידיהם<sup data-n=\"4419\">726</sup> כו'. וכמו שרואים קצת בכמה אנשים שחביבים עליהם תו\"מ מצד טבע הרגילות מנעוריהם שהרגילום והרגיל א\"ע בזה שנק' מלומדה בטבע שני כו', ולא מצד ירא' ואהבת אלקי'. וז\"ש ותהי יראת\"ם אותי גם ביראת אלקי' מלומד\"ה יראה זו שיהי' <span data-k=\"pg\">תצח</span> ּ ירא אלקים מצות אנשים (ואע\"פ שא' למען תלמד ליראה את ה'<sup data-n=\"4420\">727</sup>, זהו בלימוד בתורה ותלמידי חכמי' המלמדי' יראת אלקי' מצד עצמו' אלקו' שמכניסי' בלב המקבלי' מעט מעט כחנוך לנער כו'. וכמו אשר יצוה את בניו<sup data-n=\"4421\">728</sup> ושמרו דרך הוי' כו' ונק' לימוד\"י הו\"י'<sup data-n=\"4422\">729</sup> כו' כמ\"ש במ\"א, שזהו כמו אומן שמלמד מלאכת אומנות לבנו ותלמידו שמרגילו מעט מעט עד שמכניס בלבו ונקנה אצלו כטבעי'. כך האמונה האלקי' ואוי\"ר האלקי' במצות נטבע ונמשך בנש\"י מאבות<sup data-n=\"4423\">730</sup> כמו האומן את היונק<sup data-n=\"4424\">731</sup> וכמו ויהי אומן<sup data-n=\"4425\">732</sup> כו', ולכך נק' האבות אומני\"ם<sup data-n=\"4426\">733</sup> כו'. משא\"כ רגילות זו דמצות",[["4411","718","<b>דמצות אין צריכות כוונה</b>: ערובין צה, סע\"ב. ראה שו\"ע אדה\"ז הל' ק\"ש ס\"ס, ס\"ה. ראה גם מאמרי אדה\"א נ\"ך ע' א ואילך. וש\"נ. שע\"ת יב, ב ובהערה 12. ש\"א יא, א. לעיל פ' בשלח קנו, ב ואילך. קסט, ג. לקמן פ' ויקהל תטז, א."],["4412","719","<b>החפץ לה' בעולות וזבחים</b>: שמו\"א טו, כב."],["4413","720","<b>והי' אם שמוע</b>: עקב יא, יג."],["4414","721","<b>התהלך לפני</b>: לך יז, א."],["4415","722","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["4416","723","<b>ותהי יראתם אותי מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680208\" data-slug=\"torat-chaim\" data-id=\"2300680208\">תו\"ח ויחי רמב, ג</a> הערה 44."],["4417","724","<b>רגילות עושה טבע שני</b>: ראה דרשות ופירושי רבינו יונה גירונדי פ' תולדות (ירושלים תש\"מ) ע' מט. חיבור התשובה להמאירי בשם חכמי המוסר מאמר א ספ\"ג (ע' 70). רבינו בחיי הקדמה לפ' פינחס ע' קפו (טבע). אור תורה תולדות כו, יג (קה\"ת יג, ב) (טבע). פרי הארץ להרמ\"מ מויטעבסק פ' קרח ע' כה (טבע). מאמרי אדה\"א שמות ח\"ב ע' תרכ. וש\"נ."],["4418","725","<b>חנוך לנער</b>: משלי כב, ו."],["4419","726","<b>מעשה אבותיהם בידיהם</b>: ברכות ז, א."],["4420","727","<b>למען תלמד ליראה את ה'</b>: פ' ראה יד, כג."],["4421","728","<b>אשר יצוה את בניו</b>: וירא יח, יט [בדילוג]."],["4422","729","<b>לימוד\"י הו\"י'</b>: ישעי' נד, יג. ראה גם לעיל פ' שמות יב, ב. שע\"ת עט, ג."],["4423","730","<b>האמונה. . בנש\"י מאבות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא</a> פי\"ח ופל\"ג. לעיל פ' בא קטז, ג. וש\"נ."],["4424","731","<b>האומן את היונק</b>: בהעלותך יא, יב."],["4425","732","<b>ויהי אומן</b>: אסתר ב, ז."],["4426","733","<b>נק' האבות אומני\"ם</b>: ראה גם לעיל קיח, ב. וש\"נ."]]],[2300550669,"אנשים מלומדה מאבות לבנים אחריהם אינו ענין יראת אלקי' ואמונתו ותו\"מ לקיים רצונו כו', רק עצם המעשה לבד שיהי' ישר דרכו, כמו בפיו ושפתיו בתפלה וגם במצות שיהי' נאה וטוב לאלקי' ואנשי', ויהי' לו תפארת מן האדם להחזיקו לאיש ישר וטוב כו'. וכמו למען שמי יכבד ה'<sup data-n=\"4427\">734</sup> כו', וזהו למראה לבד (אן שְטֶעל) כי האדם יראה לעינים<sup data-n=\"4428\">735</sup> כו' (שאינו עולה למעלה כלל והי' זמן רב שלא הועלו מצות מעשיות<sup data-n=\"4429\">736</sup> דכנ\"י למעלה כלל) (וגם האוהבי' ד\"ת ושוקדי' עלי' רק מצד התורה עצמה לבד ולא מצד אלקות שבה כלל וכלל כו').\n<b>והנה</b> לפי ב' הפירושי' הנ\"ל בפנו אלי עורף בין בחיצוניות ואחוריי' דרצון הלב שנק' עורף כמו בפיו ושפתיו כבדוני וכן במצות רק לצאת י\"ח לבד כנ\"ל, ובין גם במצות אנשי' מלומדה הנ\"ל שאינו רק מצד הלימוד והרגילות שאין בזה אפי' חיצוניות הלב רק כמו אב\"א ממש, הרי אין זה כמו שפונה עורף מצד השנאה ופר\"ע ממש רק שנתרוקן האור האלקי במעשה המצות כאלה, וגם בעסק התורה ותפלה בלי נשאר רושם פנימיות אור וחיות אלקי בנשמות שיאמר ע\"ז וחי בהם כו'. אבל מ\"מ המעשה דמצות מצד עצמן והדיבור בד\"ת ותפלה קיימי' לבד ויכולים לעלות למעלה לפרקי' (כמו בשבתות ויו\"ט ותפלת יריאי'<sup data-n=\"4430\">*737</sup> ) או תפילת עצמו ותשובה שלימה שיעשה לפרקים יעלה הכל מכל מה שעסק בתו\"מ ותפלה כידוע), וא\"צ בירור ותיקון בגיהנם כדברים בטילים ומעשים לא טובים. כי ד\"ת ומצות אינם בטילים מצד עצמן כו', אע\"פ שאין בהם שום כוונה כלל אף לצאת י\"ח, רק רגילות ולהתייהר ככת חנפי' ומתייהרי' שרוצים לקנות שם ועושים צדקה גדולה ומאריכים בתפלה בצביעות ושוקדים בתורה, גוף הד\"ת ומצות ותפלה קיימין ולא יתבטל אפי' אות א' ולא מעשה אחד. וראי' מן הרשעים גמורי' שעוברי' על כמה לאוין וכרת בפרהסיא מ\"מ המצו' ותורה וצדקה וכה\"ג שלהם לא יבוטל ויש להם חלק לעוה\"ב דאפי' פושעי ישראל מלאים מצות<sup data-n=\"4431\">737</sup> כו' כידוע.\n<b>ולפי\"ז</b> יובן ג\"כ בהתעוררות המשפיע למקבל באתעדל\"ע מהקב\"ה לכנ\"י שהיא כמים הפנים לפנים<sup data-n=\"4432\">738</sup> כן לב האדם העליון לאדם התחתון דכנ\"י זהו ג\"כ בבחי' חיצוני' ואחוריי' לבד, דהיינו מה <span data-k=\"pg\">998</span> ּ שלא יאיר להם מבחי' פנימי' דשם הוי' דסובב כו' ואין גילוי שכינה בכלל ולא בפרט בכל מעשיהם",[["4427","734","<b>למען שמי יכבד ה'</b>: ישעי' סו, ה."],["4428","735","<b>כי האדם יראה לעינים</b>: שמו\"א טז, ז."],["4429","736","<b>שאינו עולה למעלה. . מצות מעשיות</b>: ראה גם מאמרי אדה\"א דרושי חתונה ח\"ב ע' תמח. קונטרסים ע' כז. וש\"נ. ספר השיחות תרצ\"ו ס\"ע 150 ואילך."],["4430","*737","<b>ותפלת יראי'</b>: ראה גם לקמן שעד, ד."],["4431","737","<b>פושעי ישראל מלאים מצות</b>: ערובין יט, א."],["4432","738","<b>כמים הפנים לפנים</b>: נסמן לעיל פ' משפטים רצ, ב."]]],[2300550674,"בתו\"מ וצדקה ותפלה, רק כפי אופן העלאה שלהם בחיצוני' בתפלה ותו\"מ עכ\"פ ודאי גם הוא ית' יתעורר אליהם שזהו בבחי' חיצוני' הרצון וחכמה ומדות דשם הוי', וחיצוני' זו יש בה הארת הרצון העליון וגם חכמה ומדות כו' רק שאין בזה בחי' פנימיות כלל. ולזאת לא יקום לעת צרתם להושיעם או לפקח כ\"כ בחיי פרנסתם וכה\"ג מצד שנסתלק פנימיות ההשגחה מפנימיות הלב דאדם העליון כו' מטעם שאין קורא בשמך בפנימיות. אך כשצועקי' אליו בעת צרתם, או שירבו עליהם מקטרגי' ביותר לכלותם ברוחניות ובגשמיות אזי ודאי מתעורר להחזיק בם נגד השונא הרודפם ולהצילם, כמו עמדת להם בעת צרתם<sup data-n=\"4433\">739</sup> וכמו הנה ה' עומד לריב עמים<sup data-n=\"4434\">740</sup> כו' ונק' גבור ורב להושיע וכמ\"ש לא מאסתים<sup data-n=\"4435\">741</sup> כו' לכלותם כו'. דאם הי' לו שנאה עליהם הי' מואס בהם לכלותם בחרון אפו כמו שהי' בזמני' הקדמוני' בחורבן בית ראשון ובית שני וכה\"ג, אבל בהיותם בגלו' בארץ כו' לא מאסתים כו' ועומד להצילם מצרתם אע\"פ שאין לו אהבה פנימי' כלל וכלל כנ\"ל וד\"ל (משא\"כ בפוני' עורף לגמרי בפר\"ע במזיד לעבור על ד\"ת למאוס בדרך ה' בתו\"מ, כמו האפיקורסי' ומיני' ועברייני' וכרשעים גמורי' שאינם עושים תשובה לעולם שכפי מעשיהם ולבבם שנסוג אחור ממש, כך מלמעלה נמשך עליהם שנאה וכמו ומשלם לשונאיו אל פניו להאבידו<sup data-n=\"4436\">742</sup> בעוה\"ב והוא שגם בשעה שרוצה ה' להשפיע להם בעוה\"ז כרשע וטוב לו כדי להאבידו כו' משפיע להם כמאן דשדי בתר כתפוי כו' כנ\"ל) (אבל כל העניני השפע האלקית בעוה\"ז בכל חלקי דצח\"מ שנותן לחם לכל בשר כל\"ח<sup data-n=\"4437\">743</sup> כו' ולכל בריא' בפרנסתו זהו חסד חנם שזן את העולם בחסד כו' אע\"פ שאינם ראוי' כלל, ואע\"פ שיש כמה רשעי' שחוטאי' לפניו זן ברחמי' לפמשוה\"ד כו').\n<b>והנה</b> מבואר למעלה שיש אופן גם בבחי' אב\"א שיהיו עומדי' בקירוב ודיבוק זע\"ז בכתף לכתף ממש אעפ\"י שאין בזה שום צד קירוב בפנימיות מאחר שפנו עורף ולא פנים ואף בחיצוני' אין רצון וחפץ כלל כו', מ\"מ מאחר שסמוכי' ודבוקי' זא\"ז באחוריי' וכתף לפי שעומדי' בקירוב מקום או אף ע\"י כותל א' מפסיק ביניהם ולא נתרחקו לגמרי יוכלו בקל לחזור פב\"פ בהתעוררות הרצון מזה לזה כו', וגם עצם ענין העמידה זו נקרא קירוב ויחוד בחיצוני' ואחוריי' עכ\"פ כנ\"ל (וראי' מדו פרצופי' כו' כנ\"ל). ויובן מזה בנמשל שבמעשה המצות כמצות אנשים מלומדה וכה\"ג שאין קירוב ברצון ומדות אפי' בחיצוני' וכמו שפנו עורף כו', מ\"מ נק' עמידה זו אף בבחי' אב\"א עמידה שבקירוב, דגם שכמים <span data-k=\"pg\">תצט</span> ּ הפנים אל פנים כו' מסלק מהם כל הפנימי', עכ\"ז בחי' אחוריי' וחיצוני' דשם הוי' נמשך בקירוב",[["4433","739","<b>עמדת להם בעת צרתם</b>: נוסח ועל הנסים דחנוכה."],["4434","740","<b>הנה ה' עומד לריב עמים</b>: ראה ישעי' ג, יג. הנסמן לעיל פ' בשלח רלב, ג."],["4435","741","<b>לא מאסתים</b>: בחוקותי כו, מד."],["4436","742","<b>ומשלם לשונאיו אל פניו להאבידו</b>: ואתחנן ז, י."],["4437","743","<b>שנותן לחם לכל בשר כל\"ח</b>: תהלים קלו, כה."]]],[2300550679,"בחיצוני' ואחוריי' דמצות שלהם שנעשו בפו\"מ עכ\"פ שאין המעשה והדיבור האלקי בתו\"מ בטל לעולם כנ\"ל (וא\"צ טבילה בנה\"ד כדברים בטלים ולא גיהנם כמעשה הרע דק\"נ כו'). א\"כ יש השראת גילוי אור אלקי מצומצם עכ\"פ בדיבור ומעשה דתו\"מ ותפלה שלהם בקירוב ממש, כי דבר ה' מדברי' בד\"ת אף שהוא בדרך רגילות ומצות עושי' כהלכתן למעשה כטו\"ת וצדקה וכה\"ג וכן שבת ומילה וכל המצות שבגוף עצם המעשה מתלבש בהם שם הוי' בהעלם רק שאינו בגילוי בנפשם כלל וכלל כנ\"ל וד\"ל. וא\"כ יובן מזה שיכול להיות בחי' יח\"ע דקוב\"ה ושכינתי' שהוא הוי' ואלקי' שנעשה במצות הוי' בצדיקי' שעושי' בכוונה ורעותא דלבא, יח\"ע זה נעשה גם במצות אנשים כו' שאין בהם כוונה כלל וכלל כנ\"ל. רק שיחוד זה אינו נק' יחוד פב\"פ למעלה (כזו\"נ שהן קוב\"ה וכנ\"י שנק' שכינה למעלה כו') אלא נק' יחוד חיצוני' דאב\"א כמו שמפסיק מחיצה בין המשפיע למקבל ואינם רואים זא\"ז כלל, אבל עומדי' בקירוב זא\"ז ממש כנ\"ל. וכך גילוי אלקות בתו\"מ בתפלה עכשיו בהעלם גדול כנ\"ל, אבל הוא בקירוב וסמיכות לגבי המקבלים שהם כנ\"י בד\"ת ותו\"מ שלהן ממש כנ\"ל. וכן גם בנ\"י עומדי' בקירוב להוי' שבתו\"מ המלובש גם בנשמתם בעת עסקם בתו\"מ, רק שזהו עמידה שבאחוריי' וחיצוני' דעורף ולא פנים בענין מחיצה של ברזל<sup data-n=\"4438\">744</sup> מפסקת בין ישראל לאביהם שבשמים ע\"י העוונות שפנו עורף כו'. ועכ\"ז א' הנה זה עומד אחר כתלינו<sup data-n=\"4439\">745</sup> מציץ מן החרכים כו', פי' כותלינו זה נעשה בחי' מחיצה מבדלת מן העוונות כנ\"ל ועכ\"ז לא נסתלק האור האלקי אדרבה עומד אחר כתלינ\"ו זה בקירוב רק שמסלק פנימיותו מאתם. ומ\"מ מחזיר פניו גם בכתלינו ומציץ מן החרכים כו' חרכים הללו שנעשו ע\"י בע\"ת<sup data-n=\"4440\">*746</sup> וצ\"ג כו' כמ\"ש במ\"א, וכמ\"ש דומה דודי לצבי<sup data-n=\"4441\">746</sup> שמחזיר ראשו לאחורי\"ו להתלבש בבחי' אחוריי' וחיצוני' שלו המלובש בתו\"מ שלמטה כמ\"ש במ\"א וד\"ל. וא\"כ הרי יכול להיות החזרת פנים בפנים ממש ע\"י עמידה זו דאב\"א בקירוב זע\"ז ע\"ד הנ\"ל שעומד אחר כתלינו כו', כך יחזרו ישראל פניהם בהתעוררו' פנימי' המוח והלב לפנימי' דהוי' כנ\"ל. והיינו ע\"י עסק בתו\"מ בבחי' אב\"א כמו בזמן הגלות, לפי שגם גופו של קירוב זה שמתייחדי' בתו\"מ בבחי' אב\"א נק' יחוד ולא ריחוק אמיתי, וכמו שאומרים לשם יחוד כו' על כל מעשה המצות<sup data-n=\"4442\">747</sup> אע\"פ שנעשי' בלא כוונה כלל (וכמו שיש זווג אב\"א וכד\"ו פרצופי' כו' כנ\"ל, ולפי שהחיצוני' גוררת גם הפנימי' לפי שנגררת אחר הפנימי' כעורף הנגרר אחר הפנים כו' (וראי' מיציאת מצרים שהיו ישראל בקטנות המוחין מאד כתינוק כמ\"ש זכרתי לך חסד נעוריך<sup data-n=\"4443\">748</sup> לכתך אחרי לבד ומזה נעשה החזרת פב\"פ במ\"ת משום דהא בהא תליא",[["4438","744","<b>מחיצה של ברזל</b>: ע\"פ פסחים פה, ב. ראה ברכות לב, ב. אוה\"ת תצוה ע' א'תרצא."],["4439","745","<b>הנה זה עומד אחר כתלינו</b>: שה\"ש ב, ט [בדילוג]. ראה לקמן שסה, א. תו\"א מג\"א צד, ג. מאמרי אדה\"א נ\"ך ע' תח ואילך."],["4440","*746","<b>חרכים. . ע\"י בע\"ת</b>: ראה גם לקמן שנז, א. שסט, ב ואילך."],["4441","746","<b>דומה דודי לצבי</b>: התחלת הכתוב הנה זה עומד. ראה מאמרי אדה\"א שם ע' תג ואילך."],["4442","747","<b>לשם יחוד כו' על כל מעשה המצות</b>: ראה פע\"ח (שער הזמירות) ש\"ז, ספ\"ה. ספר תוצאות חיים לבעל ראשית חכמה (ירושלים תדש\"מ ע' שטו). לקמן פ' פקודי תמד, א. תנה, ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצב ובהנסמן במ\"מ לשם. מאמרי אדה\"א הנחות תקע\"ז ע' קצב. וש\"נ. שע\"ת קלד, ג."],["4443","748","<b>זכרתי לך חסד נעוריך</b>: ירמי' ב, ב."]]],[2300550684,"ומטעם הנ\"ל וד\"ל) (וכמ\"ש למעלה מטעם דע\"כ יעזוב כו' לפי שהיתה עצם מעצמי כו' כי מאיש לוקחה זאת, כך כנ\"י שהיא בחי' המל' נבנית בפרצוף שלם בע\"ס או\"כ ע\"י תו\"מ בחיצוני' שנק' עצם מעצמי ובשר <span data-k=\"pg\">1000</span> ּ כו' תושב\"כ ושבע\"פ כו'). ונמצא מובן מכ\"ז דגם שנש\"י עומדי' אב\"א באחוריי' וחיצוני' בתפלה כמו בפיו מן השפה כו' ולבו רחק מצד התקשרות כל הפנימי' בצרכי גופם, מ\"מ ע\"י המצות שלהם מצד עצמן לבד אף בלא כוונה כלל כנ\"ל נחזרים בבחי' פב\"פ כנ\"ל (וזהו כל עיקר ענין דפ' זו ואתה תצוה כו', שע\"י משה שיקחו אליך שמן זית זך ממעשה המצות שיתקן אותם ע\"י בחי' לב נשבר דוקא שנק' כתית (כמשי\"ת) יחזיר אותם פב\"פ להעלות נר תמיד למעלה מנר מצוה שלהם בבחי' פב\"פ דוקא כמ\"ש אל מול פני כו'. וזה הכח להחזיר לבנ\"י במצות שלהם מאב\"א להיות בבחי' פב\"פ א\"א כ\"א ע\"י משה דוקא (כמשי\"ת), ומתורץ בזה כל הנ\"ל כמשי\"ת).\n<b>והנה</b> להבין טעם הענין בתוס' ביאור יש להקדים תחלה ענין א' בביאור ענין הידוע בב' מדרגות דסובב כ\"ע וממלא כ\"ע שזהו שם הוי' ושם אלקים בכלל כידוע, ונק' ג\"כ בדרך כלל בב' מדרגות דהעלם וגילוי ובלשון הזהר עלמא דאתכסיא ועלמא דאתגלייא, וכמו בי\"ה הוי' צור עולמים<sup data-n=\"4444\">749</sup> ב' עולמי' וזהו ברוך ה' כו' מן העולם ועד העולם<sup data-n=\"4445\">750</sup> כידוע. והיינו מבחי' ההעלם לגילוי שזהו מבחי' סובב לבחי' ממלא דהיינו מבחי' מקיף הכללי לאו\"פ הכללי, דאו\"מ הכללי נק' סובב כ\"ע כמו שמקיף וסובב מלמעלה למטה כא' כמו עיגול כדורי דשמים שמקיפי' וסובבי' לארץ למעלה ולמטה דשוי' בו מעלה ומטה לגמרי וכמו ומתחת זרועות עולם<sup data-n=\"4446\">751</sup> כו'. ובבחי' או\"פ הכללי שנק' ממלא כ\"ע זהו בחי' עלמא דאתגלייא בכלל שבא האור ושפע האלקי' בבחי' גילוי אור וחיות ממש בעולמות דבי\"ע להחיותם מאין ליש כמו ע\"י אותיות הדיבור דיו\"ד מאמרות עד עוה\"ז השפל ממש כו'. ולכך נמשל בבחי' סובב וממלא לבחי' העלם וגילוי דמחשבה ודיבור<sup data-n=\"4447\">752</sup> באדם דהמח' הוא בהעלם במוח והדיבור בא בגילוי בצירופי אותיות רבים ומחולקי' זה מזה, וכל מה שנסקר במח' בהעלם בסקירה א' נעשה הגילוי מזה בדיבור בפרטי פרטיות בצירופי' רבים כל א' וא'. ונמצא שזהו כמו בחי' הכלל אל הפרט דכל מה שבבחי' כלל נכלל הכל כא' ברגע א' מבלי קדימה מראש לסוף כלל בא אח\"כ בהתחלקות חלקים רבים בגילוי בפרט כל א' וא' בפ\"ע בסדר והדרגה דוקא כידוע, וכמו הרוצה לבנות בנין שעולה במחשבתו ורצונו בכללות כל מעשה הבנין מראשו לסופו כא' ממש ובהתגלות הרצון והמח' הזאת למעשה ע\"י הדיבור הרי יתחלק בסדר והדרגה כל דבור ומעשה בפ\"ע מעליון לתחתון כל פרט ופרט מיוחד בפ\"ע, ועכ\"ז כולם היו כלולים כא' ממש במח' ורצון הכללי בהעלם טרם",[["4444","749","<b>בי\"ה הוי' צור עולמים</b>: ישעי' כו, ד. מנחות כט, ב."],["4445","750","<b>ברוך ה'. . ועד העולם</b>: ראה גם לעיל פ' שמות יח, ג. וש\"נ."],["4446","751","<b>ומתחת זרועות עולם</b>: ברכה לג, כז. ראה גם לעיל פ' וארא נה, ד. וש\"נ."],["4447","752","<b>סובב וממלא. . דמחשבה ודיבור</b>: ראה שער היחוד והאמונה פי\"א. לעיל פ' בשלח קמג, ד. וש\"נ."]]],[2300550689,"שגילה רצונו בדיבור ומעשה ואם אין כלל אין פרט כו'. וכך יובן למעלה בהפרש שבין ב' מדרגות הנ\"ל דהעלם וגילוי דמקיף הכללי דסובב כ\"ע זהו כשעלה במח' ורצון הפשוט בכללות לכל ההשתל' שנסקר הכל כא' מג\"ע העליון דבריאה בשוה עם הסוף דדצ\"ח דעשי' ולמטה מטה כא', וכמו שאו' ברוך שאמר במחשבה הכללי'<sup data-n=\"4448\">753</sup> והי' העולם בכלל כולל לכל וי\"ו אלפי שני' בזמן ומקום ולעליונים ותחתוני' בשוה ממש ראש וסוף כא' כעיגול השמים המקיף למעלה <span data-k=\"pg\">תק</span> ּ ולמטה בשוה ממש. ואח\"כ יצא לגילוי בבחי' או\"פ הכללי דממלא כ\"ע בדרך התחלקות פרטיות ביו\"ד מאמרות בצירופי אותיות מראש לסוף בסדר והדרגה דוקא בכל דיבור ומעשה מיוחד מח' ורצון בפרט עד שיש הפרש גדול בין עולם העליון יותר כג\"ע העליון דבריאה בין עוה\"ז השפל מכולם כו' וד\"ל.\n<b>ויובן</b> זה יותר בביאור ממשל החיות של הנפש הרוחני' בחומר גופו הגשמי' שיש בזה ב' מדרגות כידוע, א' מה שהנפש הזאת מלאה בגוף בבחי' גילוי אור וחיות ממש בכל האברי' מראש לרגל ע\"י הגידים ודם ובשר הממוזג בכל אבר פנימי וחיצוני ממוח שבראש עד צפורני הרגל כנ\"ל. והב' מדרגה גבוה מזו והיינו מה שהנפש בבחי' העלם וסתימות מן הגוף בלתי נגלה מעצמות הנפש בה כלום שזהו שנק' מקיף וסובב לכל קומה דאדם (ונק' צלם או מזלא כמו אך בצלם יתהלך איש<sup data-n=\"4449\">754</sup> כידוע, ויש ב' מקיפים דחי' ויחידה ומקיף דחי' שהוא למ\"ד דצלם פועל בגוף מן ההעלם לגילוי החיות לפרקי' אע\"פ שהיא בהעלם ומקיף כמו דמזלי' חזי<sup data-n=\"4450\">755</sup> ונופל בפחד כו' (כמ\"ש במ\"א). ומובן מזה עכ\"פ שעיקר ההפרש בין ב' מדרגות הנ\"ל בנפש וגוף, שבחי' גילוי האור וחיות דאו\"פ מתחלק הוא בפרטי פרטיות בכל האברי' בכל א' לפי מזגו ותכונתו דוקא ובא בהם אור וחיות הצורה הרוחניות בהדרגה וסדר מעליון לתחתון, כמו ממוח שבראש שהוא בתכלית העילוי ברוחניות כמו להשכיל כל שכל דק ועמוק כו' ויורד האור הרוחני ומשתלשל ויורד בירידת המדרגות כ\"כ עד שבסוף הקומה שהוא הרגל שם החיות והצורה בקטנות הערך מאד שהוא רק כח ההילוך בפועל תנועה גשמי' לבד, ומשם הולך האור ועולה מלמטה למעלה כמו מרגל לירך ושוק שיש בהם חיות דק יותר מן החיות הגס שבעקביי', ולמעלה יותר כמו בידים יש בהם הפעולה הדקה יותר כמלאכת מחשבת כאריגה וכתיבה ורמז לחכמה שמרמז ביד ומורה באצבע, וכה\"ג עולה יותר לראי' העין וריח החוטם ושמיעה ודבור שכולם בפנים דוקא עד מוח שבראש (וכן באברי' הפנימי' הולך כסדר מעליון לתחתון ממוח ללב ומלב לכבד ובני מעיים כו'). אבל בבחי' ההעלם דמקיף דנפש על אברי הגוף הנ\"ל הרי אין חילוק כלל בין מוח שבראש בגילוי השכל הרוחני או המח' ורצון",[["4448","753","<b>ברוך שאמר במחשבה הכללי'</b>: נוסח ברוך שאמר. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670502\" data-slug=\"torat-chaim\" data-id=\"2300670502\">תורת חיים נח עג, א</a> ובהנסמן במראי מקומות לשם."],["4449","754","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז. ראה מאמרי אדה\"א דברים ח\"ב ע' תצח ואילך (ובהנסמן בריש המאמר שם)."],["4450","755","<b>דמזלי' חזי</b>: מגילה ג, א."]]],[2300550694,"הרוחני שבמוח להיותר אחרון שהוא ההילוך ברגל וחיצוניות הצמיחה דצפורן וכה\"ג מאחר שאור מקיף זה מושלל ומובדל בערך לגמרי מכל האור וחיות הנמשך באברי הגוף כנ\"ל ע\"כ ראש ורגל שוין בו ממש כו' וד\"ל.\n<b>אך</b> הנה אנו רואים דבר פלא ביותר והוא דודאי לפי אופן של בחי' גילוי האור וחיות דנפש באברי' שבא בהתחלקות והדרגה א\"א לומר שיהי' מציאות שכל ומחשבה הרוחניות רק במוח שמוכן לקבל צורה זו דוקא, אבל לא באבר אחר זולתו כמו אבר העין שמוכן רק לראי' ולא לשכל ומחשבה והיד למלאכה והרגל רק להילוך, וא\"א לומר שיקבלו היד והרגל צורת השכל ומח' שבמוח להיות בהן מהות מחשבה ורצון כי ערך חיותם גס הרבה יותר מערך חיות המוח שמסוגל לדקות המח' ושכל שהן גידים דקים שבמוח כו'. אמנם עכ\"ז אנו רואים בחוש שנמצא בהכרח <span data-k=\"pg\">1002</span> ּ ממציאות דקות הרוחניות דמחשבה ורצון שבמוח גם ברגל וכן ביד, שהרי אנו רואי' שמיד שיעלה ברצונו ומח' הרוחניות שבמוחו להניע הרגל להילוך מיד ינוע הרגל בלי שהיי' ועיכוב כלל וכלל (ואעפ\"י שיש מציאות כח התנועה בגידי הרגל מצד עצמן גם בלא מח' ורצון שבמוח כמו שיניע היד ורגל בשינה בלי בחירה ברצון כלל, זהו רק תנועה חיונית ונפשיות כשאר בע\"ח מצד גידי הדם כו'. אבל מה שמניע תנועה בידו ורגלו באופן מיוחד ע\"פ רצונו ומחשבתו שעולה במוחו דוקא זהו שנק' תנועה רצונית דוקא שנמשך ע\"י גידי המוח עורקי' דקים מאד שנק' נערוי\"ן כידוע בס' הרפואה. וראי' מחולי המאניע<sup data-n=\"4451\">756</sup> שהוא הסתלקות גידי הרצון נעשה כאבן דומם בלי תנועה כלל אע\"פ שיש בו כל החיות בדם בשלימות). והי' מהראוי שיהי' שהיי' זמן מה בזה משעת העלי' זו דמח' במוח עד שנשתלשלה וירדה לרגל להניע' כפי פעולתו הגשמי' כי משכן דקות המח' אינו רק במוח ולא ברגל כלל כנ\"ל, וירידה כזאת ממוח שבראש במחשבה ורצון זה הרוחני שילך דרך כל צינורות הקומה ממוח ועד הרגל ודאי צריך שיהוי ועיכוב זמן מה עכ\"פ, ואנו רואים שאין שהי' ועיכוב כלל וכלל בזה, אלא מיד שעולה במוח המחשבה ורצון להילוך ברגל ולפעול מלאכה ביד מיד עושה ופועל בהילוך או מלאכה גשמי' שאין לה ערוך כלל לגבי רוחני' של המחשבה שבמוח ונקשרים כא' ממש ומהיכן נמצא מציאות ומהות מחשבה הרוחניות בגשם החיות שברגל להניע' שאין כלי הרגל מסוגל כלל לקבל רוחניות המחשבה כנ\"ל וד\"ל.\n<b>אך</b> הנה צריך לומר בזה דודאי לפי אופן של בחי' גילוי אור החיות דנפש הבא בהתחלקות באברים בכל א' לפי מזגו דוקא ודאי א\"א שיומשך מהות מח' הרוחניות באבר הרגל הגשמי כנ\"ל וגם בהילוך אור המח' הרוחני' מן המוח לרגל צריך שהי' זמן ועיכוב כי צריך שיעבור כל בנין אברי הגוף דרך גידי הדם והעורקי' המסבבי' בגוף מראש לרגל וכה\"ג, אבל בבחי'",[["4451","756","<b>מחולי המאניע</b>: ראה גם לעיל פ' בא קד, ד. וש\"נ."]]],[2300550698,"ההעלם במקיף דנפש הבלתי מתלבש כלל באברי הגוף כלל כנ\"ל (רק הרי מ\"מ סובלת בהרגשה כללי' ע\"י הגידים רוחני' המתפשטי' שנק' נערוין בשוה בכולם ממש בלי סדר והדרגה כלל וכלל) שלגבי בחי' העלם מקיף זה שוין ראש ורגל כא' ממש כנ\"ל, הרי יוכל להיות ממהות מח' הרוחני' שבמוח גם ברגל עצמו להניעו כפי המח' שמלובש ברגל. ואע\"פ שאין אבר הרגל מסוגל ומורכב בחומר שלו לקבל גילוי אור מהו' מחשבה הרוחניות זהו דוקא בבחי' גילוי החיות, אבל בבחי' ההעלם דהיינו שאין המח' בגילוי ברגל כאור וחיות התנועה דרגל עצמו רק בבחי' ההעלם לבד שורה בו (והיינו בהעלם דגידי' דקים שנק' נערוין שמתפשטי' בהעלם גדול אף ברגל וכן בכל האברים להיות הרצון ומח' שבמוח שולטת בהן בתנועתן ופעולתן, וגם בחי' ההרגשה הרוחני' שזהו לחבר הרוחני' דנפש בחומר האברי' בכלל ובפרט שהוא בבחי' כלל שוה בכל חיות האברים שיקבל מהעלם דמקיף זה מראש לרגל כא' ממש ואין חילוק כלל בזה בין החיות אבר רוחני לחיות אבר גשמי). ולכך מיד שעולה במחשבה במוח שבראש להניע הרגל תנוע בלי עיכוב כלל, מצד בחי' העלם המח' שיש גם <span data-k=\"pg\">תקא</span> ּ ברגל (בגידי' ונערוין שברגל שיש שם מן המוח שהם בהעלם רוחני בלא חיות מורגש כלל). ואין הרחק המקום שמן המוח לרגל מעכב ומפסיק להיות עיכוב זמן בזה, מאחר שא\"צ לבא בדרך גילוי החיות כלל, אלא מבחי' מקיף וסובב שלא ירדה לפי מזג חיות האברי' בהתחלקו' כלל נמשך במוח וברגל בשוה וברגע א' בהתעוררות א' ממש, כי העלם מקיף זה שוה בראש ורגל, רק שבמח' במוח בא הרצון בגילוי וברגל זהו עצמו המחשבה שבמוח להניע שמתלבש ברגל רק שהוא ברגל בהעלם ולא בגילוי כמו במוח. אבל יש ממהות המח' גם ברגל וביד וכה\"ג מצד שבבחי' ההעלם דמקיף הנ\"ל מאיר ברגל כמו בראש בשוה ממש (ויובן זה במה שרואי' בענין ההרגשה דאדם מרגיש ויודע א\"ע שיש ב' מיני הרגשה וידיעה, א' מה שמרגיש הרגשה גשמי' בחיי בשר ודם בכל אבר כפי חיותו ומזגו דוקא כמו בקלקול וכאב שמרגיש בכל אבר לפי מהותו, וזהו הרגשה פרטי' שבגידי הדם כו' באור וחיות המורכבת בכל אבר בפרט. והב' הרגשה וידיעה כללי'<sup data-n=\"4452\">757</sup> ונעלמת שהיא למעלה מהרגשה מורגשת בגילוי הנ\"ל, והוא מה שיודע ומרגיש בהעלם בעצמו מכללות הכל ממוח לרגל כא' ממש שנק' ידיעה והרגשה נעלמת ולא בגילוי אור וחיות כלל ושוה ומשוה בידיעה והרגשה זו הנעלמת ראש ורגל בגוף וגם בנפש מתחלת הרצון עד סוף מעשה, והוא מח' הכללי' שמקפת א\"ע בידיע' עצמו בכלל).\n<b>והנה</b> ע\"פ כל הנ\"ל במשל זה יובן יותר ענין ההפרש בין העלם וגילוי למעלה בב' מדרגות דסובב וממלא הנ\"ל שזה שא' בזהר דקוב\"ה סתים וגליא<sup data-n=\"4453\">758</sup>, דבחי' ממכ\"ע זהו כמו בחי' גילוי אור וחיות הנפש המתחלק בגוף מראש לרגל בסדר והדרגה",[["4452","757","<b>הרגשה וידיעה כללי'</b>: ראה גם לעיל פ' בשלח קסו, ג. וש\"נ."],["4453","758","<b>דקוב\"ה סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א."]]],[2300550702,"מעליון לתחתון כנ\"ל. כך אור העליון יותר בחב\"ד דבריאה בנשמות דבריאה כו' וכן מלאכים דבריאה כשרפי', וכמו המח' והשגה דבינה שבמוח שהוא בחי' פנימי' יותר וכולל כל מה שיסתעף ממנו כו' ויורד ומשתלשל יותר בעולם היצי' באופנים<sup data-n=\"4454\">759</sup> וחיות<sup data-n=\"4455\">760</sup> כו', עד צמצום האחרון יותר בג\"ע דעשי' ועד גלגלי' דעשי' וכל חלקי דצח\"מ וארמ\"ע דעוה\"ז שזהו כחיות הרגל גשמי כנ\"ל ונק' רגלי השכינה וכמו והארץ הדום רגלי כו'. וכך עד\"ז יש חיצוני' ואחוריי' בכל עולם לפי ערכו עד שיש חיצוני' דחיצוני' כצפרניים ושערות כו' שמקבלים החיצוני', ויש מלאכים עליונים שנק' בבחי' אברים פנימים דשכינה כמו אצטומכא וקרביים כמו וכל קרב\"י<sup data-n=\"4456\">761</sup> את שם קדשו כמ\"ש במ\"א. ובודאי יש הפרש גדול בין פנימי' דמחשבה ושכל אלקי שבנשמות ומלאכים דבריאה בין בחי' רגלי השכינה בשמים וארץ גשמיי', כמו בהילוך גלגל המזלות וצמיחת הארץ וכל אשר בה וכתי' כל אשר חפץ ה' עשה בשמי' וארץ<sup data-n=\"4457\">762</sup> כו'. הרי בחי' הרצון הנעלם שבחכמה בראש שולט גם בארץ וגלגלים לסדר הילוכם כרצונו שבמוח חו\"ב דמל' דאצי' (שנק' אדם דבריאה בכלל), וכמו שאו' ומסדר הכוכבים ברקיע כרצונו<sup data-n=\"4458\">763</sup> דוקא ובהשגחה פרטי' בארץ כו' כמו בג\"ע דבריאה ממש בשוה. ומוכרח לומר שיש מהות המח' ורצון העליון הנעלם בחו\"ב דמל' גם ברגל שנק' רגלי <span data-k=\"pg\">1004</span> ּ השכינה בארץ כמו במוחין דחו\"ב למעלה רק שהוא בהעלם ולא בגילוי כנ\"ל. כי זהו בא מבחי' מקיף וסובב כ\"ע שלמעלה מההתלבשות אור וחיות בגילוי בעולמות דבי\"ע שהוא בחי' סתים, ששם הוא בחי' ההעלם דמחשבה הכללי' שבעצמו' אלקו' ששוה ומשוה כל מה שבא בהשתלשלו' מראש דעולם הבריאה עד בחי' רגל דעולם העשי' בהשוואה א' ממש כנ\"ל במקיף דנפש אדם למטה. ולכך יכול להיות בחי' העלם דמח' גם בבחי' רגל שהוא שליטת הרצון העליון גם בארץ למטה כמו למעלה ממש רק שהוא בהעלם דמקיף ולא בבחי' גילוי אור וחיות כממלא כ\"ע כו'. וז\"ש את השמים בעולם הבריאה בכלל ואת הארץ בעשי' אני מלא<sup data-n=\"4459\">764</sup> בהשוואה א' דלית אתר פנוי מיני' אבל בהעלם ולא בגילוי שא\"כ הי' חילוק מדרגו' בין למעלה ולמטה ובין פנימי' לחיצוני' ואחוריי' אלא הכל בהשוואה א' (כמו והקדוש בשמים ובארץ<sup data-n=\"4460\">765</sup> בשוה וכן א' המגביהי לשבת ע\"כ משפילי לראות<sup data-n=\"4461\">766</sup> בשמים וארץ בשוה וע\"ז א' דאיהו תפיס בכל עלמין בהעלם בשוה ולית מאן דתפיס כו' וכן הוא מקומו ש\"ע שסובל הכל כא' בהעלם א' אבל אין העולם מקומו כו') (והיינו כענין מחשבה וידיעה והרגשה כללי' בהעלם הנ\"ל שהיא מתלבשת בידיע' והרגשה מורגשת בפרט ועכ\"ז אינה נתפסת בזה כלל כך תפיס",[["4454","759","<b>בעולם היצי' באופנים</b>: ראה גם לעיל פ' בא צז, ג. וש\"נ."],["4455","760","<b>בעולם היצי'. . וחיות</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רח. וש\"נ. שע\"ת נח, א ובהערה 3. לקמן פ' ויקהל תג, ג."],["4456","761","<b>מלאכים. . וכל קרב\"י</b>: תהלים קג, א. ראה זהר לך פז, סע\"א. (רע\"מ) פינחס רלד, ב. לעיל פ' וארא ס, ג. וש\"נ."],["4457","762","<b>כל אשר חפץ. . וארץ</b>: תהלים קלה, ו [ושם: ובארץ]."],["4458","763","<b>ומסדר הכוכבים ברקיע כרצונו</b>: תפלת ערבית [בדילוג]."],["4459","764","<b>את השמים. . ואת הארץ. . אני מלא</b>: ירמי' כג, כד."],["4460","765","<b>והקדוש בשמים ובארץ</b>: ברכת ישתבח. ראה גם לעיל פ' בשלח קסו, ג. וש\"נ."],["4461","766","<b>המגביהי לשבת. . משפילי לראות</b>: תהלים קיג, ה. ו [ושם: המשפילי]."]]],[2300550705,"כו' ואינו נתפס ומשפילי לראות בהשגחה פרטי'). ונמצא מובן עכ\"פ שמצד בחי' ההעלם דמקיף דסובב כ\"ע כנ\"ל אע\"פ שמתלבש ובא גם בדרך פרטי פרטיות מראש דעולם הבריאה עד חיצוני' דעולם העשי', מ\"מ שוה הוא בכולם ממש בלי שינוי והפרש כלל מעלה ומטה ופנימי' וחיצוני' מאחר שכל זה הוא בבחי' ההעלם בענין נבדל בערך לגמרי עד שיתלבש העלם המח' ורצון ברגל כמו במוח כנ\"ל, א\"כ אין הפרש בין רגל לראש כלל לגבי בחי' המקיף דסובב כ\"ע וגם הראש כרגל יחשב והרגל כראש כו'. ולפ\"ז ממילא מובן מאחר שמצד בחי' עיגול המקיף מבלי שימצא ראש וסוף כלל א\"כ ג\"כ אין הפרש וחילוק בו בין פנימי' לחיצוני' ואחוריי' כלל וכלל שגם בבחי' אחוריי' וחיצוני' הכלים יתלבש בהעלם זה כמו בפנימי' ממש בשוה להיותו למעלה מגדר וסוג התפשטו' גילוי החיות הבא בציור אדם פנים ואחור באו\"כ כו' ע\"כ ראש ורגל פנים ואחור שוין ממש וד\"ל.\n<b>והנה</b> לפי כל הנ\"ל יובן בבחי' סוכ\"ע שאין שם בחי' רגל וראש ויכול להיות הפנימי' וחיצוני' שוין ממש וכמו כל אשר חפ\"ץ ה' עשה בעשי' דבחי' רגל בד\"י<sup data-n=\"4462\">767</sup> דעוה\"ז ודצח\"מ ברצונו הפשוט שנק' חפץ ה' כו' לפי שאין העולם מקומו ונתפס בכולם בשוה כו' כנ\"ל. וכך יובן ג\"כ בענין המצות להיות מבואר למעלה בשרש המצות שהן בבחי' מקיף דכת\"ר הכללי דאבי\"ע מקור כל האו\"פ דאד\"ם דאצי' כו', כי הגם שכל מצוה ומצוה הוא בבחי' כלי מגביל דוקא לאור הרצה\"ע וח\"ע שגנוז בה ולכך יש מספר רמ\"ח מ\"ע שהן לנגד רמ\"ח אברי'<sup data-n=\"4463\">768</sup>, ומבואר למעלה שבאברי' בא בחי' גילוי האור וחיות דאו\"פ דוקא המתגלה בכל אבר לפי מזגו ובסדר והדרגה מעליון <span data-k=\"pg\">תקב</span> ּ לתחתון כנ\"ל, וכך המצות יש שנק' בבחי' ראש כמצות תפילין בראש וק\"ש ביח\"ע דחו\"ב כו' וכה\"ג, ויש שנק' בחי' רגל ויד כצדקה<sup data-n=\"4464\">769</sup> וכה\"ג שהרי כללות המצות נק' בחי' אדם חיצוני בחיצוניות הכלים ואברים דוקא כנ\"ל. אך הנה מבואר למעלה שהמצות הן בחי' כלים פנימי' ועצמי' שמקושר בהן מבחי' פנימי' ועצמו' דאוא\"ס שבע\"ס דאצי' דוקא כנ\"ל (וכנ\"ל בענין המזון שמחזק האורות בכלים שכולו פנימי' ועצמו' בלי חיצוני' כלל וכמו שכנ\"י נק' רעייתי (וכמו באתי לגני אכלתי יערי<sup data-n=\"4465\">771</sup> כו' כידוע) שמפרנסי' לאביהם שבשמים<sup data-n=\"4466\">770</sup> במצות מעשיות שאו' ע\"ז כאלו עשאוני ברמ\"ח כו' אע\"פ שכבר יש או\"כ באצי'), והיינו להיות ששרש המצות בפנימי' ועצמו' דתענוג והרצון העליון בבחי' מקיף דכתר הכללי טרם שבא באו\"פ בכלי (שזהו קודם התחלקות הרצון בחכ' ומדות באו\"כ ברמ\"ח מ\"ע ברמ\"ח אברי' חיצוני' כו') שנק' תר\"ך עמודי",[["4462","767","<b>בד\"י</b>: בד' יסודות."],["4463","768","<b>רמ\"ח. . רמ\"ח אברי'</b>: מכות כג, סע\"ב."],["4464","769","<b>רגל. . כצדקה</b>: ראה גם לעיל פ' שמות מו, ב. וש\"נ."],["4465","771","<b>באתי לגני אכלתי יערי</b>: שה\"ש ה, א [בדילוג]. ראה גם לעיל פ' יתרו רס, ד."],["4466","770","<b>שכנ\"י נק' רעייתי. . שמפרנסי' לאביהם שבשמים</b>: שה\"ש א, ט. ראה זהר ויקרא ז, ב. לקמן פ' ויקהל שצט, א הערה 254. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תרעט. הנחות תקע\"ז ע' קמז."]]],[2300550708,"אור כעמוד שמחבר גג ורצפה<sup data-n=\"4467\">772</sup> כא' ממש מבלי שימצא ראש וסוף כו'. ולכך יש בחי' התכללו' האמיתי' באברים שהן המצות מבלי חילוק בין ת\"ת ותפילין וק\"ש שבמוחי' לצדקה שברגל ממש כנ\"ל (וכנ\"ל דהתכללו' זאת בחיצוני' האברים מצד בחי' המקיף ששרש הכלים במקיפי' שלמעלה מאו\"פ ולכך בנין הכלים קודם לבנין האורות כו'). ולכך ע\"י קיום המצות מעוררי' וממשיכי' מפנימי' קדש העליון שהוא בחי' סובב הכללי המקיף לאבי\"ע כמו שאו' אשר קדשנו במצותיו<sup data-n=\"4468\">773</sup> בקדש העצמות דא\"ס שלפני הצמצום דקו\"ח באצי' ובריאה כו' שהוא מקיף כללי בהעלם ומקור נעלם לכל גילוי אורות דע\"ס דאבי\"ע כו'. ולכך ודאי ממילא מובן שכ\"ש וק\"ו הוא שבבחי' מקיף דקדש העליון הזה שרש כל המצות (בהעלם ובהשוואה א' לכולם כנ\"ל) שוה ומשוה מראש לסוף כא' ממש, ואין הפרש כלל לגבי' בין פנימי' לחיצוני' ואחוריי' כלל וכלל דהיינו שבחי' ההעלם דקדש זה מאיר בשוה בחיצוני' ואחוריי' דכלים דמל' דמל' דעשי' כמו בפנימי' דאדם העליון דאצי' (כמו שעיגול א\"א מקיף רגלי העשי'<sup data-n=\"4469\">774</sup>, כך מקיף דטה\"ע מקיף לכל הקו\"ח מראשו לסופו).\n<b>ולפ\"ז</b> הרי יובן דגם שכנ\"י הן עומדים בבחי' אב\"א והוא בחיצוני' ואחוריי' דכלים דמל' בעשי' הנמשך בשפע חיצוני' במזלות ודצח\"מ דעשי' שנק' רגלי השכינה, כמו בטרדת הפרנסה בהתקשרות הנפש בפנימי' ועצמיו', ולה' בתפלה לבם רחוק רק בפיו ושפתיו כו', וכן במצות ותורה רק בטבע הרגילות בלי כוונה כלל כנ\"ל. מ\"מ לגבי בחי' אור המקיף דקדש העליון הכללי שרש כל המצות הנ\"ל הרי יכול להיות בהם ע\"י המעשה דמצות מבחי' פנימי' דקדש דמקיף העליון ממש כמו שיאיר בפנימי' החכ' דאדם דאצי', רק שהוא בבחי' ההעלם לבד ולא בגילוי גמור כמו העלם המח' ורצון שבמוח שמלובש בהעלם ברגל ממש כנ\"ל. כך בנש\"י אעפ\"י שהן בבחי' רגל או בחי' אחוריי' וחיצוני' שלהם יוכל להתלבש ולהאיר במצות מעשיות שלהם מבחי' הפנימי' ועצמיות דמקיף דכתר העליון כמו שהוא למעלה ממש בלי שינוי כלל, לפי שלגבי בחי' מקיף הכללי הזה דעצמות א\"ס בשרש המצות שלמעלה מהשתלשלו' אף באו\"כ דמצות למעלה באצי' שוה לפניו <span data-k=\"pg\">1006</span> ּ בחי' רגל עם ראש ופנים ואחוריי' כו' כנ\"ל בסובב כ\"ע ששולט ברגל כמו בראש כו' וד\"ל (אך ה\"ז בבחי' ההעלם ולא בגילוי כנ\"ל, ולע\"ל בעוה\"ב יתגלה בחי' העלם דמקיף הזה שבמצות ומזה יהי' העוה\"ב<sup data-n=\"4470\">775</sup> כידוע. ולכך אפי' במצות דפ\"י יהי' חלק בעוה\"ב מטעם זה וד\"ל).",[["4467","772","<b>כעמוד שמחבר גג ורצפה</b>: ראה גם אגה\"ק סכ\"ט. ש\"א יג, ב ובהערה 34."],["4468","773","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לא."],["4469","774","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370051\" data-slug=\"torah-or\" data-id=\"3901370051\">שעיגול א</a>\"א מקיף רגלי העשי'</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' תצט. תו\"א לך יא, ד. תו\"ח שם פז, ד. מאמרי אדה\"א במדבר ח\"ב ע' תל. דברים ח\"ב ע' תצה. לעיל פ' בשלח קצו, ד."],["4470","775","<b>שבמצות ומזה יהי' העוה\"ב</b>: ראה גם מאמרי אדה\"א בראשית ע' שצב. וש\"נ. לעיל פ' שמות ז, א. וש\"נ."]]],[2300550711,"<b>וזהו</b> שבמעשה המצות א' וימינו תחבקני<sup data-n=\"4471\">776</sup>, דהיינו שבחי' ימין העליון מקיף וסובב גם לבחי' אחוריי' דנש\"י כמו שהן עומדי' אב\"א כאשר הן באחוריי' וחיצוני' מצד בחי' גילוי החיות דאו\"פ בכלי. והוא מה שיש בכח המקיף דימין העליון לחבק לבחי' אד\"ם דכנ\"י כמו שהן למטה שלא יפנו עורף לעולם, כמו שמחבק האב לבנו מאחוריו שלא יתן כתף סוררת<sup data-n=\"4472\">777</sup> בעורף כי יהי' נצמד ומדובק באביו ע\"י ימינו שיחבקנו אליו פב\"פ תמיד. והב' זהו גם לאחר שפנו עורף ועומדי' אב\"א ממש בתפלה ותו\"מ כנ\"ל יש בכח האו\"מ הזה להחזירם פב\"פ או להקימם מנפילתם למטה ויגביהם למעלה, כמו אנכי תרגלת\"י לאפרים<sup data-n=\"4473\">778</sup> קחם על זרועותי, או שיאיר פניו אליהם גם בהיותם למטה כמו למעלה כמו כי אתך אני<sup data-n=\"4474\">779</sup> כו' באשר הוא שם<sup data-n=\"4475\">780</sup> למטה, לפי ששוה מטה ומעלה ממש מטעם הנ\"ל. וא\"צ כנ\"י לעלות במעלות ומדרגות להתפשט מגשמיות שלהם כי אין זה רק מצד גילוי האור דממלא כו' שנשתלשל עד שהן בבחי' אחוריי' או בחי' רגל, אבל בחי' מקיף דאו\"י שמאיר מלמעלה מקיף ראש ורגל בפנימי' ואחוריי' כא' ממש אע\"פ שנשאר כמו שהוא בבחי' אחוריי' או בחי' רגל כנ\"ל וד\"ל. וזהו קרוב ה' לכל קוראיו זהו קריאה דתפלה<sup data-n=\"4476\">781</sup> דמשמע דקורא זה מרחוק עומד וקורא מלמטה לה' שיענהו כמו מן הרוממו' דשמים לארץ, ועכ\"ז א' קרוב ה' שנעשה קרוב אל הקורא באשר הוא שם למטה כמו וישמע אלקי' אל קול הנער באשר הוא שם<sup data-n=\"4477\">782</sup>, כי שומע תפלת כל פה<sup data-n=\"4478\">783</sup> אפי' מקטן הערך מאד שעומד בריחוק בחיצוני' ואחוריי' או בבחי' רגל אבל יש בזה העלאה למעלה והמשכה למטה להיות קרוב לקוראיו מלמעלה למטה. אבל מ\"ש לכל אשר יקראוהו באמת זהו בחי' קריאה דתו\"מ<sup data-n=\"4479\">784</sup> ששרשן במקיף הכללי דעצמות א\"ס ממש שלמעלה ולמטה שוין ממש כנ\"ל ה\"ז הקורא למטה באמת דתו\"מ אינו בבחי' ריחוק כלל, דגם כמו שהוא למטה זהו כמו למעלה ממש וא\"צ להמשכות לבוא מלמעלה בדרך קריאה ובקשה אלא נמצא הוא למטה בלבושי' אלה דתו\"מ כמו שהוא למעלה ממש וכמא' הקורא בתורה קורא בשמותיו העצמי'<sup data-n=\"4480\">785</sup> כו' בחי' מקיף דכתר הכללי הנ\"ל (אע\"פ שנמשך בג' קוין תורה ועבודה וגמ\"ח בציור אדם מ\"מ הרי כולל הכל כא' ממש בשוה מראש לרגל גם ברמ\"ח אברים דמ\"ע כנ\"ל) וד\"ל.\n<b>ומעתה</b> יש להבין מ\"ש כאן ויקחו אליך שמן זית זך כתית למאור כו' מאחר שמבואר למעלה שע\"י המצות מצד עצמן אע\"פ שבנ\"י הן בבחי' אב\"א יכול להיות החזרת פב\"פ דוקא מטעם הנ\"ל (והיינו בב' פנים, א' בבחי' ימינו תחבקני",[["4471","776","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג."],["4472","777","<b>כתף סוררת</b>: זכרי' ז, יא. נחמי' ט, כט."],["4473","778","<b>אנכי תרגלת\"י לאפרים</b>: הושע יא, ג [ושם: ואנכי. . זרעותיו — ראה הנסמן לעיל פ' בא פט, ב]."],["4474","779","<b>כי אתך אני</b>: ישעי' מג, ה. ירמי' א, ח. יט. טו, כ. ל, יא. מו, כח."],["4475","780","<b>באשר הוא שם</b>: נסמן בהערה 782."],["4476","781","<b>קרוב ה' לכל קוראיו. . דתפלה</b>: תהלים קמה, יח. ראה סידור שחרית נו, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680230\" data-slug=\"torat-chaim\" data-id=\"2300680230\">תו\"ח וישב רא, ב</a>. מאמרי אדה\"א שמות ח\"ב ע' תקע."],["4477","782","<b>וישמע אלקים. . הוא שם</b>: וירא כא, יז [בדילוג]."],["4478","783","<b>כי שומע תפלת כל פה</b>: נוסח שמו\"ע [בדילוג]."],["4479","784","<b>לכל אשר יקראוהו באמת. . דתו\"מ</b>: ראה גם לעיל יא, ג. וש\"נ."],["4480","785","<b>הקורא בתורה קורא בשמותיו העצמי'</b>: ראה פתיחת הרמב\"ן עה\"ת. הנסמן במאמרי אדה\"א דברים ח\"א ע' קלט. תו\"ח ח\"ש קלד, ב ובהערה 10."]]],[2300550714,"באחוריי' דכנ\"י לבלתי יוכלו ליתן עורף כו' כנ\"ל. והב' גם שפנו עורף יחזירם פב\"פ רק ע\"י מצות מעשיות שלהם מצד עצם המעשה לבד כנ\"ל וד\"ל). &lt;תקג&gt; ּ א\"כ מה זה שציוה שיקחו אל משה דוקא שמן זית זך שהן המצות שיהי' נעשי' ע\"י משה דוקא כנ\"ל ואז יהי' העלא' נר מצוה תמיד למעלה בבחי' פב\"פ כמו אל מול פני כו' ע\"י אהרן כנ\"ל. אך תחלה יש להבין מ\"ש כתית למאור דוקא ולא א' לאור<sup data-n=\"4481\">786</sup> כו' כי עיקר הדלקת הנר בשמן ופתילה אינו רק להאיר אור לבד ולמה א' למאור שלמעלה מן האור כידוע ואח\"כ א' להעלות נר כו'. והנה יש להקדים תחלה מה שהתורה נק' לפעמים אור כמ\"ש ותורה אור<sup data-n=\"4482\">787</sup>, וכן א' יהי אור וא' בזהר דא אור קדמאה<sup data-n=\"4483\">788</sup> שהוא בחי' חכמה דתורה שנק' אור. ולפעמים נק' התורה בשם מאור כמו שא' מאור שבה מחזירו למוטב בחי' מאור שבה שגנוז באותיות דתורה בהעלם מחזירו למוטב שיכול להפוך אותו מרע לטוב ומחושך לאור כו' (וזהו אור הגנוז לצדיקי' לע\"ל<sup data-n=\"4484\">789</sup> כו').\n<b>וביאור</b> הענין הנה ידוע בזהר דאוריי' סתים וגליא<sup data-n=\"4485\">790</sup> כמו הנסתרות לה' כו' והנגלות לנו<sup data-n=\"4486\">791</sup> כו' והוא בחי' פנימי' התורה שנק' סודות ורזי' דאורייתא ונק' פלאות חכ'<sup data-n=\"4487\">792</sup> או תעלומות חכ'<sup data-n=\"4488\">793</sup> עילאה, וכמו צנור הנובע מים מן ההעלם לגילוי שהמים נובעים בצנורות בהעלם כך הוא בחי' הח\"ע דתורה שנובע בהעלם ולא באה בגילוי עדיין כסוד ה' שבטעמי מצות שיתגלו לע\"ל ועכשיו הן בהעלם ונק' טעם כמוס לרצה\"ע שבמצות (וזהו מזל ונוצר חסד שאור אבא דאצי' מקבל ממנו<sup data-n=\"4489\">794</sup> כו' ושרשו בחי' ח\"ס דא\"א או חכ' דא\"ק עד בחי' חכ' הקדומ' דמל' דא\"ס עצמו). וע\"ז א' ג\"כ ותורה אור, דאע\"פ שהוא בהעלם דחכ' עדיין שזהו בבחי' אי\"ן דחכ' שבכתר קודם שתמצא בבחי' יש אפי' כנקודה דיו\"ד כטיפי המעיין או המים המקלחי' מן הצנור כו', מ\"מ ה\"ז עצמו ג\"כ בחי' גילוי אור לגבי הכח העצמי' דחכ' דא\"ס שקודם בואו לבחי' צמצום דנביעה זו שבהעלם. והוא כמו כח המשכיל ההיולי בעצם הנפש שהוא מקור עצמו להוליד ולהמציא כל מיני שכל וחכ' טרם שבא לכלל נביעה ומקור להמציא שכל כו' (שזהו שנק' נפש השכלית<sup data-n=\"4490\">795</sup> ע\"ש כח השכל המשכיל כל שכל כו' שנק' נפש אדם בחי' מדבר שיש בה כח המוליד להוליד בדומה לו ג\"כ נפש שכלי' כו') (ואע\"פ שמה שנמשך מכח העצמו' דחכ' בבחי' נביעה בהעלם אין זה נק' אור ממש בגילוי, מ\"מ ה\"ז עכ\"פ בחי' גילוי המשכה מן העצם שבלתי מוגבל כלל בהמשכה והשפעה רק שבחי' המשכה זאת נקרא",[["4481","786","<b>כתית למאור. . לאור</b>: ראה גם לעיל פ' שמות טז, ג. לקמן שמו, ד. ש\"א מה, ב ובהערה 24."],["4482","787","<b>ותורה אור</b>: משלי ו, כג."],["4483","788","<b>יהי אור. . דא אור קדמאה</b>: בראשית א, ג. ראה זהר בראשית ל, ב. תרומה קסז, א."],["4484","789","<b>אור הגנוז לצדיקי' לע\"ל</b>: חגיגה יב, א."],["4485","790","<b>דאוריי' סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א."],["4486","791","<b>הנסתרות. . והנגלות לנו</b>: נצבים כט, כח. ראה גם לקמן פ' פקודי תנד, ד. תס, א."],["4487","792","<b>פלאות חכ'</b>: ראה גם לעיל פ' שמות כא, ב. וש\"נ."],["4488","793","<b>תעלומות חכ'</b>: איוב יא, ו. ראה גם לעיל פ' שמות לג, א. וש\"נ."],["4489","794","<b>מזל ונוצר חסד שאור אבא. . ממנו</b>: ראה גם לעיל פ' משפטים רפט, ב. וש\"נ."],["4490","795","<b>נפש השכלית</b>: ראה גם לעיל פ' בא קא, ג. וש\"נ."]]],[2300550717,"המשכה נעלמת והרי עתיד ומוכן לצאת מן ההעלם הזה לגילוי כבוד ה' שנגלה ליראי ה', אע\"פ שנק' שכל מופלא<sup data-n=\"4491\">796</sup> שכל הנעלם מכ\"ר<sup data-n=\"4492\">797</sup> כו', ע\"כ נק' גם הוא בשם אור דאור גימ' רז<sup data-n=\"4493\">798</sup> כו').\n<b>והנה</b> בחי' אור דתו' בבחי' סתים וגליא ממש כשיצאה למטה בהשתלשלו' כמא' דאורייתא מח\"ע נפקת שיצאה מח\"ע העצמיי' מן ההעלם לגילוי (וכמו מעיין שנובע טיפין וכצנור המקלח מים כנ\"ל) הרי ירדה בהתלבשות בכל עולם ועולם לפי מה שהוא, דהיינו לפי אופן של ההשתל' ממש. כי אחר שבחכ' דתו' אור הוא שנעשה ונמשך כל ההשתל' כמ\"ש בזהר דאסתכל באוריי' וברא <span data-k=\"pg\">1008</span> ּ עלמא שזהו בחכ' דתורה אור שקדמה לעולם דוקא שנק' תורה וחכ' הקדומה דגם היא נק' בשם אור דוקא, להיותה בבחי' המשכה והשפעה מכח חכ' העצמי' דא\"ס ב\"ה ממש דלתבונתו אין מספר ונק' חכים ולא בחכ' ידיעא כלל אפי' בבחי' העלם, רק כמו כח המשכיל באדם בעצם טרם שמשפיע ומוליד שכל וחכ' כנ\"ל. ואע\"פ שבחי' אור דתוה\"ק הזאת ג\"כ היא למעלה הרבה מן ההשתל' דחכ' דמע\"ב וכל העולמות בחכ' דהשתלשלו' זהו רק בבחי' גילוי החכ' שמאין תמצא בבחי' יש כמעיין שבא בגילוי וגם זה רק בשביל המשכות העולמות מאין ליש ממש כו' כמ\"ש כולם בחכ' עשית שזהו כמו שכל שבעשי' בחיצוני' שאין זה ערך כלל לבחי' החכ' הפנימי' דתורה אור (אפי' לבחי' גילוי דחכמה באותיות כיו\"ד וה\"א דשם הוי' דתורה ומצו' כו'). מ\"מ מאחר שבחכ' דתורה דוקא ברא הכל כמ\"ש דאסתכל באוריי' כו' שהוא כמו שעושי' האומנים בלוח הבונים לצייר אופן הבנין שמציירים אותו ע\"פ שכל וחכ' דחכ' זו נמשך מחכ' ושכל הפנימי' שלמד מכבר לעצמו כו', כך א' ואהי' אצלו אמון אומנא<sup data-n=\"4494\">799</sup> כאומן המצייר לוח הבנין שע\"פ החכ' דתורה נעשה ציור הלוח לעשות בנין כל העולמות כך וכך דוקא ולא כך וכך, ועד\"ז אסתכל באוריי' וברא כו' דלפי אופן הורא' החכמה דתורה אור כך הי' ממש ציור אופן השתלשלו' העולמות בכלל ובפרט (אף בכל ציור ותמונה דבהמה וחי' וחלקי דו\"צ ושמים וארץ וכ\"צ<sup data-n=\"4495\">800</sup> ) (וכרשב\"י שידע כל הי\"מ בכל פרט מיו\"ד הדברות<sup data-n=\"4496\">801</sup> שמלובש בהן שהן פנימי' די\"מ בכלל ובפרט) וכמ\"ש אם לא בריתי<sup data-n=\"4497\">802</sup> כו' חוקות שמים כו' וכן מ\"ש כי הוא ציוה<sup data-n=\"4498\">803</sup> כו' חק נתן<sup data-n=\"4499\">804</sup> כו' זהו ע\"פ חק דתוה\"ק), וא\"כ הרי גם תוה\"ק ירדה למטה בכל ההשתל' וכמ\"ש התורה ה' קנני ראשית דרכו במעשה בראשית מראש",[["4491","796","<b>שכל מופלא</b>: ראה הקדמת הראב\"ד לס\"י ”הנתיב הא'\". מאמרי אדה\"א בראשית ע' ח בהערה."],["4492","797","<b>שכל הנעלם מכ\"ר</b>: ראה פיוט אל מסתתר. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' עתר ובהנסמן במ\"מ לשם. מאמרי אדה\"א בראשית ע' ח. וש\"נ."],["4493","798","<b>דאור גימ' רז</b>: ראה זהר (רע\"מ) צו כח, ב. ת\"ז תי\"ט (לט, ב)."],["4494","799","<b>ואהי' אצלו אמון אומנא</b>: משלי ח, ל. ב\"ר בתחלתו."],["4495","800","<b>דו\"צ. . וכ\"צ</b>: דומם וצומח. . וכל צבאם."],["4496","801","<b>וכרשב\"י שידע. . מיו\"ד הדברות</b>: ראה זהר ויקרא יא, ב ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670040\" data-slug=\"torat-chaim\" data-id=\"2300670040\">תו\"ח בראשית ז, סע\"ב</a>."],["4497","802","<b>אם לא בריתי</b>: ירמי' לג, כה."],["4498","803","<b>כי הוא ציוה</b>: תהלים קמח, ה."],["4499","804","<b>חק נתן</b>: תהלים שם, ו."]]],[2300550720,"ומקור הראשון דקו\"ח עד סוף עולם העשי'. ולכך יש אור דתוה\"ק בהתלבשות בכל עולם ועולם כמו בעולם האצי' נק' תורה דאצי' ובבריאה תורה דבריאה<sup data-n=\"4500\">805</sup> עד תורה אור הנגלית לנו באותיות ממש בעולם העשי', וזהו אצלו אומן אומנא בבחי' שפלות וירידה להיות כאומן לבנות בנין בחכמה דתורה כמ\"ש בחכ' יבנה<sup data-n=\"4501\">806</sup> בחכ' דתורה דוקא והוא בי\"ת דבראשית דבראשית נמי מאמר הוא<sup data-n=\"4502\">807</sup>, פי' מאמר פתוח<sup data-n=\"4503\">808</sup> מן ההעלם דחכ' הקדומה שיצאה לגילוי בשביל ההשתל' העולמות וד\"ל.\n<b>אך</b> כל זה הוא בבחי' אור דתורה כמו שבאה בבחי' המשכה עכ\"פ בבחי' העלם וגילוי בבחי' סתים וגליא כנ\"ל, אבל בחי' מאור דתורה זהו כמו שהיא כלולה ומתאחדת ממש בכח החכ' העצמי' דא\"ס ב\"ה עצמו כמ\"ש ואהי' אצלו שעשועי'<sup data-n=\"4504\">809</sup> בחי' שעשועי' עצמיי' ממש והוא בחי' תענוג הפשוט דעצמות ממש בחכמתו העצמיי' (שנק' שעשועי המלך בעצמו ממש) שזהו כמו קודם שנמשך אור דחכ' אפי' בהעלם ופנימי' כנ\"ל. וזהו המלובש גם עכשיו שירדה התורה בהשתלשלו' בבחי' עצמיות הרצון הפשוט שמורכב באותיות דתורה ובמצות מעשיות <span data-k=\"pg\">תקד</span> ּ בפ\"מ דוקא שלמעלה מטעם כמוס לרצון כו' (והוא העדן דעוה\"ב דעין לא ראתה<sup data-n=\"4505\">810</sup> כו') ונק' תר\"ך עמודי אור שמחברי' למעלה ומטה כא' ממש, להיותו למעלה ממקור ההשתל' אפי' בחכ' הקדומה שאינו בחי' מקור למקור אפי' להיות חכמה דמע\"ב כאומן הבונה כו', דזהו ירידה ושפלות גדולה מעצם פנימי' כח החכ' דא\"ס שכל עצמות פנימיותו מלובש בזה ולכך א' ואהי' שעשועי' עצמיי' ממש מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> בחי' מאור שבתו' שמחזירו למוטב כו' דהיינו בחי' עצמו' כח החכ' דא\"ס שנמשך וגנוז ומלובש בהעלם בתוך אור דתורה הנמשכת למטה שנק' מאור מקור כל בחי' אור בהעלם וגילוי כו' (והוא אור הגנוז לצדיקי' בעוה\"ב שגנזו והעלימו באור דתורה<sup data-n=\"4506\">811</sup> שמביט בו מסוף העולם כו', להיותו למעלה מכל ההשתלשלו' מראש לסוף ע\"כ ראי' החכמה במאור דתורה מביט בבחי' מקיף כעיגול כו' מבלי שימצא ראש וסוף כלל. משא\"כ באור דתורה שבאה בהשתלשלו' דאבי\"ע יש בה בחי' ראש וסוף לפי אופן ההשתל' משום דבחכ' דתורה נבנה בנין העולמות וזהו שנק' ת\"ח בוניך שעוסקים בבניינו ש\"ע<sup data-n=\"4507\">812</sup> כו'). וזהו הטעם שא' שמאור הגנוז באור דתורה מחזירו למוטב דמחזירו זה קאי במי שעוסק בתו' של\"ש כלל רק להתייהר ולעשות קרדום כו' ואינו מקיים מ\"ש בתו', וכמו שא' למיימיני' בה סמא דחייא<sup data-n=\"4508\">813</sup>",[["4500","805","<b>תורה דאצי'. . דבריאה</b>: ראה גם לעיל פ' בא קיד, ב. וש\"נ."],["4501","806","<b>בחכ' יבנה</b>: משלי כד, ג. ראה גם לעיל פ' וארא פא, ג. וש\"נ."],["4502","807","<b>דבראשית נמי מאמר הוא</b>: בראשית א, א. ר\"ה לב, א."],["4503","808","<b>מאמר פתוח</b>: שבת קד, א. ראה גם לעיל פ' שמות יב, ב. וש\"נ."],["4504","809","<b>ואהי' אצלו שעשועי'</b>: משלי ח, ל [בדילוג]."],["4505","810","<b>העדן דעוה\"ב דעין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["4506","811","<b>אור הגנוז. . והעלימו באור דתורה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380383\" data-slug=\"likkutei-torah\" data-id=\"4001380383\">לקו\"ת במדבר יח, ד</a> ובהנסמן במ\"מ לשם. מאמרי אדה\"א בראשית ע' תה. וש\"נ."],["4507","812","<b>ת\"ח בוניך. . ש\"ע</b>: ראה ברכות סד, א. שבת קיד, א. מאמרי אדה\"א דברים ח\"ד ע' א'תכו. וש\"נ."],["4508","813","<b>למיימיני' בה סמא דחייא</b>: שבת פח, ב."]]],[2300550723,"למשמאילי' בה סמא דמותא כו' שמוסיף כח בק\"נ וכמו ולרשע מה לך לספר<sup data-n=\"4509\">814</sup> כו', וכן במצות שעושה להתייהר ולקנות שם לבד כמצות אנשים מלומדה הנ\"ל שנק' בחי' אחוריי' כמו כי פנו אלי עורף כו' כנ\"ל. אך בחי' המאור הגנוז באור דתו' שלומד אפי' של\"ש מחזירו למוטב, שמחזירו מבחי' אחוריי' שנסוג אחור ומעוררו לתשובה שלימה להיות עוסק בתורה ומצות לשמן, וכמו שאו' לעולם יעסוק בתו' ומצות אפי' של\"ש שמתוך של\"ש בא לשמה<sup data-n=\"4510\">815</sup>, וזה פלא לכאורה איך משל\"ש לכוונה זרה ונכרית שלא לה' כלל יבוא לעסק לשמה שזהו כהיפוך חשך לאור ורע לטוב ואם עומד ברע דק\"נ שנק' חשך ולא אור איך יהופך לעמוד במקום הקדושה שנק' אור שיעסוק לשמן כו'. אך הענין הוא דכל מה שבא בהשתלשלו' העולמות מריש כל דרגין עד סוף עולם העשי' שאת זלעו\"ז עשה<sup data-n=\"4511\">816</sup> כו' להיות מציאות מדות הרעות דק\"נ עד בחי' רע גמור כו' שהוא בא מצד עה\"ד טו\"ר, זהו דוקא מצד ההשתלשלו' שבא בצמצומי' רבים באו\"כ עד הכלים החיצוני' ואחוריי' דאחוריי' שמקבלי' היכלות דק\"נ שנק' חשך, משום שלפי אופן ההשתל' הבא בגילוי אור יש מקום למציאות החשך ורע באחוריי' דאחוריי' כו', והוא מה שיכול להיות אפי' בת\"ח שעוסקי' בתומ\"צ שיהי' של\"ש כלל וכמו בכנ\"י שעומדי' אב\"א כנ\"ל. אבל למעלה מכל עיקר ומקור ההשתלשלו' גם למעלה מחכ' דתורה אור שנק' אומנא כו', והוא בחי' מאור דתורה כמו שהוא בחכ' דעצמות א\"ס טרם שנמשך באור דחכמה דתורה במע\"ב שהוא למעלה מעה\"ד לגמרי ונק' עץ החיים שכולו חיים וטוב כו', כמו העוה\"ב שנק' יום שכולו טוב להיותו למעלה מהשתלשלו' דאבי\"ע הרי אינו בא בחיצוני' ואחוריי' כלל (משא\"כ אור דתורה שבא בהשתלשלו' דאבי\"ע יש בה ג\"כ פנימי' וחיצוני' כמו מגילה כתובה פנים ואחור<sup data-n=\"4512\">817</sup> כו' (כמו סתים <span data-k=\"pg\">1010</span> ּ וגליא דתורה כו') ולכך נק' התורה רק בחי' נובלות דחש\"מ<sup data-n=\"4513\">818</sup> כו') אבל לוחות הראשונות היו מב' עבריהם בלי חיצוני' ואחוריי' כלל כו').\n<b>וזהו</b> הטעם שיש בכח מאור הגנוז בתורה להחזירו למוטב שהוא להחזירו פב\"פ גם שהי' אב\"א כו', משום דאין בחי' פנים ואחור שייך רק בבחי' גילוי אור דתו' שבא בעה\"ד טו\"ר דוקא שלמשמאילי' בה סמא דמותא כו'. אבל בבחי' המאור שבה אין בחי' אחוריי' וחיצוני' כלל להיותו למעלה מכל ההשתל' דאו\"כ פנימי' וחיצוניות, ע\"כ לגבי בחי' המאור הזה שוין קמי' פנימי' וחיצוניות משום דגם חושך לא יחשיך<sup data-n=\"4514\">819</sup> לפניו כלל דאין חושך אלא בבחי' העלם המעלים לאור. אבל בחי' מאור למעלה מבחי' אור שממנו מקור מוצא האור שאין חשך מחשיך שם כלל",[["4509","814","<b>ולרשע מה לך לספר</b>: תהלים נ, טז [בדילוג]."],["4510","815","<b>לעולם יעסוק. . בא לשמה</b>: ראה פסחים נ, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191122\" data-slug=\"likkutei-sichot\" data-id=\"1300191122\">לקו\"ש</a> תולדות (כרך ג) ע' 781. וש\"נ. ויגש (כרך ה) ע' 245 הערה 37. עקב (כרך יט) ע' 122 הערה 15. פיה\"מ פו, ג."],["4511","816","<b>שאת זלעו\"ז עשה</b>: קהלת ז, יד."],["4512","817","<b>מגילה כתובה פנים ואחור</b>: ראה זכרי' ה, א. ב. יחזקאל ב, י. לעיל פ' בא קכד, ד. וש\"נ."],["4513","818","<b>התורה. . נובלות דחש\"מ</b>: ראה ב\"ר פי\"ז, ה. פמ\"ד, יז."],["4514","819","<b>דגם חושך לא יחשיך</b>: תהלים קלט, יב."]]],[2300550726,"וכחשיכה כאורה<sup data-n=\"4515\">820</sup> ממש כו' ולכך מחזירו למוטב מחשך לאור כנ\"ל (וזהו למוטב שהאור נק' טוב כמ\"ש וירא האור כי טוב<sup data-n=\"4516\">821</sup> ומוטב לשון מפעיל שהוא מקור כל רצון ושכל טוב וזהו בחי' מאור מקור כל אור דתו' שנק' טוב כו') וזהו שמתוך של\"ש ממש יעסוק לשמה ממש מכח ועוז דבחי' מאור שבה דוקא שמחזירו למוטב שהוא להיות פב\"פ כי כח הגדול הזה דבחי' מאור יכול לעשות מחשך אור שהוא מאחור פנים כו' (דפנים ואחור זהו שנעשה באו\"כ בצו\"ח<sup data-n=\"4517\">822</sup> דוקא כמ\"ש אחור וקדם צרתני<sup data-n=\"4518\">823</sup> כו' שהוא בחי' אדם בנר\"נ וכלים מוחא ולבא<sup data-n=\"4519\">824</sup> כו', אבל בבחי' מאור הנ\"ל א' כי לא אדם הוא<sup data-n=\"4520\">825</sup> למעלה גם מבחי' אדם דתורה ומצות כו').\n<b>ובכל</b> זה יובן במ\"ש ויקחו אליך שמן זית זך כתית למאור כו'. דהנה מבואר למעלה בענין וימינו תחבקני שבחי' רב חסד דעצמות שבימין העליון מחבק גם לאחוריי' דכנ\"י כמו שהן עומדי' אב\"א כו', ולכאורה אינו מובן דאיך שייך בחי' חיבוק כשעומד אב\"א כו'. אך זהו מדבר בימינו דחכמה דתוה\"ק שהיתה שעשועי' עצמיי' בבחי' מאור מקור כל אור דתורה שבאה למטה בהשתלשלו' דאבי\"ע וכמ\"ש מימינו אש דת למו מימין זה דבחי' מאור ניתן אור דתורה בבחי' אש כמו כה דברי כאש<sup data-n=\"4521\">826</sup> כו' באש שחורה ע\"ג אש לבנה<sup data-n=\"4522\">827</sup> כאור הנר שכלול מב' גווני' אור הלבן ואור השחור שהוא תושב\"כ ושבע\"פ כו'. וזהו שיוכל ימין זה לחבק גם בבחי' אחוריי' שיעמוד פב\"פ בתמידות ולא יסוג אחור (והוא ענין התוקף וחיזוק האמונה הפשוטה שבחיצוני' ואחוריי' דמעשה המצות שלא יפנו עורף לעולם), וגם אם פנו עורף יחזירם למוטב כנ\"ל וד\"ל. וזהו ויקחו אליך דוקא שמן זית כו' דגם ששרש נשמת משה הוא באור דתוה\"ק שבאה למטה בהשתלשלו' בפנימי' דחכ' דתורה אור באצי' כו', אך במשה נא' כי טוב<sup data-n=\"4523\">828</sup> הוא בטי\"ת רבתי שמקורו העצמי' הי' בעה\"ח דתורה כמו שהוא בבחי' מאור דתורה ש\"מ שהי' שעשועי' עצמיי' וכמ\"ש בו מן המים משיתיהו<sup data-n=\"4524\">829</sup> ממ\"ע שנק' יה\"ק<sup data-n=\"4525\">830</sup> כו', ולכך הי' בחי' שוש' דמלכא ממש שהי' ממוצע לחבר המשפיע במקבל כמו שירד ה' בעצמו על ה\"ס וא' אנכי<sup data-n=\"4526\">831</sup> ממש כו'. וזהו שיוכל משה לתקן גם למטה מטה גם בבחי' החכ' דתו' שירדה למטה בהשתל' לתקן ולברר לעה\"ד טו\"ר דבחכ' דתורה דוקא אתברירו<sup data-n=\"4527\">832</sup> שהוא הנק' שמן זית דשמן הוא בהעלם דחכמה קודם שנק' אור שהרי מן השמן יאיר האור כו', אך שמן זה הוא בהעלם דחכ' <span data-k=\"pg\">תקה</span> ּ דתורה שלמטה שנתלבשה ונתעלמה בדברים גשמיים דק\"נ להבדיל בין טו\"ר כו' שיהי' מקור מוצא לבחי' אור",[["4515","820","<b>וכחשיכה כאורה</b>: תהלים שם. ראה לעיל פ' וארא סד, א הערה 204."],["4516","821","<b>וירא האור כי טוב</b>: בראשית א, ד [בדילוג]."],["4517","822","<b>בצו\"ח</b>: בצורה וחומר."],["4518","823","<b>אחור וקדם צרתני</b>: תהלים קלט, ה."],["4519","824","<b>בנר\"נ וכלים מוחא ולבא</b>: ראה אבן עזרא משפטים כג, כה. לעיל פ' בשלח קמה, א. וש\"נ."],["4520","825","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["4521","826","<b>כה דברי כאש</b>: ירמי' כג, כט."],["4522","827","<b>באש שחורה ע\"ג אש לבנה</b>: ראה רש\"י שה\"ש ה, טז (ד\"ה שחורות). הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקעח."],["4523","828","<b>במשה נא' כי טוב</b>: שמות ב, י ובמנחת שי שם. ראה לעיל פ' שמות מג, ד. וש\"נ."],["4524","829","<b>מן המים משיתיהו</b>: שמות שם. ראה לעיל פ' שמות מג, א. וש\"נ."],["4525","830","<b>ממ\"ע שנק' יה\"ק [ ים הקדמוני]</b>: ראה גם לעיל פ' שמות מד, א. וש\"נ."],["4526","831","<b>שירד ה'. . על ה\"ס וא' אנכי</b>: יתרו יט, כ. כ, ב."],["4527","832","<b>דבחכ'. . אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא."]]],[2300550729,"דמאור עצמו שיהפוך גם החשך לאור והוא שיאיר בפב\"פ אל מול כו', וזהו שע\"י משה דוקא יקבל שמן זית זך דוקא שיהי' למאור שיומשך מבחי' המאור עצמו כדי להעלות נר תמיד פב\"פ כנ\"ל וד\"ל.\n<b>ומעתה</b> יש להבין מ\"ש שמן זית זך כתית דוקא ואז יהי' למאו\"ר דוקא כנ\"ל, ויש להקדים תחלה דאת זלעו\"ז עשה האלקי' ממש כמו שבסט' דקדושה יש אור וכלי ואו\"פ ואו\"מ וכללות ציור אדם בנר\"נ כו' וכמקיף דחי' יחידה, כך ממש בסט' דק\"נ בבחי' הרע שמנגד לטוב נמשך ג\"כ בסדר השתלשלו' כמו כל אופן ההשתלשלו' דבחי' הטוב דקדושה באו\"פ ואו\"מ כנ\"ל. דהנה שרש הרע בא ונמשך מחטא דעה\"ד טו\"ר שנמשך בב' אופנים, הא' בבחי' גילוי מציאות רע באופן בהגבלה והרכבה בדבר מה שניכר במציאות בגילוי מאין ליש כדרך כל בריאה שנברא מאין. ואע\"פ שאין רע יורד מלמעלה<sup data-n=\"4528\">833</sup> כלל זהו בבחי' האצי', אבל בירידת האור האלקי מאצי' לבריאה ע\"י צמצום דמסך המבדיל בהארה דהארה כו', את זלעו\"ז עשה שם האלק\"י' הזה כו' לברוא גם מציאות הפסולת וקליפה לפרי שהוא ק\"נ דרע שמנגד לטוב (וכיצה\"ר באדם שכולו רע ומנגד לחלק הטוב הנק' יצ\"ט ונלחם עמו ומתגבר עליו לפרקי' כמו בבינוני כו'). והנה בחי' הרע הזה יורד ומשתלשל ממדריגה למדריגה כמו בעולם הבריאה בחי' הנוגה שבו מיעוטו רע ורובו טוב<sup data-n=\"4529\">834</sup> ונכלל בטוב דקדושה, וביצי' חציו רע וחציו טוב ולפרקים הרע מתהפך גם הוא לטוב (כמו תאוות היתר לאכילה ושתי' וכה\"ג שיהופך גם הוא לטוב אם אין בו רע גמור כו', ובעשי' הוא רובו רע והוא חום התאוה הרעה שבוער כאש כו' וכידוע. וכל זה הנה נמשך בציור קומה דאדם ג\"כ כמו הרע שבשכל כחכמים המה להרע<sup data-n=\"4530\">835</sup> ולא להטיב לראות ולהשיג רק ברע וחוב, וכן במדות כמו אהבת רע מטוב כבעל לה\"ר ומדבר מרמה והורג רעהו בחץ שחוט לשונו<sup data-n=\"4531\">836</sup> כו' כתער מלוטש<sup data-n=\"4532\">837</sup> כו' כמלשינות כו' וכן רציחה בכעס ברתיחת הדמים וגסות וחוצפה ועזות יתירה כו' שהן במדות בלב, וכן במעשה ממש שפועל ועושה כל רע שזהו בבחי' רגל כו'. וכ\"ז נק' או\"פ מוגבל בכלים שונים כמו בחי' הטוב שבקדושה שמוגבל באו\"כ דקדושה במוח ולב ומעשה בציור אדם דקדושה כך בזלעו\"ז נק' אדם בליעל<sup data-n=\"4533\">838</sup> כו'. וכמו שיש בחי' או\"מ באדם דקדושה שנק' צלם דחי' יחידה, כך בבחי' הרע דק\"נ יש ג\"כ בחי' מקיף שמקיף וסובב לכל בחי' או\"כ דרע בגוף שנקרא עומק רע והוא כמו שיש בקדושה עומק טוב<sup data-n=\"4534\">839</sup> כו', ונק' כתרין",[["4528","833","<b>שאין רע יורד מלמעלה</b>: נסמן לעיל פ' יתרו רעא ד."],["4529","834","<b>הבריאה. . מיעוטו רע ורובו טוב</b>: נסמן לעיל פ' משפטים רצד, א הערה 61."],["4530","835","<b>כחכמים המה להרע</b>: ירמי' ד, כב."],["4531","836","<b>בחץ שחוט לשונו</b>: ע\"פ ירמי' ט, ז."],["4532","837","<b>כתער מלוטש</b>: תהלים נב, ד."],["4533","838","<b>אדם בליעל</b>: משלי ו, יב."],["4534","839","<b>עומק רע. . עומק טוב</b>: ס\"י פ\"א, מ\"ה. ראה גם שע\"ת ד, א."]]],[2300550732,"דק\"נ בחי' כת\"ר שלמעלה מחו\"ב ומדות ונה\"י דק\"נ שמקיף מראש לרגל שבהן עצמן כא' ממש מבלי ימצא ראש וסוף כו'. כעצמות הרצון דתאוה רעה להיותו מקור כל רצון רע וכהולך בשרירות לבו רק רע כו' שמקיף וסובב לרע שבמוח ברע<sup data-n=\"4535\">840</sup> שבמעשה כא', להיותו למעלה מן המוחי' דחו\"ב <span data-k=\"pg\">1012</span> ּ דק\"נ, וכמו וירא העם כי בר\"ע הוא<sup data-n=\"4536\">841</sup> מוקף בעומק העלם הרע שבלתי מרגישי' כלל. שכמו שיש בטוב טוב המורגש כמו בהתפעלות רצון מורכב בשכל וטעם ובהתפעלות אהבה בלב במורגש כו', ויש אה\"ר בהעלם העצמות עומק הרצון שבלתי מורכב ומורגש ברצון ושכל וטעם רק הוא בהעלם ומקור כל התפעלו' רצון ושכל טוב כו'. כך ממש בעמ\"ר, דק\"נ הוא מקור בהעלם לכל רצון ושכל ומדות דרע ועדיין אינו מורגש במציאות רע זהו שנק' מקיף דרע מראש לרגל כעיגול כו' שאין דבר טוב בקדושה יכול להוציאו משם, כ\"א ג\"כ בבחי' מקיפים דטוב דקדושה דוקא שלמעלה מן החכ' וטעם ולא בבחי' החכמה ומדות דאו\"פ דקדושה כלל. וראי' לזה ממ\"ש כי אין מעשה וחשבון<sup data-n=\"4537\">842</sup> ודעת בשאול אשר אתה הולך שמה כו', פי' כי בחי' קליפה דשאול זהו בחי' מקיף דרע דק\"נ שלמעלה מחו\"ב ומדות דק\"נ כמו ג' הנה לא תשבענה שאול<sup data-n=\"4538\">843</sup> כו'. וזהו שא' כי אין מעשה וחשבון ודעת להיו' שקליפ' דשאול הוא בחי' הכתר דקליפ'<sup data-n=\"4539\">844</sup> שמקיף ראש וסוף כא' שהשאול עמוקה ביותר ונק' עמ\"ר כנ\"ל ע\"כ אין חשבון כו', שאינו בסדר והדרגה דמעשה וחשבון ודעת שהוא בציור אדם בחב\"ד חג\"ת נה\"י דמעשה בנה\"י וחשבון במדות ודעת במוחין, ובשאול בכת\"ר דק\"נ שוה מעשה עם דעת רגל עם ראש עד שאין שם מעשה ולא חשבון ודעת וחכמה כו'. ולזאת לא ינצל מן השאול הזה ע\"י מעשה המצות באו\"כ בחי' רגל ולא בחשבון דאוי\"ר ודעת במוח ושכל, בחי' הטוב הזה אינו רק בחי' או\"פ בכלי שברע דשאול בעומ\"ר תקיף וחזק מכל זה וע\"כ אין מעשה וחשבון שם כו', ולא יש בכח שום דבר טוב בקדושה האלקי' לעמוד נגד כח הקליפה דשאול כ\"א באותו כח דכת\"ר שבו שזהו במקיף דכת\"ר דקדושה בחי' עמ\"ט כנ\"ל וד\"ל.\n<b>וביאור</b> ענין זה הנה אנו רואי' ביצה\"ר ויצ\"ט שבאדם שזהו הנה\"ב ונה\"א כידוע, שכאשר יתגבר באדם חלק הרע שבנה\"ב להתפעל באיזה תאוה רעה שבאה במורכב באיזה טעם ודבר באהבה התלויה בדבר כו', שזהו מדות רעות דק\"נ שנולדים מן השכל וטעם שמתבונן ומעמיק דעתו להתאוות",[["4535","840","<b>ברע</b>: תיבה זו אינה ברורה בגוכתי\"ק. ד: עד רע."],["4536","841","<b>וירא העם כי בר\"ע הוא</b>: ראה תשא לב, כה. כב. מאמרי אדה\"א הנחות תקע\"ז ע' קכא. וש\"נ."],["4537","842","<b>כי אין מעשה וחשבון</b>: קהלת ט, י [בדילוג]. ראה זהר קרח קעח, א. פינחס רכ, ב. ביאוה\"ז פינחס קי, סע\"ד ואילך. מאמרי אדה\"ז תקס\"ב כאן (ע' שנ). מאמרי אדה\"א קונטרסים ע' רנ."],["4538","843","<b>ג' הנה לא תשבענה שאול</b>: משלי ל, טו. טז."],["4539","844","<b>שאול. . הכתר דקליפ'</b>: ראה גם מאמרי אדה\"ז תקס\"ב כאן (ע' שנ)."]]],[2300550735,"באהבה רעה כו' כמו לתאוה יבקש נפרד<sup data-n=\"4540\">845</sup> מי שנפרד מדעת והשג' האלקי' ונמשל כמו בהמה כו', אך לזאת יוכל להיות הצלה שינצל ויטהר מטומא' מחשבה ודעת להוליד אהבו' ותאוות רעות, והוא ע\"י שיעמיק דעתו ורצונו באור תורת ה' ועבודתו האלקי' וזהו ההצלה לכל נפש שנטמאה במח' ומדות ברע במורגש שתטהר, וכמו ע\"י אש הגיהנם שמוציא האש הזר הזה ויכול לבא לג\"ע אח\"כ וגם מתאוות היתר יוכל ליטהר ע\"י אש דק יותר והוא בטבילה בנה\"ד כידוע. אבל בחי' עמ\"ר דמקיף הרע הנ\"ל אין בתאות כזאת שהיא בחי' כלי להכיל כלל להיותה למעלה מהגבלת השכל והלב לגמרי, והיינו כשיעמיק רצונו בתאוותיו בבחי' עצמיות הנפש ממש בלתי מוגבל בכלי המוח והלב כלל זהו שבא בעמקי שאול תחתי' דוקא, כי השאול מקור לעצמיות הרע דכל תאוות רעות ושם מקורם העצמיי' ולא הגיהנם וכה\"ג. ולזאת כל מדות רעות בגילוי או\"כ יתוקן הפגם בגיהנם כי שם מקורם ויעלו משם אבל לא ירדו <span data-k=\"pg\">תקו</span> ּ בשאול כי אין השאול מקורם, אבל החוטאי' בעצם הרע דמקיף דק\"נ (כמו בפר\"ע לילך בשרירות לבו כו' כמ\"ש והתבר\"ך בלבבו לאמר<sup data-n=\"4541\">846</sup> שלום יהי' לי למען ספות הרוה כו' שיקבלו החיצוני' דק\"נ בחו\"ב ומדות רעות דק\"נ תוס' יניקה ע\"י מאור הכתר דקדושה, וכמו חטא העם הזה חטאה גדולה<sup data-n=\"4542\">847</sup> שפגמו באור הכתר ע\"י ע\"ז ונאמר בהם ויצאו וראו בפגרי<sup data-n=\"4543\">848</sup> כו' הפושעים בי ממש בגופא דמלכא שהוא בחי' הכת\"ר<sup data-n=\"4544\">849</sup> שאשם לא תכבה כו' שזהו היורד לשאול שלא יעלה כמ\"ש כי אין מעשה וחשבון כו' שלא יועיל לו שם שום זכות דמעשה וחשבון דטוב כו' כנ\"ל (וכמו האפיקורסי'<sup data-n=\"4545\">850</sup> והמינים שיורדים לשאול ואינן עולים כנ\"ל<sup data-n=\"4546\">851</sup> ), כי השאול דוקא שם הוא מקור לרצון עצמו דרע הזה כענין עבירה מלפפתו<sup data-n=\"4547\">852</sup> כו' ונק' ג\"כ כף הקלע<sup data-n=\"4548\">853</sup> כו' שאין לו מנוחה ותיקון לעולם כידוע).\n<b>אך</b> הנה אעפ\"כ הרי אנו מוצאים שעולים גם מן השאול ואבדון<sup data-n=\"4549\">854</sup> כמ\"ש ה' מוריד שאול ויעל<sup data-n=\"4550\">855</sup> כו', הענין הוא דודאי א\"א שיעל משאול ע\"י חשבון ומעשה כנ\"ל כי אין עליה לנפש החוטאת ע\"י זכות המעשה וחשבון כ\"א כשפגמה בחו\"ב ומדות כו' שזהו בגיהנם, כי בחי' האדם דקדושה שהוא בצלם האלקי' כשהוא עומד במעלה עליונה במוחי' ומדות דקדושה באוי\"ר שכלי' וטבעיי' עד בחי' המעשה הטוב לא יפול הנופל ברע כלל וכלל. אך כאשר נתרוקן מכל אור וחיות דקדושה",[["4540","845","<b>לתאוה יבקש נפרד</b>: משלי יח, א."],["4541","846","<b>והתבר\"ך בלבבו לאמר</b>: נצבים כט, יח [בדילוג]."],["4542","847","<b>חטא העם הזה חטאה גדולה</b>: תשא לב, לא. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שפב. וש\"נ. נ\"ך ס\"ע תר ואילך. וש\"נ."],["4543","848","<b>ויצאו וראו בפגרי</b>: ישעי' סו, כד."],["4544","849","<b>הפושעי'. . בגופא דמלכא. . הכת\"ר</b>: ראה זהר יתרו פה, ב. עט\"ר ע' 132 ואילך. שע\"ת פה, ד. לעיל פ' בשלח רכט, א. לקמן פ' פקודי תנד, ג."],["4545","850","<b>האפיקורסי'</b>: ראה גם אמ\"ב שער הציצית צו, ג."],["4546","851","<b>כנ\"ל</b>: תיבה זו אינה ברורה בגוכתי\"ק. ד: כלל."],["4547","852","<b>עבירה מלפפתו</b>: סוטה ג, ב. ראה גם שע\"ת עא, ד."],["4548","853","<b>כף הקלע</b>: ראה גם בענין כף הקלע שערי אורה ו, א ובהערה 2."],["4549","854","<b>השאול ואבדון</b>: משלי טו, יא. כז, כ. ראה ערובין יט, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680115\" data-slug=\"torat-chaim\" data-id=\"2300680115\">תו\"ח מקץ רטז, ג</a> ובהערה 42. מאמרי אדה\"א בראשית ע' קג וע' תקנח. קונטרסים ע' רנ. במדבר ח\"ב ע' תשסז. שה\"א בהקדמה ה, ב."],["4550","855","<b>ה' מוריד שאול ויעל</b>: שמו\"א ב, ו [בדילוג]."]]],[2300550738,"בבחי' הפנימי' ונשאר רק בבחי' אחוריי' וחיצוני' דמעשה בלי כוונה כלל כמו מת יחשב ויכול ליפול בהיכלות דק\"נ בתחלה בתאוות היתר ומהיתר לאיסור כו', כידוע דמבחי' אחוריי' דקדושה מקבלים היכלות דק\"נ<sup data-n=\"4551\">856</sup>, ולכך כשעומד האדם באחוריי' דטוב דקדושה קרוב הוא מאד להיכלות דק\"נ (והוא העצבות שנופל בעצמו ביאוש שמזה יפול בתאוות רעות ממש כידוע). ואמנם בחי' הטוב שבנה\"א עומד לנגד הרע שבו כי בחי' הרע שבו הוא לפ\"ע הטוב שלו דוקא (ולכך א' דכל הגדול מחבירו<sup data-n=\"4552\">857</sup> שהטוב שלו גדול יצה\"ר שלו גדול יותר) ויכול להצילו מן הגיהנם כנ\"ל. אך מי שנופל בעמ\"ר והטומאה ונטבעה נפשו החומריות בעמקי השאול שהוא מקור כל רע בעצם אין דבר נגדו בטוב דקדושה שיוכל להוציאו משם, כי כל עבודתו בתו\"מ ובאוי\"ר בתפלה לא יועיל שם כנ\"ל כ\"א בבחי' מקיף דנר\"נ דקדושה. והיינו בהתעוררו' בעצמות הרצון בעומק לעומק כמו עומ\"ר דתאוה שיהי' היפוכו ממש, וא\"א להיות זה כ\"א בעמקות הרצון ותענוג בעצמות הנה\"א שמלובש בענין היפוכו שהוא ענין עוצם עומק הלב נשבר ונדכה מאד בצער שנוגע בעצמיות ממש שנק' תשובה עילאה שמקירת הלב ממעמקי' קראתיך<sup data-n=\"4553\">858</sup> כו' עד שמואס בחייו ממש שעי\"ז יוצא גם משאול תחתית וע\"ז א' מוריד שאול ויעל כו' ואע\"פ שפשעו בי ממש בבחי' כת\"ר, אבל ע\"י עמקות דביטול הרצון הזר בעצם מתקן לפגם הכתר ויוצא מעיגול ומקיף דק\"נ לעיגול ומקיף דכת\"ר דקדושה ונעשה מפש\"ע רב שפ\"ע<sup data-n=\"4554\">859</sup> ומנגע עונג<sup data-n=\"4555\">860</sup> כו' וד\"ל.\n<span data-k=\"pg\">1014</span> ּ<b>ובזה</b> יובן מארז\"ל דיפה שעה אחת<sup data-n=\"4556\">861</sup> בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב כו', ויש להבין בזה דהלא העוה\"ב הוא שכר המצות ואיך המע\"ט עצמן בעוה\"ב<sup data-n=\"4557\">862</sup> גדול מעוה\"ב. ועוד מ\"ש תשובה ומע\"ט ומה שייך זע\"ז, ומה שהקדים תשובה למע\"ט<sup data-n=\"4558\">863</sup>, ומה ענין תשובה לעוה\"ב שהתשובה היא בלא תו\"מ כלל. ועוד איך יחובר ב' ענינים דתשובה ומע\"ט יחד, הלא התשובה באה מעומק לב נשבר ונדכה בתכלית שנק' תשובה עילאה כנ\"ל, ומע\"ט צריך להיות בשמחה וטוב לבב דוקא כמ\"ש עבדו את ה' בשמחה וכתיב תחת אשר לא עבדת כו' בשמחה וטוב לבב<sup data-n=\"4559\">864</sup> כו'. והוא ענין שמחה ש\"מ שצ\"ל בכל איש מישראל כמו שאו' וישמחו בך ישראל<sup data-n=\"4560\">865</sup> מקדשי שמך במצות כו' שקדשנו במצותיו כו' וכתיב ויספו ענוים שהן צ\"ג בהוי' שמחה בשמחה ש\"מ דוקא כידוע.",[["4551","856","<b>דמבחי'. . מקבלים היכלות דק\"נ</b>: ראה גם לעיל פ' יתרו עדר, א ובהערה 25."],["4552","857","<b>דכל הגדול מחבירו</b>: סוכה נב, סע\"א. ראה גם מאמרי אדה\"א נ\"ך ע' שנא. וש\"נ. קונטרסים ע' שעח."],["4553","858","<b>ממעמקי' קראתיך</b>: תהלים קל, א."],["4554","859","<b>מפש\"ע רב שפ\"ע</b>: תהלים יט, יד. ראה זהר (אד\"ר) נשא קלג, א. מאמרי אדמו\"ר האמצעי דברים ח\"א ע' שז. וש\"נ. הנחות תקע\"ז ע' רמז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670499\" data-slug=\"torat-chaim\" data-id=\"2300670499\">תו\"ח בראשית כח, ב</a> ובהערה 10. לעיל פ' שמות כ, ג."],["4555","860","<b>ומנגע עונג</b>: ראה ס\"י פ\"ב, מ\"ד ובמפרשים שם. לעיל פ' שמות כ, ג. וש\"נ."],["4556","861","<b>דיפה שעה אחת</b>: אבות פ\"ד, מי\"ז [ושם: יפה — ראה גם לעיל פ' שמות ט, א. וש\"נ]."],["4557","862","<b>בעוה\"ב</b>: כ\"ה בגוכתי\"ק."],["4558","863","<b>תשובה ומע\"ט. . למע\"ט</b>: ראה גם לעיל פ' וארא סו, א. וש\"נ."],["4559","864","<b>תחת אשר לא עבדת. . וטוב לבב</b>: תבוא כח, מז [ושם: ובטוב — ראה גם לעיל פ' בשלח רה, ג. וש\"נ]."],["4560","865","<b>וישמחו בך ישראל</b>: נוסח ברכת היום דיו\"ט הוא: כל ישראל. ראה גם לעיל פ' בשלח קעח, ב. וש\"נ."]]],[2300550741,"<b>אך</b> הנה ידוע דכל עיקר חיי העוה\"ב אינו רק בחי' זיו ועונג העליון שבעצמות א\"ס ב\"ה כמו זיו השכינה בג\"ע העליון שנשמות דבריאה מתענגי' על הוי' בשכל ועונג מורגש דוקא, וכך יהי' גם בבחי' עונג העצמי' הנעלם דעוה\"ב שנק' עדן העליון שיבוא בגילוי דוקא במורגש בחיי עולם בגופי' קדושי' כמ\"ש ונחי' לפניו ממש, וזהו שבא דוקא מעונג העצמי דנה\"א בתו\"מ לשמן בכוונה ורעותא דלבא שזהו בשמחה וטוב לבב דוקא מרוב כל דעוה\"ב שנק' כל<sup data-n=\"4561\">866</sup> כידוע וד\"ל. והיינו לפי ששרש המצות הוא בעצמות פנימי' התענוג הפשוט שבפנימי' רצונו העליון שזהו עצמו שיבוא בגילוי ממש בעוה\"ב ונק' חיי העוה\"ב ולכך צ\"ל שמחה ש\"מ בטוב לבב שמעוררי' לפנימי' העונג כו', אך זהו רק בבחי' גליא והוא מה שיכול לבא מהעלם עצמות התענוג הפשוט לגילוי אור וחיות לנשמות בעוה\"ב, אבל שעה א' בתשובה בעוה\"ז יפה יותר מכל חיי העוה\"ב, לפי שהתשובה באה מקירת הלב בלב נשבר מאד ונבזה בעיניו נמאס ומואס בחייו ממש מצד עוצם המרירות בעצמיות נפשו על ריחוקו מה' אחד שנגעה לו עד הנפש, ועי\"ז יבא לבחי' ביטול הרצון הזר שנתקשר שם בתחלה בתכלית הביטול בעצם שזהו שמהפך חשך לאור ורע עצמו לטוב שהוא למעלה הרבה מגוף האור ותענוג שבעוה\"ב הבא בגילוי שנק' חיי העוה\"ב, כי ביטול עצמיות הרצון בתש\"ע זו מגיע למעלה גם מן הרצון והתענוג שבמצות. ולכך בע\"ת אמיתי' גדולי' מצ\"ג בתו\"מ והיינו למעלה מבחי' אור דחכמה ותענוג ורצה\"ע שבתו\"מ משום דמשכא בחילא יתיר<sup data-n=\"4562\">867</sup> כו', ולזה אין צ\"ג יכולים לעמוד כלל במקום בע\"ת<sup data-n=\"4563\">868</sup>, כי אור שלהם בתו\"מ לא יוכל לעמוד במקום שההעלם דחשך סתרו שהוא חשמ\"ל העליון שנהפך החושך העליון לאור והוא מה שלא יכול לבוא בגילוי גם בעוה\"ב. וזהו ויספו ענוים בתו\"מ בשמחה ש\"מ בהוי' שמחה אבל אביוני אדם שהן בע\"ת בלא אור דתו\"מ כלל בקדוש ישראל עצמו יגילו למעלה משם הוי' וכו' (וזהו שאמר עשה רצונו כרצונך<sup data-n=\"4564\">869</sup> בקיום המצות כדי שיעשה <span data-k=\"pg\">תקז</span> ּ רצונך כרצונו בעוה\"ב, בטל רצונך בעצם הרע כתש\"ע הנ\"ל כדי שיבטל רצון אחרים דהיינו היפוך החושך דק\"נ שלמעלה מאור דתו\"מ כו', וכמו שא' טוב מאד זה מ\"ה<sup data-n=\"4565\">870</sup> כשנהפך ממות לחיים יותר מחיים וטוב עצמו והוא כשארור נעשה ברוך שמקטרג עצמו דרע יהפך לטוב כידוע. וזהו שא' בר\"מ דמשה לא זכה לתשובה רק קודם מותו<sup data-n=\"4566\">871</sup> אע\"פ שהי' צדיק גמור טוב בעצם כנ\"ל וד\"ל.",[["4561","866","<b>דעוה\"ב שנק' כל</b>: ראה גם לעיל פ' בשלח קמט, א. וש\"נ."],["4562","867","<b>בע\"ת. . דמשכא בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. לעיל פ' שמות לז, א. וש\"נ."],["4563","868","<b>אין צ\"ג יכולים לעמוד כלל במקום בע\"ת</b>: ראה ברכות לד, ב. לעיל פ' שמות מא, א. וש\"נ."],["4564","869","<b>עשה רצונו כרצונך</b>: אבות פ\"ב, מ\"ד."],["4565","870","<b>טוב מאד זה מ\"ה</b>: בראשית א, לא. ראה ב\"ר פ\"ט, י. לעיל פ' בא קכג, ג. וש\"נ."],["4566","871","<b>דמשה. . לתשובה רק קודם מותו</b>: ראה זהר (רע\"מ) משפטים קיד, ב. תצא רעח, ב. לעיל פ' שמות לז, א. וש\"נ."]]],[2300550744,"<b>אך</b> עכ\"ז יפה שעה אחת בתשו' ומע\"ט יחד ולא בתשובה לבד ואע\"פ שהן ב' הפכים לכאורה צער ושפלות ומרירות עם שמחה וטוב לבב שבמע\"ט שלא ישכנו יחדיו כו', ואמנם אדרבה לזה אמר שיקדים התשובה למע\"ט דוקא וכמו צ\"ג שנעשי' בע\"ת כר\"מ דיעשה מצ\"ג בע\"ת, והוא מה שאחר המרירות ושפלות ולב נשבר כבע\"ת אמיתי' יבא מזה עצמו אח\"כ לשמחה וטוב לבב בעשותו המצות שזהו עיקר השמחה כשבאה מהיפוך להיפוך כמו ממות לחיים ומאפילה לאור גדול כיוצא משבי' וס\"נ<sup data-n=\"4567\">872</sup> וכה\"ג שישמח בנפשו שמחת הנפש בעצמה בראותה אור כו'. וכך הוא בענין שמחה ש\"מ שבאה אחר הענוה ושפלות אמיתי' בלב נשבר בעומק מאחר שנתרחק מאלקות בחטאי' או שאר תאוות זרות כו' שיגיע לבחי' ענוה יתירה שהוא שפל מכל אדם ונבזה בעיניו נמאס מאד בבחי' רגל להיות נדרס כעפר לכל כו' לפי שמכיר את מקומו השפל היטב באמת לאמיתו, אך כשבא לידי מצוה יתבונן שבזה יקרב ה' אל נפשו השפלה ויאיר לו גם בחושך לפי שזהו פנימי' רצונו וממשיך גילוי אור א\"ס עצמו במצוה זו דגם חושך לא יחשיך לפניו כו', ע\"כ ישמח בשמחה ש\"מ זו יותר מצ\"ג באור הוי' שבנפשם האלקי' בעשותם המצות בשמחה וטוב לבב שהן שמחי' שמחת עצמם בקרבתם לפני ה' באהבה ודביקות הנפש בכוונה כו', והבע\"ת ישמח במצוה ולא בשמחת עצמו כלל כי הוא שפל ועניו בעצמו יותר מעפר כו' כמו שהי' רק במה שיוצא ממות לחיים ומאפילה דטומאה לקדושה במצוה זו זהו שמחה מצד בחי' אלקות לבד שלמעלה מאור התענוג שבמצות ובעוה\"ב כנ\"ל וד\"ל.\n<b>וזהו</b> שא' תשובה ומע\"ט בעוה\"ז שניהם יחד דוקא כנ\"ל יפה יותר מכל חיי העוה\"ב, דאע\"פ ששמחה ש\"מ מזה יבוא העונג העצמות בגילוי בעוה\"ב וז\"ש בשמחה וטוב לבב מרוב כל דעוה\"ב כנ\"ל אבל למעלה מרוב כל דעוה\"ב וגעה\"ע בזיו השכינה מעונג דע\"י בכתר מל' דאצי' (שנק' זיווא עילאה דע\"י<sup data-n=\"4568\">873</sup> שמאיר בבינה שבמל' שנק' כל להשפיע לנשמות בכאו\"א כו') זהו בתשו' ומע\"ט בעוה\"ז במה שהשמחה ש\"מ באה מתוך הענוה והשפלות דבחי' תשובה עילאה דוקא כנ\"ל (לפי שבזה יש יתרון האור מהיפוך החשך לאור שאין אור דתו\"מ מגיע שם כנ\"ל) וכמ\"ש ואביוני אדם בקדוש כו' למעלה משם הוי' דהיינו אור דתו\"מ דצ\"ג כו'. ועכ\"ז בתשובה עילאה לבדה אע\"פ שנהפך החושך לאור שיש בכלל מאתים<sup data-n=\"4569\">874</sup> כו' לא יעלה למעלה מחיי העוה\"ב <span data-k=\"pg\">1016</span> ּ כלל, ומוכרח לאמר שיש שרש לאור דתו\"מ דצ\"ג למעלה גם מבחי' החושך דחשמ\"ל העליון והיינו בבחי' המאור עצמו דעצמות א\"ס ב\"ה שלמעלה מאור דתו\"מ, וכנ\"ל בענין מדריגה הב' דתו' אור שנק' מאור שבה כו' שיכול להחזירו למוטב והוא להפוך גם חושך גמור דרע עצמו לטוב",[["4567","872","<b>וס\"נ</b>: וסכנת נפשות."],["4568","873","<b>זיווא עילאה דע\"י</b>: ראה גם לעיל פ' שמות לה, א. וש\"נ."],["4569","874","<b>שיש בכלל מאתים</b>: ב\"ק עד, א."]]],[2300550747,"כנ\"ל, והוא מה שיוכל להפוך מאב\"א להיות פב\"פ כנ\"ל ואע\"פ שאין כח זה באור דתו\"מ כלל מצד עצמו. אך באמצעות האור דתו\"מ בבחי' מאור עצמו כמו שהי' תוה\"ק בחי' שעשועי' עצמיי' (שלמעלה מבחי' גילוי אור זה אפס קצהו בעוה\"ב שנק' פר\"ס<sup data-n=\"4570\">875</sup> ש\"י מחצה<sup data-n=\"4571\">876</sup> מזה התענוג העצמיי') מזה יגיע גם הבע\"ת לבחי' מאור שיחזירנו למוטב. וזהו מאור שבה דוקא שהן ת\"ח העוסקים בתורה של\"ש, אבל בלא תו\"מ כלל אפי' של\"ש כו' לא יוכל להגיע בתשו\"ע הנ\"ל לבדה רק לבחי' החשמ\"ל העליון שיהפך לאור אבל לא בבחי' מאור עצמו דקמי' כחשיכ\"ה כאורה ממש בשוה כו' כנ\"ל. ואין זה המאור מאיר רק בשמחה ש\"מ דצ\"ג שנעשו בע\"ת שמגיע למאור עצמו ולא באור דתו\"מ לבד, ולא בתשובה לבד כ\"א בתשובה ומע\"ט יחד כנ\"ל בשמחה ש\"מ שמתוך תכלית השפלות ועומק בלב נשבר בתכלית (כמו דוד המלך שהי' בע\"ת אמיתי בעומק הלב להיות שמח מאד במצות כמובן באשרי תמימי דרך<sup data-n=\"4572\">877</sup> שחשקה נפשו במצו' וזהו שמחה שמן הענוה כנ\"ל). לכך הי' יעקב צ\"ג ונעשה בע\"ת בלבשו ב\"ע<sup data-n=\"4573\">878</sup> החמודות שבזה זכה לקבל מברכו' דיצחק, ודוקא יעקב שהי' צ\"ג איש חלק הוי' במאור עצמו מטעם הנ\"ל. ולזה משה זכה לתשובה עילאה במאור עצמו וכן משיח שיעשה לצ\"ג בע\"ת, כי כל בירורים דתהו שנק' חושך להפוך לאור הוא על<sup data-n=\"4574\">*879</sup> צ\"ג שיהי' בע\"ת דוקא מטעם הנ\"ל ולא בתשו' עילאה לבדה כנ\"ל וד\"ל (ורמז לדבר זה בגמ' בשאלו כל חללי דעלמא מ\"ט עיזי מסגי ברישא והשיבו כברייתו ש\"ע ברישא חשוכא כו' והחושך נהפך לאור ע\"י צ\"ג דוקא, וז\"ש ויהי ערב ויהי בקר שערב נכלל בבוקר דוקא אז נק' יום אחד שהוא בחי' אחדות פשוט דבחי' מאור כנ\"ל שגולל אור מפני חשך<sup data-n=\"4575\">879</sup> וחשך מפני אור כו', וז\"ש ולילה כיום יאיר לע\"ל שיהי' יום שלם מחושך ואור יחד דוקא ונק' יום הגדו\"ל כידוע וד\"ל).\n<b>ובכל</b> זה יובן מ\"ש ויקחו אליך שמן זית זך דוקא וכתי\"ת דוקא וע\"י משה אז יהי' עולה לבחי' מאור עצמו דעצמות א\"ס ממש כנ\"ל כדי להעלות נר תמיד (בלילה כביום כמו שיהי' לע\"ל כנ\"ל), דהנה יש להבין בתוס' ביאור בענין הנ\"ל דתשובה בלא מע\"ט כלל אינו עולה למעלה כ\"כ כמו בתשובה דצ\"ג נעשים בע\"ת דוקא כנ\"ל מצד שרשם במאור עצמו שיהפכו חושך לאור כו', דא\"כ לכאורה אין זה מצד התשובה בעצם רק מבחי' מאור שבהן שיחזירו למוטב כו'. אך הענין הוא דודאי עיקר התשובה הוא בחי' לב נשב\"ר ונדכא בשפלות ומרירות עד שמואס בחייו ממש כו', שזהו ודאי מה שמבחי' גסות ויש דתוקפא דנפשא בחוצפא ועזות בשרירות הלב נעשה רך מאד ונשבר לחלקים כעפר תיחוח כי נתבטל הגסות בתכלית ונעשה בבחי' אין ממש, וזהו שפלו' שמן גודל",[["4570","875","<b>בעוה\"ב שנק' פר\"ס</b>: ראה גם לעיל פ' בשלח רטז, ב. וש\"נ."],["4571","876","<b>פר\"ס. . מחצה</b>: נסמן לעיל פ' וארא נט, ג."],["4572","877","<b>באשרי תמימי דרך</b>: תהלים קאפיטול קיט."],["4573","878","<b>ב\"ע</b>: בגדי עשו."],["4574","*879","<b>על</b>: כ\"ה בגוכתי\"ק."],["4575","879","<b>שגולל אור מפני חשך</b>: ראה לעיל בריש המאמר (שיח, ג)."]]],[2300550750,"המרירות <span data-k=\"pg\">תקח</span> ּ בחשבונו היטיב מח\"נ ששפל מכל אדם בזה ונעשה כעפר לכל כו' כנ\"ל. אך יש שפלות וענוה אחרת שאינה באה כלל מחמת פחיתת ערכו בח\"נ ותאו' גופניו' ולא מחמת מרירות מחשבון נפשו במעשיו המכוערים וכה\"ג, רק בחי' שפלות וענוה יתירה בעצם מהותו שאינו תופס מקום כלל וכלל בעצמו וכאילו אינו במציאות ומהות דבר מה לגבי כל האדם שהכל גבוהים ממנו ונפשו כעפר ממש לכל אדם יהי' מי שיהי', רק מצד שפלותו העצמי' (בל\"א נישקייט בעצם ער איז ג ר נישט באיי זיך בתכלית) שאינו מרגיש עצמו כאילו הוא מותר בעולם וכמו אברהם שקרא עצמו עפר ואפר<sup data-n=\"4576\">880</sup> ממש וכן משה הי' עניו ביותר מכל האדם כו' מצד שהי' בחי' מ\"ה ואין בעצם כאילו אינו במציאות כלל וכלל לכך כל אדם הי' תופס מקום אצלו להיות נפשו כעפר ממש לכל ונעשה מדרס לכל מפני שאינו מרגיש א\"ע כלל וכלל כו'. וזהו הגורם ממילא שיהי' נבזה בעיניו נמאס כ\"כ עד שלבו נשבר תמיד בעצם שאין לו חפץ בחייו הגשמי' וכמו מ\"ש הטבעי' וכל יש וגסות וגדולה וכל הון וכה\"ג שנאה נפשו ולא יוכל לקבל, וממילא כל מה שיש בביטול הגסות והעזות וחוצפא שנשבר והי' לאי\"ן ממש זהו בא מכח השפלות ולב נשבר בבחי' אי\"ן ומ\"ה בעצם הזה (שזהו מצד שרש דצ\"ג בבחי' אין האמיתי דמאור עצמו שבכחו יש לעשות מיש וגסות דתהו להיות בבחי' אין שהוא תשובה דבע\"ת בלב נשבר ונדכא מחשבונו בשפלותו שנתרחק שיצר לו ויהי' הקשה רך בביטול היש וגסות שזהו תלוי לפ\"ע בחי' אין ומ\"ה העצמי שקדם לחוש\"ך שהוא גסות דחוצפא ותוקף הלב למטה (וזהו שהי' משה עיקר המנגד לפרע\"ה שהוא עורף גסות דכת\"ר דק\"נ<sup data-n=\"4577\">881</sup> רק מחמת שפלותו וענוה שלו העצמי' בבחי' אי\"ן האמיתי שכל י\"ש וגסות נופל לפניו מיד ונעשה אי\"ן כמו פרעה שהי' נופל ומתבטל מגסותו כשראה למשה, ולכך המדברים אל פרעה הוא מש\"ה דוקא ואח\"כ אהרן ולישראל הי' אהרן תחלה<sup data-n=\"4578\">882</sup> שושדמ\"ט להעלות לנש\"י ואח\"כ משה כו' כמ\"ש במ\"א. שעיקר היסוד להתיש כח הסט\"א שהוא הגסות והחומריות דרע בעצם כל היום בלכתו בשוק שלא בשעת הכושר בתפלה הוא רק בשפלות דמ\"ה בעצם דמשה (נישקייט בעצם) שנופל בזה כל גסות הלב ונעשה בע\"ת ממילא בלב נשבר מאד).\n<b>ובזה</b> יובן הטעם דצ\"ג שהם בבחי' אין ומ\"ה בענוה יתירה בעצם שזהו מצד שרשם במאור ואור העצמי' (דמי\"ש לאי\"ן דכלא ממש חשיב כו') לפ\"ע זה יהפכו הגסות דחושך לאור, והיינו מה שיהיו בע\"ת שזהו לעשות מיש אין שגדול יותר מתשובה לבדה שאין בה מכח האין בעצם שלפני החושך כו'. וזהו ענין שמחה שמן הענוה דמ\"ה דצ\"ג בשמחה ש\"מ",[["4576","880","<b>אברהם. . עפר ואפר</b>: וירא יח, כז."],["4577","881","<b>לפרע\"ה. . דכת\"ר דק\"נ</b>: ראה זהר בא לד, א ובהגהת הרח\"ו שם. לעיל פ' שמות לב, ד. וש\"נ."],["4578","882","<b>המדברים אל פרעה הוא מש\"ה. . אהרן תחלה</b>: ראה לעיל פ' וארא פב, ב. ואילך."]]],[2300550753,"אחר השפלות האמיתי (וז\"ש ויספו ענוים צ\"ג במ\"ה בעצם שיהיו בע\"ת בלב נשבר כנ\"ל) שיפה יותר מכל חיי העוה\"ב שבא מהתענוג ושמחה בעצם שלא ע\"י שפלות בביטול הגסות ויש לאין. וזהו שמשה דוקא זכה לתשובה שגדול כח אי\"ן העצמי שלו לעשות <span data-k=\"pg\">1018</span> ּ מי\"ש אי\"ן בתכלית שזהו למעלה יותר, וזהו ג\"כ מה שיעקב איש חל\"ק כו' באי\"ן העצמי ולבש בגדי עשו לעשות מיש אין כבע\"ת). וזהו מ\"ש כאן ויקחו אליך שמן זית בחי' חכמה<sup data-n=\"4579\">883</sup> כח מ\"ה<sup data-n=\"4580\">884</sup> ביטול במציאות בעצם כמו שהוא למעלה בבחי' אין האמיתי יומשך גם למטה מטה לעשות בחי' היש וגסות היותר קשה שיהי' רך ונשבר כמו בע\"ת, וזהו שנק' שמן זי\"ת ז\"ך דוקא שהוא מה שבכח מ\"ה דבחכ' אתברירו רפ\"ח<sup data-n=\"4581\">885</sup> כו' שיזדככו מטומאה לטהרה. ואין זה רק לפ\"ע צלילת השמן בהיותו ז\"ך ביותר והוא האי\"ן ומ\"ה בתכלית באופן שיהי' כתית שנסחט ביותר ע\"י דריכה בגת שהוא תכלית השפלות בלב נשבר ונדכא מאד לעשות מכל גסות וקושי רך ונשבר בתכלית הקצה שזהו הענין דהיפוך החשך לאור שבא ביתרון מן האור עצמו כנ\"ל במעלת בע\"ת, והיינו ע\"י ענין שמחה ש\"מ הנ\"ל שבאה מן הענו\"ה היתירה דוקא אחר שמכיר בעצמו שהוא שפל מכל האדם בבחי' עקב דרגל אז ישמח במצוה רק מצד אלקות שבמצוה לבד ולא שמח' עצמו שיש בשכלו ורצונו במצות, והיינו בלא טעם וכוונה כ\"א שאמר ועשה רצונו שזהו רק מצד המצו' בעצמה לבד כו' שעולה למעלה להיות בחי' פב\"פ לקבל מבחי' המאור עצמו כמ\"ש אל מול פני המנורה דוקא יאירו (והוא שבחי' מאור זה עצמו מחזירו למוטב להיות מיש אין כנ\"ל. וזהו שמן זית זך כתית למאור שע\"י שמן זית דחכ' שירד למטה מטה לברר לרע דעה\"ד לעשות מי\"ש וכל גסות אי\"ן בלב נשבר בחי' כתית זה יהי' עולה למאור עצמו שיאיר בנרות המנורה כו' באופן שיהי' בבחי' פב\"פ תמיד. וזהו להעלות נר תמיד פי' שעי\"ז דוקא שיקחו למשה בחי' מ\"ה בעצם שמן זית זך וכתית כנ\"ל למאור שגנוז ומלובש באור תורה זהו עיקר הכח ועוז להעלות נר תמיד להיות פב\"פ ע\"י אהרן כנ\"ל, והיינו בחי' מאור דעצמות אוא\"ס שמאיר בנשמות ישראל שנק' נרות או בנר דמצוה שלהם כנ\"ל שיהי' בהם יחוד דפב\"פ תמיד כי בחי' מאור זה מקור כל אור הפנימי' ועצמו' המאור לנשמות בג\"ע והעוה\"ב כנ\"ל וד\"ל. וזהו להעלות נר תמיד שזהו למעלה מבחי' פב\"פ כי זהו המקור והכח דפב\"פ בב' אופני', הא' שיאיר ה' פניו מפנימי' ועצמיו' דמאור באור דנשמות ישראל ונר מצוה ממול פני המנורה יאירו הנרות מלמעלה למטה תמיד. והב' זהו להעלות נר מלמטה למעלה שיעלו הנשמות מלמטה מבחי' אחוריי' להיות בבחי' פב\"פ כי מבחי' מאור זה הוא הכח ועוז ג\"כ להחזיר פב\"פ כענין מאור שבה מחזירו כו' והוא לפי שלמעלה הוא גם מפב\"פ כנ\"ל וד\"ל.",[["4579","883","<b>שמן זית בחי' חכמה</b>: ראה גם תו\"א תצוה פא, ע\"ג ואילך. מאמרי אדה\"ז על מארז\"ל ע' תצו. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקח."],["4580","884","<b>חכמה כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["4581","885","<b>רפ\"ח</b>: נסמן לעיל פ' יתרו ערב, ד."]]],[2300550756,"<b>ועם</b> כל הנ\"ל יובן מארז\"ל דתרי\"ג מצות ניתנו למשה ובא חבקוק והעמידן על אחת שהיא האמונה הפשוטה דצדיק באמונתו יחי' וזה פלא לכאו' כנ\"ל דהלא האמונה כמו טבע בנפשינו ירושה מאבו' כנ\"ל, אך הנה יובן ע\"פ הנ\"ל במ\"ש שמן למאור שזהו מ\"ש צדיק באמונתו יחי' שהעמיד כל התרי\"ג מצות ששרשן רק בבחי' אור המאיר באור דתורה שמקבל מן המאור כנ\"ל והאור הזה נחלק הוא לב' מיני אור אור לבן ואור שחור וחשוך כאור הנר שכלול מב' גוונין<sup data-n=\"4582\">886</sup> (שזהו רמ\"ח מ\"ע באור המאיר הלבן ושס\"ה ל\"ת באור השחור, דזהו שא' תרי\"ג מצות דוקא שכולל <span data-k=\"pg\">תקט</span> ּ שס\"ה ל\"ת ורמ\"ח מ\"ע יחד דוקא בהתכללו' דב' גווני אור הנ\"ל (כחוטי לבן ותכלת בציצית<sup data-n=\"4583\">887</sup> כמ\"ש במ\"א), והיינו אנכי ולא יהי' שכוללי' ה\"ח וה\"ג דמ\"ע ול\"ת<sup data-n=\"4584\">888</sup> שבדיבור הא' כו' שזהו שהעמידן על אח\"ת שהיא האמונה שהיא בכת\"ר שבכתר שכולל כא' כל תרי\"ג מצות דחו\"ג דמ\"ע ול\"ת זהו כאור הנר שעולה ויורד תמיד בבחי' רו\"ש יחד והוא האוי\"ר שנק' רו\"ש דאהבה שרש מ\"ע ויראה שרש ל\"ת כידוע ובחי' רו\"ש זה נכללו כא' ממש.\n<b>וזהו</b> להעלות נר תמיד דלכאו' אינו מובן מ\"ש תמיד דוקא כמו עולת תמיד העשוי' בה\"ס<sup data-n=\"4585\">889</sup> מכבר כו', ומ\"ש להעלות נר בלשון העלאה דוקא בבחי' רו\"ש דוקא בעלי' וירידה יחד כאור הנר כנ\"ל, ולכאורה אין זה שייך כלל למשה שנק' שוש' דמלכא רק לאהרן כה\"ג שהוא המעלה לנר הוי' דנשמות ישראל לפי שנק' שוש' דמט' כמ\"ש בהעלותך כו' כנ\"ל. אך הנה ידוע שהאהבה ודביקות בהתלהבות דרשפי אש הצמאון שבלב זהו כאור הנר שסמוך לפתילה השורף ומכלה כו' והוא בחי' הרגשה בלב, וכל עיקר יגיעה במוח ולב הוא רק כדי להתפעל בלב בהתלהבות אלקי' במורגש דוקא שאז יטיב לנפשו ויתענג ביותר בכח המדמה שכוונתו בהרגשה זו מצד קרבת אלקי' שחפץ בה. אך אור המאיר הוא בחי' הביטול ועלי' של אהבה זו בכליון למעלה ליכלל במאור שהוא מהו\"ע ית' כמו נר מצוה נכלל בשלהבת כמו צמאה לך נפשי כלתה נפשי וחוזר ויורד, וזהו והחיות רו\"ש תמיד. כך ענין העלא' נר ה' נשמת אדם ע\"י אהרן כה\"ג שא' בהעלותך את הנרות דנש\"י ברשפי אש התלהבות ודביקות ע\"י בחי' אש שלמעלה שנק' שלהבת י\"ה<sup data-n=\"4586\">890</sup> ממש שיתעוררו באהבה רבה ע\"י כה\"ג שממשיך ומעורר את האהבה<sup data-n=\"4587\">891</sup> בלב כנ\"י כענין משכני כו' כמ\"ש במ\"א אל מול פני המנורה<sup data-n=\"4588\">892</sup> כו' דוקא יאירו הנרות שזהו שמצוה לאהרן שושבינא דמט' שיעלה לנשמות ישראל בבחי' ביטול והתכללו' בהתלהבות שלהם אל",[["4582","886","<b>כאור הנר שכלול מב' גוונין</b>: ראה גם שע\"ת סב, ד."],["4583","887","<b>כחוטי לבן ותכלת בציצית</b>: ראה אמ\"ב שער הציצית פד, ג ואילך."],["4584","888","<b>ה\"ח וה\"ג דמ\"ע ול\"ת</b>: ראה קו\"א לתניא להבין מ\"ש בפע\"ח קנח, ב."],["4585","889","<b>עולת תמיד העשוי' בה\"ס</b>: פינחס כח, ו. ראה חגיגה ו, א. ב."],["4586","890","<b>שלהבת י\"ה</b>: שה\"ש ח, ו."],["4587","891","<b>כה\"ג שממשיך. . האהבה</b>: ראה לעיל פ' יתרו רסט, ב. וש\"נ."],["4588","892","<b>אל מול פני המנורה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380433\" data-slug=\"likkutei-torah\" data-id=\"4001380433\">לקו\"ת בהעלותך ל, ד</a>. מאמרי אדה\"א במדבר ח\"ג ע' תתקסג."]]],[2300550759,"מול פני כו' לעצמות א\"ס ב\"ה ולא יחפוץ בהתלהבות זו רק להרגיש עצמו בזה כנ\"ל. אך מהיכן יהי' כח באהרן כה\"ר להעלות הנרות אל מול פני כו' אע\"פ שידליקם באש דשלהבת י\"ה מ\"מ יוכל להיות שלא יעלו הנרות ליכלל אל מול כו' רק להרגיש א\"ע בקרבת אלקי' שיהנה מזה כו', ולז\"א בפ' זו ויקחו אליך למשה בחי' מ\"ה ואין בעצם שבבחי' מאור עצמו שממנו יוכל להיות כח בעצם בכל בחי' העלאת הנר דנש\"י תמיד ליכלל במאור בכל פעם שידליק אותם אהרן כו'. והוא מ\"ש דכל התרי\"ג מצות ברו\"ש באוי\"ר הכוללם יחד שנק' נר הוי' ונר מצות הוי' העמידן על אחת כו' והוא ענין שמחה ש\"מ באמונה פשוטה ועצמי' בעצמות הרצון שלמעלה מן הטעם במוח שאינו בא בבחי' הרגשה לעצמו כלל בהתלהבות העולה באהבה ודביקות רק זהו כמו עד\"מ המאמין באמונה שלימה ואמיתי' באו\"נ<sup data-n=\"4589\">893</sup> הנאמן לו ביותר שיביא לו המזון ומחי' וכל טוב מרחוק אע\"פ שעדיין לא הביא לו ואין לו מאכל להחיות נפשו מצד תוקף אמונה זו יחי' בה בבטחון חזק כאלו יש לו פת בסלו ממש כו', והרי מה שיחי' מאמונה זו <span data-k=\"pg\">1020</span> ּ מרחוק היא ויחי' בה ממש כנ\"ל. וכך הוא בצדיק שעושה המצו' באמונתו הפשוטה ועצמי' שיאמין בשם הוי' המלובש במצוה זו שיתגלה מעצמות התענוג ורצה\"ע הפשוט בעוה\"ב בשכר המצו', ותוקף האמונה זו אף שהיא מרחוק ה' נראה כמ\"ש דוד אביטה אורחותיך<sup data-n=\"4590\">894</sup> מ\"מ יחי' באמונה זו כאלו יש לו מזון ומחי' דעוה\"ב בחיי עולם אע\"פ שאינו מרגיש חיות אלקי כלל במעשה מצוה זאת כמו שמרגיש חיות אלקות בהתלהבות בתפלה מ\"מ למעלה היא יותר מכל אור והתלהבות דדביקות בתפלה. והיינו שהעמיד כל בחי' רו\"ש דתרי\"ג מצות על אמונה פשוטה שיאמין ויחיה בה מרחוק בלי הרגשה בנפשו כלל מבלי שיחפוץ להרגיש קרבת אלקי' שיש בזה רק שיאמין אמונה חזקה ויבטח בטחון חזק בה' אחד וידע ויתאמת במוחו ולבו כי קרוב אליו ממש האור בבחי' המאור דעצמו' א\"ס שבעוה\"ב בעשות מצות ה' וכמ\"ש מצות ה' ברה גם עתה מאירת עינים<sup data-n=\"4591\">895</sup> לעוה\"ב לפי שבבחי' סובב הכללי אין לבוש דמצוה מסתיר כלל. וזהו צדיק דוקא שעושה המצו' שהוא בדומה לבחי' צ\"ע בחי' סובב כו' באמונתו יחי' בלי הרגשה כלל רק בשפלות וענוה כנ\"ל שזה יותר טוב ויפה מכל חיי העוה\"ב שבא העונג הנעלם במורגש והן תרי\"ג מצות שבעוה\"ז בשמחה מתוך הענווה ושפלות דוקא כנ\"ל, וז\"ש להעלות נר תמיד אפי' מה שיאיר בעוה\"ב והוא מבחי' עולת תמיד שבהר סיני ע\"י משה דוקא וד\"ל.",[["4589","893","<b>באו\"נ</b>: באוהב נאמן. ראה גם לעיל פ' בא צ, ב הערה 176."],["4590","894","<b>אביטה אורחותיך</b>: תהלים קיט, טו [ושם: ואביטה — ראה שע\"ת לב, ב הערה 8]."],["4591","895","<b>מצות ה' ברה. . מאירת עינים</b>: תהלים יט, ט."]]],[2300550058,"<b>בעזר\"ה פ' תצוה שנת תקפ\"ו פה ליובאוויטש</b>\n<span data-k=\"pg\">תקי</span> ּ<b>ולקחת</b> את שתי אבני שוהם<sup data-n=\"4592\">1</sup> ופתחת עליהם שמות בנ\"י<sup data-n=\"4593\">2</sup> ששה משמותם על האבן האחת ואת שמות הששה הנותרים על האבן השנית<sup data-n=\"4594\">3</sup> כו'. [ו]י\"ל בתחילה טעם ההפרש בין כתפות האפוד לחושן, שבכתפות האפוד הי' רק ב' אבנים וששה משמותם כו' ובחושן היו י\"ב אבנים לי\"ב שבטים כו' אבן מיוחד לכל שבט ושבט בפ\"ע. וגם מה שב' האבנים דאפוד הי' דוקא משל שוהם (שהוא אבן טוב שמתחילת הווייתו הוא<sup data-n=\"4595\">4</sup> זך [ובהיר<sup data-n=\"4596\">5</sup> ] בעצם תולדתו כאור הבהיר בעצם), וי\"ב האבנים דחושן הי' כ\"א מובדל במינו ובמראהו כמו אודם פטדה וברקת<sup data-n=\"4597\">7</sup> הטור האחד שאין האחד דומה לחבירו כמו שאין שבט א' דומה לחבירו במדריג', לפי שכל א' יש לו מדריגה מיוחדת בי\"ב גבולי<sup data-n=\"4598\">8</sup> אלכסון<sup data-n=\"4599\">6</sup> שהן י\"ב צירופי' דשם הוי'<sup data-n=\"4600\">9</sup> כידוע (וכך גם עכשיו יש י\"ב שערים שכל שבט עולה תפלתו בשער המיוחד אליו<sup data-n=\"4601\">10</sup> כו'). והאבנים האלה הן מזוככים ע\"י מלאכת אדם שמזככים אותם או שמתבררים בגידולם בארץ או בים כאבן ספי\"ר<sup data-n=\"4602\">11</sup> וכן אוד\"ם פטד\"ה וברק\"ת שמתנוצ[צי'] בעין גוונים משונים שבו ולא שהן מזוככים ובהירים מתחלת הווייתן [ב]תולדתם (כמ\"ש במ\"א שיש הפרש זה גם בכוכבים שיש מאירים בעצם ויש [ש]מתנוצצים בעין אנה ואנה וכמ\"ש בזהר ע\"פ השמים מספרים מנהרין ומנצצין<sup data-n=\"4603\">12</sup> כו'). והוא ההפרש בין [צ\"ע לצ\"ת שהן ב' אבנים דשוה\"ם וישפ\"ה<sup data-n=\"4604\">13</sup> יוסף<sup data-n=\"4605\">15</sup> ובנימין<sup data-n=\"4606\">14</sup> וכמ\"ש בגמ' מאי כדכ\"ד ח\"א שהם<sup data-n=\"4607\">16</sup> כו' (וזהו ההפרש בין אותי' ד]תושב\"כ ובין תושבע\"פ, והוא ההפרש בין מ\"ד ומ\"ן שזהו ההפרש בין או\"י לאו\"ח<sup data-n=\"4608\">*17</sup> כידוע. והיינו הטעם שהיו אבני שוה\"ם דוקא בכתפות האפוד שהוא בחי' דכר משפיע בבחי' או\"י מלמעלה למטה דנוק'<sup data-n=\"4609\">*18</sup> צ\"ע ושה\"ם אותיות מש\"ה<sup data-n=\"4610\">18</sup> שזהו בחי' יסוד אבא<sup data-n=\"4611\">19</sup> כו', וי\"ב [ה]אבנים שבחושן הוא בבחי' נוק'<sup data-n=\"4612\">17</sup> בבחי' העלא' דאו\"ח מלמטה למעלה וע\"כ הי' על לבו של כה\"ג",[["4592","1","<b>ולקחת את שתי אבני שוהם</b>: מיוסד על ד\"ה ששה משמותם תקע\"ב נדפס באוה\"ת תצוה כרך ה' ע' א'תרנג ועם הגהות וכו' ע' א'תרנו. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["4593","2","<b>ולקחת. . שמות בנ\"י</b>: תצוה כח, ט."],["4594","3","<b>ששה משמותם. . האבן השנית</b>: תצוה שם, י."],["4595","4","<b>שוהם. . שמתחילת הווייתו הוא זך</b>: ראה גם לעיל פ' שמות ז, א. וש\"נ."],["4596","5","<b>ובהיר</b>: יא: וברור."],["4597","7","<b>אודם פטדה וברקת</b>: תצוה כח, יז."],["4598","8","<b>בי\"ב גבולי אלכסון</b>: ס\"י פ\"ה, מ\"א. ראה הנסמן לעיל פ' בא קכז, ד."],["4599","6","<b>וי\"ב. . שבט. . בי\"ב גבולי אלכסון</b>: נסמן לעיל פ' משפטים רצ, ב."],["4600","9","<b>בי\"ב גבולי אלכסון. . דשם הוי'</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' ח. וש\"נ."],["4601","10","<b>י\"ב שערים שכל שבט. . בשער המיוחד אליו</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"ח, ס\"ב. לקמן שנא, א. שה\"א פח, א ובהנסמן במראי מקומות לשם."],["4602","11","<b>מזוככים ע\"י מלאכת אדם. . כאבן ספי\"ר</b>: ראה גם לעיל פ' בשלח רלו, ג ובהנסמן לשם."],["4603","12","<b>השמים מספרים מנהרין ומנצצין</b>: תהלים יט, ב. ראה גם לעיל פ' משפטים שב, ב. וש\"נ."],["4604","13","<b>צ\"ע לצ\"ת. . דשוה\"ם וישפ\"ה</b>: ראה גם לעיל פ' שמות ז, א. וש\"נ."],["4605","15","<b>דשוה\"ם וישפ\"ה יוסף ובנימין</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380819\" data-slug=\"likkutei-torah\" data-id=\"4001380819\">לקו\"ת ראה כה, ד</a> מציין: בהרמב\"ם פ\"ט מהל' כלי המקדש וברבות ס\"פ תצוה ופ' במדבר פרשה ב [ז]."],["4606","14","<b>צ\"ע לצ\"ת. . יוסף ובנימין</b>: ראה זהר ויצא קנג, ב. לעיל פ' שמות כא, ג. וש\"נ."],["4607","16","<b>מאי כדכ\"ד ח\"א שהם</b>: ראה ב\"ב עה, א."],["4608","*17","<b>יוסף ובנימין. . או\"י לאו\"ח</b>: ראה פרדס (שער ממטה למעלה) שט\"ו, ספ\"ד. ע\"ח (שער מ\"ן ומ\"ד) של\"ט, סוף דרוש טו."],["4609","*18","<b>דנוק'</b>: ביא: שנק'."],["4610","18","<b>ושה\"ם אותיות מש\"ה</b>: ראה יאיר נתיב למאו\"א מערכת אבן ס\"ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550670\" data-slug=\"torat-chaim\" data-id=\"2300550670\">תו\"ח ח\"ש קלד, ב</a> ובהערה 13. לקמן שנד, ד. שנה, ד."],["4611","19","<b>משה. . יסוד אבא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."],["4612","17","<b>האפוד שהוא בחי' דכר. . שבחושן. . נוק'</b>: ראה גם לקמן שנד, ב. ד. מאמרי אדה\"א דברים ח\"ב ע' תמא. וש\"נ. סה\"מ תרס\"ח ע' קיח."]]],[2300550090,"דוקא (כמשי\"ת). וע\"כ הי' בבחי' הזדככות דאו\"ח שנק' נ[י]צ[ו]ץ וכמ\"ש ולא יזח החשן מעל האפוד<sup data-n=\"4613\">20</sup> לפי שצ\"ל היחוד וחיבור דחושן שבלב בחי' המל' תמיד דבוק במשפיע שהן אבני שהם דאפוד (וכמ\"ש במ\"א שזהו ענין טהרה מביאה לידי קדושה<sup data-n=\"4614\">21</sup> דבחי' העלאת מ\"ן דתשו' נק' טהרה שמטהר ומזכך [עצמו] מן העכרורי' כמו אבן ספי\"ר שנעשה ספי\"ר כנ\"ל, שזהו בחי' או\"ח ועי\"ז נמשך המשכת מ\"ד שהוא בחי' או\"י דקדושה דהיינו מעצם האור העליון דמשפיע שבתו\"מ (באותיות דתושב\"כ שהן אותיות עצמי' משא\"כ תושבע\"פ שע\"ז נא' ותהי להם הלבינה לאבן<sup data-n=\"4615\">22</sup> כו'. וזהו ותחת רגליו כו'<sup data-n=\"4616\">23</sup> ותחת רגליו דוקא כמעשה לבנ\"ת הספי\"ר<sup data-n=\"4617\">24</sup> (כמו אבנ\"י החש\"ן) בבחי' או\"ח דמל' וכעצם השמים לטוהר הוא בבחי' או\"י דמשפיע שנק' טהירו עילאה כמו לפני הוי' תטהר\"ו<sup data-n=\"4618\">25</sup> כמ\"ש במ\"א). אך הנה כללות הענין לפי שי\"ב אבנים דחשן הי' רק כדי להעלות לזכרון לכל נש\"י שיעלו למעלה (מבריאה לאצי' כמ\"ש ששם עלו שבטים<sup data-n=\"4619\">26</sup> שבטי י\"ה כו'), וע\"כ היו השמות די\"ב שבטים בחקיקה על האבנים כו' דכל שבט הי' לו שם<sup data-n=\"4620\">27</sup> מיוחד באבן שלו והיו נתונים על לבו י\"ב מיני אבנים אלה כאו\"א מיוחד במינו ובמראהו כפי אותו השרש של השבט למעלה במדות דז\"א דאצי', ואהרן כה\"ג הי' מעלה לכללות נש\"י החקוקי' בי\"ב אבני החושן שעל לבו בי\"ב שמות שלהם (כמו לך אמר לבי<sup data-n=\"4621\">28</sup> שהן כללות נש\"י שחקוקי' בלב העליון דבחי' המל' וכמים הפא\"פ<sup data-n=\"4622\">29</sup> כו' <span data-k=\"pg\">1022</span> ּ את פניך הוי'<sup data-n=\"4623\">30</sup> כו'), לפי שאהרן כה\"ג נק' שוש' דמטרוניתא<sup data-n=\"4624\">31</sup> כמו משל השוש[בין] דכלה שיש בכחו להעלות ולקרב את הכלה לגבי החתן וכידוע [ד]כנ\"י נק' כלה והקב\"ה נק' חתן כמ\"ש בשה\"ש<sup data-n=\"4625\">32</sup> כו'. והנה עדיין יש להבין למה הי' שמות השבטים חקוקים באבנים דוקא הלא האבן הוא בחי' דומם ואיך יתכן לומר ששמות השבטים החקוקים באבן גשמי יעלה אותם למעלה באצי' [ממש] כמ\"ש ונשא אהרן את שמות בנ\"י בחשן המשפט על לבו [כו'] לזכרון לפני ה' תמיד<sup data-n=\"4626\">33</sup> כו')<sup data-n=\"4627\">34</sup>.",[["4613","20","<b>ולא יזח החשן מעל האפוד</b>: תצוה כח, כח. ראה מאמרי אדה\"ז תקס\"ו ע' קצז ואילך."],["4614","21","<b>טהרה מביאה לידי קדושה</b>: ראה ירושלמי שבת פ\"א, ה\"ג. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ק. ראה גם לעיל פ' שמות ז, א. מאמרי אדה\"א שמות ח\"ב ע' תרכח. דברים ח\"א ע' עד."],["4615","22","<b>ותהי להם הלבינה לאבן</b>: נח יא, ג. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' סז ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370344\" data-slug=\"torah-or\" data-id=\"3901370344\">תו\"א משפטים עז, ג</a> ואילך."],["4616","23","<b>ותחת רגליו כו'</b>: ביא: ליתא."],["4617","24","<b>ותחת רגליו. . כמעשה לבנ\"ת הספי\"ר</b>: משפטים כד, י."],["4618","25","<b>לפני הוי' תטהר\"ו</b>: אחרי טז, ל. ראה גם לעיל פ' בא קכג, ג. וש\"נ."],["4619","26","<b>ששם עלו שבטים</b>: תהלים קכב, ד."],["4620","27","<b>כו'. . הי' לו שם</b>: ביא: כל שם דכל שבט."],["4621","28","<b>לך אמר לבי</b>: תהלים כז, ח."],["4622","29","<b>וכמים הפא\"פ </b>[ב: הפנים לפנים]: משלי כז, יט."],["4623","30","<b>את פניך הוי'</b>: המשך הכתוב לך אמר לבי."],["4624","31","<b>שאהרן. . שוש' דמטרוניתא</b>: נסמן לעיל פ' יתרו רסט, ד."],["4625","32","<b>[ד]כנ\"י נק' כלה. . חתן כמ\"ש בשה\"ש</b>: ראה גם לעיל פ' וארא עב, ג. וש\"נ."],["4626","33","<b>ונשא אהרן. . תמיד</b>: תצוה כח, כט."],["4627","34","<b>כו')</b>: ביא: כו'."]]],[2300550122,"(ב) <b>אך</b> הנה יובן כ\"ז הענין באבני האפוד ואבני החושן מענין הדלקת הנרות של המנורה (שהי' בזה ג\"כ ב' מדרגות דדכר ונוק' כנ\"ל באבני האפוד ואבני החושן רק שהוא מדבר באור הנשמות כמו שהן בלא כלים בגופים עדיין, ו[ב]ענין אבני[ם] דחושן ואפוד הוא מדבר בנשמות שבגופים למטה ובאים לידי בירור והזדככות ע\"י תשו' ומע\"ט שיוכלו גם הם לעלות לזכרון לפני ה', אבל זה דוקא ע\"י הדלקת והעלאות [נרות] דנש\"י עצמם תחלה), והוא מ\"ש כאן בריש הפ' ואתה תצוה את בנ\"י<sup data-n=\"4628\">35</sup> ויקחו אליך שמן זית זך כתית למאור להעלות נר תמיד (כמשי\"ת) וע\"כ הקדים זה למצות חשן ואפוד לפי שבחי' שמן המאור להאיר האור דנרות דנש\"י צ\"ל תחלה במקורם הראשון ע\"י משה ואהרן כמ\"ש ויקחו אליך דוקא כו' (כמשי\"ת). וביאור הענין ידוע ומבואר במ\"א בפ' בהעלותך את הנרות<sup data-n=\"4629\">36</sup> דאהרן כה\"ג הוא המעלה [את] נש\"י למעלה כמ\"ש ובהעלות אהרן את הנרות<sup data-n=\"4630\">37</sup> שזהו ענין נצחי ותמידי [שמעלה] לנש\"י תמיד בכל דור ודור<sup data-n=\"4631\">38</sup> ובכל זמן להיות ידוע דאהרן כה\"ג הוא מז' הרועים<sup data-n=\"4632\">39</sup> שהוא כמו הרועה שזן ומפרנס שנק' משפיע ולכאורה העלאה זו שמעלה לנש\"י הוא בבחי' או\"ח דמקבל אל המשפיע. אך הענין הוא דשניהם אמת להיות ידוע דכל הנשמות ירדו מלמעלה מאוצר הנשמות<sup data-n=\"4633\">40</sup> שנמשכו מאור הזרוע לצ\"ע<sup data-n=\"4634\">41</sup> למטה בגופים, והגם שאור האלקי שבנשמה נק' נר הוי'<sup data-n=\"4635\">42</sup> וכמו ניצוץ קטן שנמשך ונבדל משלהבת ואבוקה גדולה. אבל הניצוץ הזה ה\"ז בא בבחי' ירידה והשתלשלו' עד למטה ביותר בהתלבשו' בחומר הגס הגופני [ה]מחשיך אורה ביותר ע\"י תאות חומריות דנה\"ב שגובר כח המתאווה דרוח הבהמה עד שיורד ומשפיל גם לרוח האדם שהוא הניצוץ דנשמה שיומשך אחר גופו במח' טמאות שנק' לבושים צואים<sup data-n=\"4636\">43</sup> לבושי' דמסאבותא<sup data-n=\"4637\">44</sup> וכ\"ש במעשה כו', עד שקרוב שיכבה אור הנשמה לגמרי כמשל אור קטן הדולק במקום אויר מעופש וגס ביותר כבור עמוק או במקום אויר חום, וכ\"ז [רק] מצד ריחוק אור הנשמה ממקור חוצבה למעלה באלקי' חיים שנתרחקה בריחוק עצום כ\"כ<sup data-n=\"4638\">45</sup> כו'. אך הנה נר האלקי דנשמה טרם יכבה ע\"י חשכת גסות חומריות הגוף מיד נתעורר [מ]מקור כל הנשמות שנק' מקור כל החיים העליוני' כו' רוח התעוררות האה\"ר דמשפיע אל המקבל לעורר את האהבה והתשוקה בכל ניצוצות דקדושה גם הנופלים בשאול תחתית שיתעוררו בתשו' שלימה מקירו[ת] הלב (כראב\"ד שיצאה נשמתו בבכי'<sup data-n=\"4639\">46</sup> וכה\"ג),",[["4628","35","<b>ואתה תצוה את בנ\"י</b>: תצוה כז, כ."],["4629","36","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב. ראה מאמרי אדה\"א במדבר ח\"ג ע' תתפא ואילך. וש\"נ. לעיל פ' וארא עז, ב."],["4630","37","<b>ובהעלות אהרן את הנרות</b>: תצוה ל, ח. ראה גם לעיל פ' תרומה שז, ד."],["4631","38","<b>ודור</b>: ביא: ליתא."],["4632","39","<b>דאהרן. . מז' הרועים</b>: ראה תיקונים לז\"ח קד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201655\" data-slug=\"likkutei-sichot\" data-id=\"1300201655\">לקו\"ש חנוכה (כרך כ) ע' 643</a>. לקמן שנו, א. וש\"נ."],["4633","40","<b>מאוצר הנשמות</b>: ראה גם לעיל שלג, ד. וש\"נ."],["4634","41","<b>הנשמות שנמשכו מאור הזרוע לצ\"ע</b>: ראה גם לעיל פ' בשלח רמ, ג."],["4635","42","<b>שבנשמה נק' נר הוי'</b>: נסמן לקמן בהערה 72."],["4636","43","<b>לבושים צואים</b>: ראה זכרי' ג, ג. ד. זהר פינחס ריד, א."],["4637","44","<b>לבושי' דמסאבותא</b>: <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ\"ו</a>."],["4638","45","<b>כ\"כ</b>: ביא: ליתא."],["4639","46","<b>כראב\"ד שיצאה נשמתו בבכי' </b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."]]],[2300550154,"וזהו כמו שנמשך אור מן השלהבת הגדולה לניצוץ קטן שעומד מרחוק להמשיכו אל השלהבת (וכמו כאשר יעמידו נר קטן תחת נר העליון <span data-k=\"pg\">תקיא</span> ּ שיודלק מן העליון גם באמצעות העשן העולה מן הנר התחתון שכבה<sup data-n=\"4640\">47</sup> שיוכלל באש העליון. כך גם בנר האלקי שכבה כמ\"ש ונר רשעים ידעך<sup data-n=\"4641\">48</sup> כשעושה תשובה אמיתי' יעלה למעלה לעורר ולהמשיך אור חדש על נשמתו להאירה כמו נתן דצוציתא<sup data-n=\"4642\">49</sup> כו'). וזהו שלום<sup data-n=\"4643\">50</sup> שלום לרחוק ולקרוב<sup data-n=\"4644\">51</sup> כשרחוק נעשה קרוב<sup data-n=\"4645\">52</sup> והוא אור הנשמה שבגוף שנתרחקה מאד מאור פני מלך חיים<sup data-n=\"4646\">53</sup> וע\"י שוש' דמטרוניתא אהרן כה\"ר שמעלה את נש\"י גם הרחוקים. והוא מה שאנו רואים שיפול הרהורי תשו' פתאום גם בלב רשע ויהי' לבו נשבר באמת עד שמואס בחייו כו' והוא שעולה למעלה ליכלל במקור חוצבו כמו ניצוץ שרץ במרוצה גדולה ליכלל בשלהבת הגדולה המושכו כו' כנ\"ל, וכך הוא במה שאנו רואים התעוררות האהבה והתשוקה [הנפלאה] שנעשה פתאום בלב כאו\"א לפרקים ליכלל ולידבק באלקים חיים בבחי' ביטול והתכללות ממש בעצמות א\"ס ב\"ה, כמו נכספה וגם כלתה נפשי<sup data-n=\"4647\">54</sup> כו', וכן אליך ה' נפשי אשא<sup data-n=\"4648\">55</sup> כניצוץ העולה מאלי' ונכללת באבוקה וכמא' צדיקי' בפני השכינה<sup data-n=\"4649\">56</sup> כנר בפני האבוקה. וזהו שנעשה ע\"י המשכת האה\"ר דאהרן כה\"ג שמעלה ומדליק את הנרות דנש\"י מלמעלה למטה שהוא כח העליון המעורר את הנרות דנש\"י<sup data-n=\"4650\">57</sup> במקבלים כו' וכענין משכני אחריך נרוצה<sup data-n=\"4651\">58</sup> ממילא כמ\"ש במ\"א (ונק' כח המעלה מ\"ן בכנ\"י<sup data-n=\"4652\">59</sup> כמ\"ש במ\"א). וזהו בהעלותך את הנרות דנש\"י לעורר בם את האהבה עד שיוכל[ו] לעלות ולקבל מאור פני הוי' ממש שנק' מאו\"ר (והוא מקור הראשון דנש\"י שהוא פנימי' בבחי' אור אבא כמ\"ש כי אתה אבינו<sup data-n=\"4653\">60</sup> כו' כמ\"ש במ\"א), אל מול פני המנורה [דוקא] יאירו כו' שהוא עצמות אוא\"ס שנק' מאור שמשם שרש ומקור הראשון לנש\"י (מלמטלמ\"ע<sup data-n=\"4654\">61</sup> ) כו' וד\"ל. ובזה יתורץ ענין הנ\"ל דגם שעבודה זו דאהרן כה\"ג הי' בבחי' העלאה להעלות לנש\"י מלמטה למעלה בבחי' או\"ח דוקא וע\"כ נק' שוש' דמטרוניתא כנ\"ל שבכחו לקרב הכלה לגבי החתן, עכ\"ז הרי כח הזה עצמו מה שיוכלו נש\"י להתעורר באה\"ר ותשובה<sup data-n=\"4655\">62</sup> ה\"ז בא דוקא מכחו של אה\"ר העליונה דאהרן כה\"ג שהוא בחי' רב חסד העליון שיומשך לב כאו\"א מישראל, כענין משכנ\"י אחריך באהבתך אז אחריך נרוצה כניצוץ בשלהבת כנ\"ל וכמו [אב] המושך בדברי אהבה ללב בנו שיתעורר אליו באה\"ר כו', והוא מפני שאהרן",[["4640","47","<b>העשן. . הנר התחתון שכבה</b>: ראה גם לעיל רלט, סע\"ג ואילך. וש\"נ."],["4641","48","<b>ונר רשעים ידעך</b>: משלי יג, ט."],["4642","49","<b>נתן דצוציתא</b>: נסמן לעיל פ' יתרו רסו, ג."],["4643","50","<b>וזהו שלום</b>: ביא: וז\"ש."],["4644","51","<b>שלום שלום לרחוק ולקרוב</b>: ישעי' נז, יט."],["4645","52","<b>כשרחוק נעשה קרוב</b>: ראה ברכות לד, ב."],["4646","53","<b>מאור פני מלך חיים</b>: משלי טז, טו."],["4647","54","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["4648","55","<b>אליך ה' נפשי אשא</b>: תהלים כה, א."],["4649","56","<b>צדיקי' בפני השכינה</b>: ראה פסחים ח, א. מאמרי אדה\"א דברים ח\"ג ע' תשסח. שה\"א מה, א ובהערה 5."],["4650","57","<b>הנרות דנש\"י</b>: ביא: האהב'."],["4651","58","<b>משכני אחריך נרוצה</b>: שה\"ש א, ב. ראה גם לעיל פ' וארא עח, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשצה. תקס\"ז ע' קפח. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381322\" data-slug=\"likkutei-torah\" data-id=\"4001381322\">לקו\"ת שה\"ש מח, ג</a>. סידור שער הר\"ח ריא, ג. מאמרי אדה\"א במדבר ח\"ב ע' תרסח."],["4652","59","<b>כח המעלה מ\"ן בכנ\"י</b>: ראה גם לקמן פ' ויקהל תכג, א בשם הע\"ח. פקודי תמח, א. מאמרי אדה\"א ויקרא ח\"ב ע' תקעג. במדבר ח\"ב ע' תסו."],["4653","60","<b>כי אתה אבינו</b>: ישעי' סג, טז. ראה גם מאמרי אדה\"א בראשית ע' כו. וש\"נ. ויקרא ח\"א ע' שפח. לעיל פ' בא קי, ג. בשלח רמא, א. רמז, ג. משפטים רצו, ג."],["4654","61","<b>(מלמטלמ\"ע)</b>: ביא: ליתא."],["4655","62","<b>באה\"ר ותשובה</b>: ב: באהב' ותשו'. יא: באה\"ר ותשוקה."]]],[2300550186,"כה\"ג הוא מז' הרועים שמשפיעים כח האהבה והתשוקה בכנ\"י ע\"כ הוא המדליק את הנרות דנש\"י כנ\"ל וד\"ל.\n<b>והנה</b> בחי' העלאה והדלקת הנרות דנש\"י בהדלקת נרות המנורה (שהן ז' נרות נגד ז' מדות<sup data-n=\"4656\">63</sup> דמל' שכאו\"א כלולה מז'<sup data-n=\"4657\">64</sup> ספי' שהן ע' נפש דיעקב<sup data-n=\"4658\">65</sup> ומסתעפים לס\"ר<sup data-n=\"4659\">66</sup> כידוע) הי' [ב' פעמים] בוקר וערב כמ\"ש [ו]בהעלות אהרן את הנרות בין הערביים והן הטבת ה' נרות<sup data-n=\"4660\">67</sup> כו' וכמ\"ש כאן מערב עד בוקר<sup data-n=\"4661\">68</sup> כו', וזהו כמו מצות ק\"ש שקורין ב' פעמים בוקר וערב<sup data-n=\"4662\">69</sup> דוקא כ[י] עבודה זאת דהדלקת נרות דנש\"י ממקורם הראשון היינו ממש ענין מצות ק\"ש שהוא למס\"נ באחדות פשוט כידוע, והוא מ\"ש שמע ישראל דוקא שהוא<sup data-n=\"4663\">70</sup> נפה\"א<sup data-n=\"4664\">71</sup> שנק' נר הוי' <span data-k=\"pg\">1024</span> ּ נשמת אדם<sup data-n=\"4665\">72</sup> שתעלה למעלה במס\"נ ליכלל ולידבק בה' אחד כ[מ]ו הניצוץ הנכלל בשלהבת כנ\"ל (וזהו כדכד ב' פעמים כ\"ד כד<sup data-n=\"4666\">73</sup> שהן ך\"ד אותיות של פסוק דשמע ישראל<sup data-n=\"4667\">74</sup> שצ\"ל בוקר וערב שיש בזה ב' מדרגות דאו\"י ואו\"ח כמ\"ש מאי כדכ\"ד חד אמר שהם וחד אמר ישפה צ\"ע וצ\"ת, ובערב שהוא בחי' [מדת] לילה בחי' ההסתר יאיר אור מן החשך דגוף בבחי' או\"ח בהבהק\"ה יותר (כענין אבני החושן כנ\"ל) וכמו בזמן הגלות שנא' לא יכבה בלילה נר\"ה<sup data-n=\"4668\">75</sup> וכתי' רשפי' [רשפי]<sup data-n=\"4669\">76</sup> כו', ובבוקר שהוא<sup data-n=\"4670\">77</sup> מדת יום הוא ק\"ש דשחרית שהוא באור [ד]צ\"ע נק' ישראל לי רא\"ש<sup data-n=\"4671\">78</sup> כו' שהוא בבחי' או\"י והוא בחי' קדושה שבא[ה] ע\"י טהרה כנ\"ל ואמר להוי כדי\"ן וכדי\"ן<sup data-n=\"4672\">79</sup> כו' כמ\"ש במ\"א).\n(ג) <b>והנה</b> מעתה יש להבין מ\"ש כאן בריש פ' זו ואתה תצוה כו' ויקחו אליך כו' ואם [זהו] בשביל מצות הדלקת נרות המנורה כמו שמסיים להעלות נר תמיד הלא דבר זה ציוה לאהרן כה\"ג דוקא שיעלה וידליק לנרות המנורה, מפני שזה שייך לאהרן דוקא (שהוא [בחי'] רב חסד דא\"א כנ\"ל) ונק' שוש' דמטרוניתא כו' כמ\"ש בהעלותך את הנרות<sup data-n=\"4673\">80</sup> ובהעלות אהרן כו', וגם כאן א[מר] מחוץ לפרוכת יערוך אותו אהרן ובניו<sup data-n=\"4674\">81</sup> כו' ואין זה שייך למשה רק לאהרן ולמה א' ויקחו אליך דוקא. אך הענין ידוע דמשה נק' שוש[בין] דמלכא<sup data-n=\"4675\">82</sup> שהוא כמו השוש[בין] שבכחו לקרב ולהמשיך את החתן שיבא להתחבר ולהתייחד בכלה [כו'],",[["4656","63","<b>ז' נרות נגד ז' מדות</b>: ראה מאמרי אדה\"א במדבר ח\"ג ע' תתקעב. הנסמן לעיל שלו, ג."],["4657","64","<b>מז'</b>: ביא: מי'."],["4658","65","<b>ע' נפש דיעקב</b>: ויגש מו, כז."],["4659","66","<b>ומסתעפים לס\"ר</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא</a> פל\"ז. לעיל פ' בשלח קפג, ג. וש\"נ."],["4660","67","<b>הטבת ה' נרות</b>: ב: הטבת הנרות, אבל בשאר הכת\"י כבפנים. ראה אוה\"ת כאן (ע' א'תרנז): שבין הערבים נק' העלאת הנרות ובבקר הוא הטבת הנרות. וראה אנציקלופדי' תלמודית כרך ח מערכת הדלקת הנרות ע' שיא ואילך. מערכת הטבת הנרות ע' תשמד ואילך."],["4661","68","<b>מערב עד בוקר</b>: תצוה כז, כא."],["4662","69","<b>מצות ק\"ש. . בוקר וערב</b>: ואתחנן ו, ז. שו\"ע אדה\"ז הל' ק\"ש רסנ\"ח."],["4663","70","<b>שמע ישראל. . שהוא נפה\"א</b>: ראה גם לקמן פ' ויקהל תלה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680071\" data-slug=\"torat-chaim\" data-id=\"2300680071\">תו\"ח ויחי רמ, ב</a> ובהערה 28. מאמרי אדה\"א דברים ח\"ב ע' תעח ואילך."],["4664","71","<b>נפה\"א</b>: ביא: נשמ' האלקי'."],["4665","72","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["4666","73","<b>כד</b>: ביא: ליתא."],["4667","74","<b>ך\"ד אותיות של פסוק דשמע ישראל</b>: ראה גם לעיל שכב, ב. וש\"נ."],["4668","75","<b>לא יכבה בלילה נר\"ה</b>: משלי לא, יח. ראה גם ש\"א מו, א."],["4669","76","<b>רשפי' [רשפי]</b>: שה\"ש ח, ו."],["4670","77","<b>שהוא</b>: ביא: ליתא."],["4671","78","<b>ישראל לי רא\"ש</b>: נסמן לעיל פ' משפטים רפח, ד."],["4672","79","<b>להוי כדי\"ן וכדי\"ן</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תמג ואילך."],["4673","80","<b>את הנרות</b>: ביא: כו'."],["4674","81","<b>מחוץ לפרוכת. . ובניו</b>: תצוה כז, כא [בדילוג]."],["4675","82","<b>דמשה נק' שוש[בין] דמלכא</b>: נסמן לעיל פ' יתרו רסג, ב."]]],[2300550218,"וז\"ש ויקחו אליך דוקא<sup data-n=\"4676\">83</sup> שמן זך כתית למאו\"ר [דוקא שממנו ידליקו אור הנרות דמנורה הוא הנק' מאור מצד שהוא מקור האור וכמ\"ש שמן למאור<sup data-n=\"4677\">84</sup> ] ולא א[מר] לאור אלא למאו\"ר שממנו דוקא יבא התפשטות האור, וזה הי' דוקא מדרגת משה דוקא שהוא בבחי' שם מ\"ה דח\"ע כמ\"ש מ\"ה שמ\"ו<sup data-n=\"4678\">85</sup> כו' ואין עצמות אוא\"ס שורה רק בפנימי' דח\"ע<sup data-n=\"4679\">86</sup> ע\"כ הי' משה שוש' דמלכא להוריד גילוי עצמות אוא\"ס למטה מטה בכנ\"י כו', וא\"א להיות בחי' העלאה והדלקת הנרות דנש\"י ע\"י אהרן כ\"א<sup data-n=\"4680\">87</sup> ע\"י השמן למאו\"ר דמשה בתחילה דוקא, ולכך א' ויקחו אליך דוקא שמן למאור בתחלה כדי להעלות נר תמיד אח\"כ ע\"י אהרן שוש' דמטרוניתא וד\"ל.\n<b>וביאור</b> הענין הנה ידוע בטעם שנק' משה<sup data-n=\"4681\">88</sup> שוש' דמלכא דוקא להיות שכל התורה כולה ניתנה לבנ\"י ע\"י משה דוקא [כמו במ\"ת שהי' כמו שוש' להוריד החתן לגבי הכלה והוא בחי' המשכת גילוי אא\"ס שבחכ' שבתו' ע\"י משה דוקא] כמ\"ש משה ידבר<sup data-n=\"4682\">89</sup> כו' (וגם עכשיו כל הלכה ודבר ה' נמשך ע\"י משה בכאו\"א מישראל<sup data-n=\"4683\">90</sup> כשיושב ושונה כו' כענין משה שפיר קאמרת<sup data-n=\"4684\">91</sup> כמ\"ש במ\"א) להשפיע לכנ\"י שזהו הממוצע המחבר לייחד חתן עם הכלה (ואע\"פ דג' קשרין הם<sup data-n=\"4685\">92</sup> ישראל מתקשראן באוריי' ואורייתא בקוב\"ה ולמה צריך לממוצע דבחי' משה<sup data-n=\"4686\">93</sup>, הענין הוא דמה דנש\"י מתקשרא[ן] בס\"ר אותיות התורה<sup data-n=\"4687\">94</sup> וקוב\"ה באורייתא זהו הכל ע\"י משה שבכחו לייחד גם לאורייתא בקוב\"ה וקוב\"ה באורייתא ואורייתא בישראל כמ\"ש [בו] כי מן המים משיתיהו<sup data-n=\"4688\">95</sup> כמ\"ש במ\"א) (משא\"כ אהרן שוש' דמטרוניתא זהו רק להעלות לנש\"י בוקר וערב לבד כמו בק\"ש שאין זה רק למקור חוצבם [לבד], אבל במ\"ש ויקחו אליך שמן כו' [אמר] להעלות נר תמי\"ד זהו כמו מצות ת\"ת דישראל מתקשראן באורייתא<sup data-n=\"4689\">97</sup> בתמידות<sup data-n=\"4690\">96</sup> יומם ולילה כמ\"ש והגית בו יומם ולילה<sup data-n=\"4691\">98</sup> וכמ\"ש בשכבך ובקומך<sup data-n=\"4692\">99</sup>, וכמו שמלמעלה למטה מאוא\"ס בחכ' <span data-k=\"pg\">תקיב</span> ּ שבתורה מאיר בתמידות משום דאורייתא מתקשרא בקוב\"ה בתמידות וכמ\"ש ואהי' אצלו כו' שעשועים<sup data-n=\"4693\">100</sup> תמידי' וד\"ל). והנה [מ]ובן מזה מאחר שהי' משה בחי' ממוצע להשפיע התורה לישראל<sup data-n=\"4694\">*101</sup> שבודאי הי' ג\"כ בחי' ממוצע להמשיך ולחבר גילוי",[["4676","83","<b>דוקא</b>: ביא: ליתא."],["4677","84","<b>שמן למאור</b>: תרומה כה, ו. ראה גם לעיל טז, ג. שמא, ג. ש\"א מה, ב ובהערה 24."],["4678","85","<b>משה. . מ\"ה שמ\"ו</b>: ראה גם לעיל פ' שמות מג, ד. וש\"נ."],["4679","86","<b>עצמות אוא\"ס שורה. . דח\"ע</b>: ראה גם לעיל פ' שמות ז, ד. וש\"נ."],["4680","87","<b>כ\"א</b>: ביא: אם לא."],["4681","88","<b>שנק' משה</b>: שם: שמשה נק'."],["4682","89","<b>משה ידבר</b>: יתרו יט, יט. ראה גם לעיל שכג, ג. וש\"נ."],["4683","90","<b>משה בכאו\"א מישראל</b>: ראה גם לעיל פ' בשלח קנו, ד. וש\"נ."],["4684","91","<b>משה שפיר קאמרת</b>: ראה גם לעיל פ' שמות י, ב. וש\"נ."],["4685","92","<b>דג' קשרין הם</b>: ראה זהר אחרי עג, א. לעיל פ' שמות ב, ד. וש\"נ."],["4686","93","<b>לממוצע דבחי' משה</b>: נסמן לעיל שכג, ג."],["4687","94","<b>בס\"ר אותיות התורה</b>: ראה מג\"ע אופן קפו. לעיל פ' שמות לב, ב. וש\"נ."],["4688","95","<b>כי מן המים משיתיהו</b>: שמות ב, י."],["4689","97","<b>באורייתא</b>: ביא: ליתא."],["4690","96","<b>מצות ת\"ת. . בתמידות</b>: ראה מנחות צט, סע\"ב. לעיל פ' וארא פא, א. וש\"נ."],["4691","98","<b>והגית בו יומם ולילה</b>: יהושע א, ח."],["4692","99","<b>בשכבך ובקומך</b>: ואתחנן ו, ז־ עקב יא, יט [ושם: ובשכבך]."],["4693","100","<b>ואהי' אצלו כו' שעשועים</b>: משלי ח, ל."],["4694","*101","<b>משה. . להשפיע התורה לישראל</b>: ראה גם לקמן שסב, סע\"ג."]]],[2300550250,"עצמות אוא\"ס שירד ויתלבש בחכ' שבתורה כמו שוש' שמוריד לחתן כו', א\"כ הרי מוכרח לומר מזה שהי' שרש נשמתו גבוה מבחי' החכ' שבתורה<sup data-n=\"4695\">101</sup> שירדה למטה מאין ליש בגילוי הדבור, כידוע הכלל דכל מי שיש בכחו להמשיך השפע צ\"ל יותר עליון מגוף אור השפע שנשפע ע\"י. והוא מ\"ש במשה כי מן המים משיתיהו<sup data-n=\"4696\">102</sup> כו' מבחי'<sup data-n=\"4697\">103</sup> ח\"ע<sup data-n=\"4698\">104</sup> שמעל לרקיע שנק' ים הקדמוני<sup data-n=\"4699\">105</sup> דח\"ע הקדומה שהוא בחי' פנימי' ומקור דחכ' קודם שבאה מן ההעלם לגילוי מאין ליש באותיות הדיבור, כמ\"ש והחכ' מאין תמצא<sup data-n=\"4700\">106</sup> פי' מבחי' האי\"ן והעלם דכת\"ר שמשם יצא החכ' מאין ליש שז\"ש דאורייתא מח\"ע נפקת<sup data-n=\"4701\">107</sup> מאין ליש אבל לא שה[י]א [ב]בחי' אין ממש. אך שרש נשמת משה הי' מבחי' העלם ואין דח\"ע הקדומה שנק' תעלומות חכ'<sup data-n=\"4702\">108</sup> או פלאות חכ'<sup data-n=\"4703\">109</sup> שא\"א שתבא לידי גילוי בדבור כלל ([ו]כמו כח השכל בעצם טרם שישכיל השכל בגילוי שאינו במציאות חכ' ושכל עדיין שאז לא יוכל להביאו בדבור כלל כידוע, ובזהר נק' רז\"א דרזי\"ן<sup data-n=\"4704\">110</sup> סוד סתום לגמרי ולמעלה נק' שכל הנעלם מכ\"ר<sup data-n=\"4705\">111</sup> כו' והוא [בחי'] פלאות<sup data-n=\"4706\">112</sup> דחכ' כו', וזהו כמו שהחכ' היא במקורה ממש קודם שתבוא לכלל בחי' אור שע\"כ הוצרך לומר יהי אור<sup data-n=\"4707\">114</sup> כו'<sup data-n=\"4708\">113</sup>. וזהו שהי' משה כבד פה וכבד לשון<sup data-n=\"4709\">115</sup> וא[מר] בזהר ור\"מ כבד פה לתושבע\"פ וכבד לשון [ב]תושב\"כ שלא הי' יכול להשפיל ולהוריד א\"ע לתושב\"כ ותושבע\"פ להיות נמשך מהעלם דח\"ע העצמי' שנק' תעלומות חכ' שא\"א לבוא בדיבור בפה בתושבע\"פ ובלשון בתושב\"כ, שז\"ש פיה פתחה בחכ'<sup data-n=\"4710\">116</sup> ותורת חסד על לשונה שהן מדות דתושב\"כ להבדיל בין טמא לטהור<sup data-n=\"4711\">117</sup> כו' וד\"ל. אך אע\"פ שהי' משה כבד פה וכבד לשון הרי נאמר בו משה ידבר דוקא, לפי שהי' זה ע\"פ ה' שהי' לעזר לעשות בשרש נשמת משה בח\"ע בחי' ירידה והמשכה מן ההעלם לגילוי דוקא, כי קמי' עצמות הא\"ס שהוא למעלה מבחי' ההעלם דח\"ע לפניו נגלו כל תעלומות דח\"ע ששוין לפניו בחי' ההעלם וגילוי ע\"כ יכול להביא ולהמשיך גם לבחי' [ההעלם] דחכ'<sup data-n=\"4712\">118</sup> הקדומה ממש שתבא בדיבור בפה בתושבע\"פ ולשון בתושב\"כ כו' כמ\"ש משה ידבר והאלקים יעננו בקול וארז\"ל בקולו של משה<sup data-n=\"4713\">119</sup> דוקא וד\"ל (וההתחלה לזה הי' במ\"ש [לו] ה' בשליחות ששלח למשה לדבר לפרעה שא' משה הן אני ערל שפתים<sup data-n=\"4714\">120</sup> כו' והשיבו ה' מי שם פה לאדם כו' הלא אנכי<sup data-n=\"4715\">121</sup> מ\"י שאנכ\"י<sup data-n=\"4716\">122</sup> ואנכי אהי' עם פיך<sup data-n=\"4717\">123</sup> כו' כמ\"ש במ\"א).",[["4695","101","<b>כמו. . שבתורה</b>: ב: ליתא. וכנראה נשמט מפני תיבות הדומות: שבתורה. . שבתורה."],["4696","102","<b>משיתיהו</b>: ביא: ליתא."],["4697","103","<b>כי מן המים. . מבחי' מ\"ע</b>: ראה לעיל פ' שמות מג, א. וש\"נ."],["4698","104","<b>ח\"ע</b>: ביא: מ\"ע."],["4699","105","<b>מ\"ע. . שנק' ים הקדמוני</b>: ראה גם לעיל פ' שמות מד, א. וש\"נ."],["4700","106","<b>והחכמה מאין תמצא</b>: איוב כח, יב. ראה הנסמן לעיל פ' בא קא, ג."],["4701","107","<b>דאורייתא מח\"ע נפקת</b>: נסמן לעיל פ' יתרו רסח, ד."],["4702","108","<b>תעלומות חכ'</b>: איוב יא, ו. ראה גם לעיל פ' שמות לג, א. וש\"נ."],["4703","109","<b>פלאות חכ'</b>: ראה גם לעיל פ' שמות כא, ב. וש\"נ."],["4704","110","<b>רז\"א דרזי\"ן</b>: ראה זהר בראשית מא, א."],["4705","111","<b>שכל הנעלם מכ\"ר</b>: נסמן לעיל שמא, ד."],["4706","112","<b>פלאות</b>: ביא: פל\"א. א: כבפנים."],["4707","114","<b>יהי אור</b>: בראשית א, ג."],["4708","113","<b>וזהו. . כו'</b>: ב: ליתא. וכנראה נשמט מפני תיבות הדומות: כו'. . כו'."],["4709","115","<b>כבד פה וכבד לשון</b>: ראה גם לעיל פ' יתרו רנו, ג. וש\"נ."],["4710","116","<b>פיה פתחה בחכ'</b>: משלי לא, כו."],["4711","117","<b>להבדיל בין טמא לטהור</b>: ע\"פ שמיני יא, מז."],["4712","118","<b>דחכ'</b>: יא: דח\"ס."],["4713","119","<b>בקולו של משה</b>: ברכות מה, א."],["4714","120","<b>הן אני ערל שפתים</b>: לשון הכתוב וארא ו, ל. וראה שמות ד, י."],["4715","121","<b>מי שם פה. . הלא אנכי</b>: שמות ד, יא."],["4716","122","<b>אנכי מ\"י שאנכ\"י</b>: ראה גם לעיל פ' יתרו רנד, ג. וש\"נ."],["4717","123","<b>ואנכי אהי' עם פיך</b>: שמות ד, יב. ראה לעיל פ' שמות מז, ד ואילך. יב, ב. וארא פ, ב."]]],[2300550281,"(ד) <b>וזהו</b> שהי' שמן למאו\"ר ע\"י משה דוקא כמ\"ש ויקחו אליך שמן זית זך כתית<sup data-n=\"4718\">124</sup> כו', [כי] הנה התורה נק' אור כמ\"ש ותורה אור<sup data-n=\"4719\">125</sup> ואמנם מקור החכ' שבתו' [הוא ש]נק' מאו\"ר שממנו מקור מוצא כל<sup data-n=\"4720\">126</sup> האור כנ\"ל והוא בחי' שמן שנק' שמן למאו\"ר דוקא, להיות שהשמן הגשמי ממנו נמצא מקור למציאות האור שע\"י נמשך התמדת הדלקה שידלק האור בפתילה ואם אין שמן בנר יקפוץ האור מן הפתילה ומיד כשיכלה השמן יכבה אור [הנר] כידוע, לפי שהשמן עצמו יש בו בכח והעלם להיות ממנו נמשך <span data-k=\"pg\">1026</span> ּ התפשטות האור אע\"פ שאין בשמן אור ממש כי הרי האור שואב לשמן וידליק, ואנו רואים שבהירות האור דנר תלוי בצלילות השמן לפי שהשמן נמשך בפתילה ונשאב באור וזהו כמו כח היולי דאור כו'. וכך הוא בענין כח היולי דחכ' שנק' תעלומות חכ' טרם שבאה מאי\"ן ליש שהוא מקור כל התהוות מציאות אור דחכ' שעדיין אין שם בחי' אור דחכ' בגילוי, וגם לא הי' בבחי' נקודה דחכ' שמאין תמצא שזהו הבא מאין ליש בהשגה דבינה ונק' תרדל\"מ<sup data-n=\"4721\">127</sup> [כידוע] במשל מעין הנובע שנמשך ממנו הנהר בהתפשטות, וכמו הברקת אור נקודת השכל שמתפשט אח\"כ לאורך ורוחב בהשגה דבינה בהכרח. אבל בחי' השמן שנק' שמן למאור (או שמן משחת קדש<sup data-n=\"4722\">128</sup> דחכ') הוא למעלה גם מבחי' נקודה דחכ', והוא בכח היולי דכח המשכיל עצמו שבכחו להשכיל כל שכל ועדיין לא נמשך נביעה ומקור לשכל פרטי הנק' נקודה, והוא מה שלא יכול לבא בדיבור לעולם כנ\"ל (ונק' שכל מופלא<sup data-n=\"4723\">129</sup> לגמרי או שכל הנעלם מכ\"ר, שהרעיון הוא ההשגה ויש [ד]חכ' שבאה מאין ליש בהשגה זהו שבא ג\"כ לדיבור, אבל עצם כח המשכיל שאינו בא לכלל משפיע שכל גם בבחי' נקודה הרי זה בא<sup data-n=\"4724\">130</sup> בבחי' אי\"ן ממש וע\"ז א' והחכ' מאין ממש תמצא בבחי' נקודה כו').\n<b>וזהו</b> ענין [ה]שמן ש[הוא] צף ע\"ג היין<sup data-n=\"4725\">131</sup> ואין לו חיבור כלל עם היין גם לענין [טומאה גם<sup data-n=\"4726\">*132</sup> ב]נגיעה כידוע, והענין הוא כי שרש השמן והיין למעלה הוא בבחי' חו\"ב<sup data-n=\"4727\">132</sup> כידוע והיין הוא מבחי' בינה שבא מהעלם לגילוי בהשגה גם בפנימי' דבינה כמו נכנס יין יצא סוד<sup data-n=\"4728\">133</sup> דיי\"ן גימ' סו\"ד<sup data-n=\"4729\">134</sup> והוא בחי' סוד והעלם דנקודה דחכ' שמאין תמצא שבא להתפשטו' לגילוי בהשגה כנ\"ל. אבל יש סוד סתום לגמרי והוא בחי' תעלומות דחכ' שנק' שמן שנשאר בהעלמו ולא יוכל לבא מאין ליש כלל בבינה, וזהו",[["4718","124","<b>כתית</b>: ביא: ליתא."],["4719","125","<b>ותורה אור</b>: משלי ו, כג."],["4720","126","<b>כל</b>: ביא: ליתא."],["4721","127","<b>דחכ'. . דבינה ונק' תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. לעיל פ' בא קכ, א. וש\"נ."],["4722","128","<b>שמן משחת קדש</b>: תשא ל, כה. לא. ראה גם מאמרי אדה\"א בראשית ע' תכ."],["4723","129","<b>שכל מופלא</b>: נסמן לעיל שמא, ד."],["4724","130","<b>בא</b>: ביא: ליתא."],["4725","131","<b>[ה]שמן ש[הוא] צף ע\"ג היין</b>: ראה שבת ה, ב. לעיל פ' בא קכ, ג. וש\"נ."],["4726","*132","<b>גם</b>: א: וגם. ו: טהרה וגם."],["4727","132","<b>השמן והיין. . חו\"ב</b>: ראה במקומות שנסמנו לעיל שם."],["4728","133","<b>נכנס יין יצא סוד</b>: ערובין סה, סע\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680053\" data-slug=\"torat-chaim\" data-id=\"2300680053\">תו\"ח ויחי רלו, ב</a>."],["4729","134","<b>דיי\"ן גימ' סו\"ד</b>: ראה ערובין שם."]]],[2300550309,"שצף ע\"ג היין מלמעלה ואין לו שום חיבור ודיבוק עם היין דבינה (דהיינו גם שנכנס יין לא יצא סו\"ד זה לגילוי [בהשגה לעולם)] כמו רזא דרזין ונק' חכם חרשים ונבון לחש<sup data-n=\"4730\">135</sup> כו')<sup data-n=\"4731\">136</sup>, והוא בחי' השתיקה שהוא סייג לחכ'<sup data-n=\"4732\">137</sup> שלמעלה מנקודות דחכ' שבאה בדיבור כמ\"ש מלה בסלע ושתיקה בתרין<sup data-n=\"4733\">138</sup> כו' שהשתיקה מורה על הפלא' והעלם דחכ' כמו שהיא במקורה העצמי' שלא יוכל לבא בדבור כלל (וכנ\"ל במשה שהי' כבד פ\"ה כו'). וזהו ג\"כ מה שאנו רואים בטבע השמן שהוא נמשך ועומד בחשאי ובשתיקה וטבע היין ברתיחה והתגברות חום קשה כו', כי טבע השמן קר ולח להיות [ש]שרשו בבחי' כח החכ' שהוא מקור החסדי'<sup data-n=\"4734\">139</sup> [ו]הוא בבחי' [ה]ביטול [והעדר] ההרגש וההתפעלו' כו', וטבע היין חם ויבש ע\"כ הוא תוסס ברתיחה [ומחמם] ופועל חמימות והתלהבות [וכעס] כפי שרשו למעלה בבחי' גבורה דבינה<sup data-n=\"4735\">140</sup> כידוע משא\"כ השמן וד\"ל.\n(ה) <b>וזהו</b> ואתה תצוה את בנ\"י אתה דוקא ויקחו אליך דוקא שמן זית זך כתית למאור פי' שמן זה יהי' ממנו נמצא בבחי' מאור לאורות דנש\"י להעלות נר תמיד כו'<sup data-n=\"4736\">141</sup> וזהו שמן זית כו' למאור בשביל מאור לאור (כמו מאיר עיני חכמים בהלכה<sup data-n=\"4737\">142</sup> כו' וכה\"ג<sup data-n=\"4738\">143</sup> ). והענין הוא כי הנה מובן מכל הנ\"ל עכ\"פ דהשמן הוא הוא<sup data-n=\"4739\">144</sup> המקור שממנו יוכל להיות הדלקת האור בנר, ואמנם א\"א לומר שהשמן עצמו יהי' נק' בשם מאור להאיר אור ממש כשמש שנק' מאור<sup data-n=\"4740\">145</sup> שממנו <span data-k=\"pg\">תקיג</span> ּ יאיר האור בגילוי [ו]כמ\"ש את המאור הגדול<sup data-n=\"4741\">146</sup> כו', שיש יחוס והשתוות עכ\"פ לזיו ואור השמש עם גוף [מאור] השמש כי השמש עצמו הוא [עצם] ספירי מאד ובהיר אורו בעצם ע\"כ יזרח אור לארץ, אבל השמן אינו מגדר וסוג האור ומאור<sup data-n=\"4742\">147</sup> ואיך נק' בשם מאור. ועכ\"ז אנו רואים שממנו וע\"י [דוקא] יהי' המציאות של האור דנר בגוונים<sup data-n=\"4743\">148</sup> לבן כפי בהירות וצלילות השמן דוקא, אלא צ\"ל שיש בשמן מקור להיות ממנו המשכת האור הנק' מאו\"ר והוא מ\"ש שמן זית זך כתית למאור [דהיינו] שכפי ערך זכות השמן כך יהי' המאור לאור, וזהו שבא מבחי' ההעלם ממש להיות מקור לגילוי אור הנר כו'. וכך יובן למעלה בבחי' שמן למאו\"ר דהיינו בחי' חכ' הקדומה שכלולה בעצמות א\"ס ממש שנק' בכלל חכים ולא בחכ' ידיעא<sup data-n=\"4744\">149</sup> כלל, ומה שנמשך ממנו להיות מקור לכל חכ' זה[ו] שנק' מאור שמאיר כל אור דחכ' וה[וא] מאור דאור דתורה",[["4730","135","<b>חכם חרשים ונבון לחש</b>: ישעי' ג, ג."],["4731","136","<b>כו')</b>: ביא: ליתא."],["4732","137","<b>השתיקה שהוא סייג לחכ'</b>: אבות פ\"ג, מי\"ג. ראה גם לעיל פ' שמות מז, ג. יתרו רסז, ד."],["4733","138","<b>מלה בסלע ושתיקה </b>[ב: משתוקא]<b> בתרין</b>: ראה מגלה יח, א. הנסמן לעיל שם."],["4734","139","<b>החכ' שהוא מקור החסדי'</b>: ראה סידור שער התפילין ט, סע\"ד. מאמרי אדה\"א הנחות תקע\"ז ע' כח. וש\"נ."],["4735","140","<b>היין. . גבורה דבינה</b>: ראה מאמרי אדה\"א בראשית ע' רפז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680332\" data-slug=\"torat-chaim\" data-id=\"2300680332\">תו\"ח וישלח קצג, ג</a> ובהערה 14."],["4736","141","<b>כו'</b>: ביא: ליתא."],["4737","142","<b>מאיר עיני חכמים בהלכה</b>: ערובין יג, ב. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תרסה."],["4738","143","<b>(כמו. . וכה\"ג)</b>: ביא: כמו. . וכה\"ג."],["4739","144","<b>הוא</b>: שם: ליתא."],["4740","145","<b>כשמש שנק' מאור</b>: ראה גם מאמרי אדה\"א נ\"ך ע' רמד. וש\"נ. וראה גם לקוטי ביאורים לשער היחוד (קה\"ת) קעד, ד."],["4741","146","<b>את המאור הגדול</b>: בראשית א, טז."],["4742","147","<b>ומאור</b>: ביא: להאיר."],["4743","148","<b>בגוונים</b>: שם: בגוון."],["4744","149","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה (יז, ב). ז\"ח יתרו לד, ד. ראה גם לעיל פ' יתרו רסו, סע\"ד ואילך."]]],[2300550334,"(כמאמר מאור שבה<sup data-n=\"4745\">150</sup> כו') כמשל האבוקה ושלהבת הגדולה שנק' מאור שמשם מאיר למרחוק וכל ניצוצי' הקטנו' יוכללו כא' ונמשכו<sup data-n=\"4746\">151</sup> במאו\"ר לפי שכל דבר נמשך לשרשו<sup data-n=\"4747\">152</sup>. וכך בכל ס\"ר אותיות התו' שהן פרטי ניצוצי' דאור החכ' כולם נכללים במאור הכללי דאור דתורה דאורייתא מח\"ע נפקת, אבל כדי שיהי' בחי' מאור זה בהכרח שבא מבחי' ההעלם דעצמות [א]א\"ס ממש בדרך דילוג גדול כמו השמן שממנו יבא מאור האור כו' וכמ\"ש ואהי' אצלו [אמון]<sup data-n=\"4748\">153</sup> כו' אצלו ממש בביטול והתכללות ונק' משל הקדמוני<sup data-n=\"4749\">154</sup> כו'. וזה הי' שרש נשמת משה כנ\"ל [שזהו] בכח העצמ[ו'] דא\"ס דוקא להביא מן<sup data-n=\"4750\">155</sup> ההעלם לגילוי לפי שלפניו שוין ההעלם והגילוי דחכ' דהיינו מאור ואור כו', וע\"כ הי' ביכולת [משה דוקא] להביא ולהמשיך מהעלם דחכ' דתורה לגילוי כו', וע\"כ הי' השמן למאור ע\"י משה דוקא שהי' ביכולתו להמשיך בחי' מאור לאור דתורה מעצמו' החכ' שבא\"ס ממש וזהו ויקחו אליך שמן אליך דוקא וד\"ל.\n<b>וזהו</b> ויקחו אליך שמן כו' למאור להעלות נר תמיד שהוא הדלקת נרות המנורה שהן העלאה כלל[ות] נש\"י ע\"י אהרן כנ\"ל שאם לא בחי' שמן למאור ע\"י משה תחילה א\"א להיות הדלקת נרות ע\"י אהרן וזהו להעלות כדי להעלות כו'. והענין יובן ע\"ד הנ\"ל באור [ו]מאור דחכ' שבתורה שע\"י משה נמשך בחי' מאור לאור דתורה ואז יכול להיות העלאה וביטול כל אור במאור, אבל אם אין מאור איך יוכל להיות ביטול והתכללות אור כי אין אור בלא מאור וא\"א להיות בחי' ביטול והתכללו' דאור רק בפני האבוקה והמאור דוקא לפי שכל דבר נמשך אל שרשו דוקא כו'. וכך יובן בשרש נש\"י שנק' נרות שיש להם מקור כללי למעלה במקור חוצבם הראשון שנק' מאור שממנו מקור כל אור דנש\"י, והוא בחי' מקור החכ' דאצי' שנק' אור אבא (כמו [משל] הולד הנולד מטיפה שבמוח<sup data-n=\"4751\">156</sup> האב<sup data-n=\"4752\">157</sup> כמ\"ש במ\"א) כמ\"ש כי בנים אתם<sup data-n=\"4753\">158</sup> כו' וכתיב בני בכורי ישראל<sup data-n=\"4754\">159</sup> [ו]ע\"כ אנו אומרי' כי את\"ה אבינ\"ו ממש [כו'], ששם הוא מקור כל אור דחכ' דתו' שהן ס\"ר נש\"י בפרט שכלולי' בס\"ר אותיות התורה<sup data-n=\"4755\">160</sup> דג' קשרים הן ישראל מתקשראן באורייתא ואוריי' בקוב\"ה (כמו דאוריי' וקוב\"ה סתים וגליא<sup data-n=\"4756\">161</sup> כך ישראל עלו במח'<sup data-n=\"4757\">162</sup> זה<sup data-n=\"4758\">163</sup> כו'). וזהו להעלות <span data-k=\"pg\">1028</span> ּ נר תמיד שזהו להעלות לנש\"י במקור חוצבם הראשון שהוא בבחי' המאור הכללי מקור הראשון דכל אותיות<sup data-n=\"4759\">164</sup>",[["4745","150","<b>מאור שבה</b>: נסמן לעיל שלו, ד."],["4746","151","<b>יוכללו כא' ונמשכו</b>: ביא: יומשכו ויכללו."],["4747","152","<b>שכל דבר נמשך לשרשו</b>: ראה גם לעיל פ' בא צה, ב. וש\"נ."],["4748","153","<b>ואהי' אצלו [אמון]</b>: משלי ח, ל."],["4749","154","<b>משל הקדמוני</b>: נסמן לעיל פ' יתרו רנט, ד."],["4750","155","<b>מן</b>: ביא: ליתא."],["4751","156","<b>[משל]. . שבמוח</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' שפח. וש\"נ. בראשית ע' ל. וש\"נ. שמות ח\"ב ע' תפו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670454\" data-slug=\"torat-chaim\" data-id=\"2300670454\">תו\"ח בראשית כז, א</a>."],["4752","157","<b>האב</b>: ביא: ליתא."],["4753","158","<b>כי בנים אתם</b>: פ' ראה יד, א [בהוספת תיבת כי — ראה לעיל פ' וארא פה, ג. וש\"נ]."],["4754","159","<b>בני בכורי ישראל</b>: שמות ד, כב."],["4755","160","<b>ס\"ר נש\"י. . אותיות התורה</b>: ראה גם לעיל פ' שמות ב, ד. וש\"נ."],["4756","161","<b>דאוריי' וקוב\"ה סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א. לעיל פ' משפטים רצ, ג. וש\"נ."],["4757","162","<b>ישראל עלו במח'</b>: ב\"ר פ\"א, ד. ראה הנסמן לעיל פ' שמות לב, ב."],["4758","163","<b>זה</b>: ביא: ליתא."],["4759","164","<b>אותיות</b>: שם: אור."]]],[2300550359,"ונר הוי' דנש\"י, וא\"א הי' לאהרן כה\"ג להעלותם לשם בבחי' ביטול והתכללות כמו בהתעוררות דאה\"ר ותשובה אמיתי' הנמשך לנש\"י מלמעלה למטה כנ\"ל בפי' בהעלותך כו' אם לא ע\"י משה דוקא, שהמשיך בחי' מאור זה דנשמה<sup data-n=\"4760\">165</sup> שזהו ענין בחי' שמ\"ן למאו\"ר שמעצמות אוא\"ס נמשך בחי' מאור דחכ' התורה ששם מקור כללות נש\"י, שאז כאשר יש בחי' מאור ממילא הי' ביכולת אהרן להעלות כל או\"ר דנש\"י [שנק' נרות] שיהיו בטלים ונכללים במאור זהו כמו במשל<sup data-n=\"4761\">166</sup> הנר בפני האבוקה הסמוכה (כמו בעשי\"ת דכתי' בהמצא\"ו<sup data-n=\"4762\">167</sup> כו' בהיות\"ו קרו\"ב כו' שבחי' המאור שנק' אבינו קרוב לניצוצים<sup data-n=\"4763\">168</sup> דנש\"י שממילא נמשכים ונכללים בו, וזהו סיבת התעוררות התשובה בכל ההמון גם [ב]קל<sup data-n=\"4764\">170</sup> שבקלים<sup data-n=\"4765\">169</sup> שנתרחק ביותר מאחר שהמאור קרוב למקום המרוחק כו'). וכמ\"כ בעלי' למעלה כדוגמא דעולה לרגל שיראה כל זכורך את פני הוי'<sup data-n=\"4766\">171</sup> ממש שהוא קירוב הניצוצי' לגבי המאור וכך הי' במ\"ת שבאור פניך ממש נתת לנו<sup data-n=\"4767\">172</sup> תורת<sup data-n=\"4768\">173</sup> כו' וד\"ל). אבל בלא בחי' שמן למאור א\"א להיות ביטול והתכללו' דנש\"י למעלה לפי שאין ביטול הנר רק בפני האבוקה דוקא לפי שכל דבר נמשך אל שרשו ויסודו כאור הנר שעולה ונכלל למעלה במקור חוצבו באש היסודי ואם אין שרש ומקור לא יהי' התעוררות בניצוצים כלל לעלות כו' וד\"ל.\n(וי\"ו) <b>וזהו</b> ויקחו אליך שמן זית<sup data-n=\"4769\">174</sup> כו' ואח\"כ אמר באהל מועד מחוץ לפרוכת<sup data-n=\"4770\">175</sup> יערוך אותו אהרן כו', כי משה נק' שוש' דמלכא להוריד ולהמשיך לעצמות אוא\"ס להיות נק' מאו\"ר (שהוא אבינ\"ו כנ\"ל) ואז ביכולת אהרן שוש' דמטרוניתא להעלות לנש\"י להיות ביטול האור במאור כו' להיות נמשכים לשרשם ומקורם הראשון כנ\"ל, וזהו כמו השוש' דחתן וכלה ממש ששושבין דחתן מוריד לחתן שיתחבר בכלה ושוש' דכלה מעלה אותה ומביא אותה אל החתן כידוע. וכך הוא למעלה ביחוד קוב\"ה [ושכינתי'] שהן [כ]נ\"י שנק' כלה שבאמצעית משה ואהרן שוש' דמלכא ומטרוניתא מתחברי' יחד בחי' החתן יורד מלמעלמ\"ט לשון נחות דרגא<sup data-n=\"4771\">176</sup> להיות נק' מאור משפיע לנש\"י וכל\"ה<sup data-n=\"4772\">177</sup> מל' כלת\"ה נפשי<sup data-n=\"4773\">178</sup> שזהו ביטול והתכללות דאור במאור ע\"י אהרן בהעלות את הנרות דנש\"י מלמטה למעלה בבחי' או\"ח למקור[ו] הראשון כנ\"ל וד\"ל. אך הנה כ\"ז היחוד [ה]עליון בקוב\"ה ושכינתי' בחי' חתן וכלה הנ\"ל הי' נעשה",[["4760","165","<b>דנשמה</b>: שם: (ל)דנש\"י."],["4761","166","<b>במשל</b>: שם: ביטול."],["4762","167","<b>בעשי\"ת דכתי' בהמצאו</b>: ישעי' נה, ו. ר\"ה יח, א."],["4763","168","<b>בעשי\"ת. . המאור. . קרוב לניצוצים</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' שכו. ח\"ב ע' תקכד. ח\"ד ע' א'שס. וש\"נ. נ\"ך ע' שפא. לעיל פ' בא קו, א."],["4764","170","<b>[ב]קל שבקלים</b>: ע\"פ ר\"ה כה, ב. תוספתא ר\"ה ספ\"א. קה\"ר פ\"א, ד (ד). רש\"י ויצא כט, כא."],["4765","169","<b>התעוררות התשובה. . [ב]קל שבקלים</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' פג. וש\"נ. שמות ח\"ב ע' שמו. וש\"נ. קונטרסים ע' קנ. וש\"נ. הנחות תקע\"ז ע' ק. לקמן שסט, ג."],["4766","171","<b>שיראה כל זכורך את פני ה'</b>: פ' ראה טז, טז."],["4767","172","<b>שבאור פניך. . נתת לנו</b>: ע\"פ סיום תפלת העמידה."],["4768","173","<b>תורת</b>: ביא: ליתא."],["4769","174","<b>זית</b>: שם: ליתא."],["4770","175","<b>באהל מועד מחוץ לפרוכת</b>: תצוה כז, כא [בדילוג]."],["4771","176","<b>החתן. . נחות </b>[יא: חו\"ת]<b> דרגא</b>: ראה יבמות סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תקז. וש\"נ."],["4772","177","<b>וכל\"ה</b>: ביא: שנק' כלה."],["4773","178","<b>וכל\"ה מל' כלתה נפשי</b>: ראה גם לעיל פ' בשלח רח, א. וש\"נ."]]],[2300550379,"בתמידות בבהמ\"ק דוקא שנא' בו ועשו לי מקדש<sup data-n=\"4774\">179</sup> ושכנתי בתוכם [ושכנתי] ממש [בתוכם] כו' (והוא ע\"י בחי' [ה]שמן למאו\"ר דמשה והעלאת הנרות שע\"י אהרן כנ\"ל שהן ב' שוש' דחתן וכלה לייחדם יחד כו', אמנם יש יתרון מעלה בבהמ\"ק ע\"י הקרבנות ע\"ג המזבח יותר ממשכן דמשה גם שהי' שמ\"ן למאו\"ר והעלאת הנרות כו' ), והענין הוא כידוע בדרז\"ל עמ\"ש ביום חתונתו זה מ\"ת<sup data-n=\"4775\">181</sup> וביום שמחת לבו זה בנין בהמ\"ק הרי בבהמ\"ק הי' שמחת לבו יותר מזמן מ\"ת שנק' חתונתו כמ\"ש כחתן יכהן פאר<sup data-n=\"4776\">182</sup> [כו' דגם] שבאור <span data-k=\"pg\">תקיד</span> ּ פניך ממש נתת לנו<sup data-n=\"4777\">183</sup> אור תורה שזהו כמו יחוד האור במאור דתורה<sup data-n=\"4778\">184</sup> דאור דתו' כאשר עכ\"ד פרחה נשמתן<sup data-n=\"4779\">185</sup> כו' עכ\"ז ע\"י הקרבנות בבהמ\"ק הי' שמחת לבו יותר מאור הארת פנים דמ\"ת כו'.\n<b>וביאור</b> הענין הנה כתי' שמן וקטורת ישמח לב<sup data-n=\"4780\">186</sup> שמן למאו\"ר וקטורת וקרבנות ישמח לב אדה\"ע, אבל שמחת לבו מקטורת וקרבנות למעלה משמחת דשמן למאור ואור הנ\"ל. והענין הוא כידוע בשרש ענין הקרבנות מן הקרבת חלב ודם<sup data-n=\"4781\">187</sup> מן הבהמה כו' שיעלה לריח ניחוח להוי' שהוא בחי' אדה\"ע דאצי' כו', זהו כמו משל דם הוא הנפש באדם למטה שאנו רואים שעיקר [ו]שרש החיות שבדם הוא הנפש [הוא] בחלל השמאלי שבו שממנו יוצא וסובב והולך הדם בכל האברים מלמעלה למטה וחוזר ועולה הדם מלמטה למעלה. וזהו הב' דפיקות [ש]בלב<sup data-n=\"4782\">189</sup> שדופק חיות הדם הוא הנפש בחלל השמאלי ונכלל ברוח החיים שבחלל הימיני<sup data-n=\"4783\">188</sup> לקבל משם עיקר ושרש חיות הרוחני. כי גם שיש חיות הנפש בדם ושורה בו ממש וע\"כ א' כי הדם הוא הנפש<sup data-n=\"4784\">190</sup> ([ו]כמ\"ש ברביעית דם שהנפש תלוי' בו<sup data-n=\"4785\">191</sup> ממש כו')<sup data-n=\"4786\">180</sup>, עכ\"ז בחי' נפש שבדם מקבל מבחי' רוח החיים שבלב בחלל הימני ואין המשכת החיות הנפש בדם כ\"א ע\"י התלבשות רוח החיים בנפש כשעולה ונכלל בו בהעלא' מלמטה למעלה תחלה [כו'], כידוע דנפש ורוח הן בחי' מקבל ומשפיע<sup data-n=\"4787\">192</sup> דנפש בחי' מקבל מרוח כנוק' שמקבל[ת] מדכר<sup data-n=\"4788\">193</sup> ומתייחדים יחד (והן ענין ב' הדפ[י]ק[ות] שבלב א' העלאת דנפש מחלל השמאלי ברוח החיים שבחלל הימני, והב' המשכת דרוח בנפש). דהיינו שבחי' המובחר שעלה מן הדם בחלל השמאלי עולה לרוח החיים שבלב, ומן הדם המובחר הזה שנכלל ברוח החיים שבחלל הימיני נברר עוד בירור שני והן כמו גידי'<sup data-n=\"4789\">194</sup> דקים",[["4774","179","<b>ועשו לי מקדש</b>: תרומה כה, ח."],["4775","181","<b>ביום חתונתו זה מ\"ת</b>: נסמן לעיל פ' יתרו רסא, ד הערה 256."],["4776","182","<b>כחתן יכהן פאר</b>: ישעי' סא, י."],["4777","183","<b>שבאור פניך. . נתת לנו</b>: סיום תפלת העמידה."],["4778","184","<b>דתורה</b>: ביא: ליתא."],["4779","185","<b>עכ\"ד פרחה נשמתן</b>: נסמן לעיל רנג, ד."],["4780","186","<b>שמן וקטורת ישמח לב</b>: משלי כז, ט."],["4781","187","<b>חלב ודם</b>: ביא: הדם."],["4782","189","<b>הב' דפיקות [ש]בלב</b>: ראה גם לעיל קד, סע\"ב ואילך."],["4783","188","<b>בחלל השמאלי. . שבחלל הימיני</b>: ראה גם ש\"א י, ב ובהערה 19. לעיל פ' בא קד, א."],["4784","190","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג. ראה גם לעיל קד, ב. וש\"נ."],["4785","191","<b>ברביעית דם שהנפש תלוי' בו</b>: ראה שבת לא, סע\"ב. מאמרי אדה\"א הנחות תקע\"ז ע' ע. וש\"נ."],["4786","180","<b>(והוא. . כו')</b>: ביא: והוא. . כו'."],["4787","192","<b>דנפש ורוח. . מקבל ומשפיע</b>: ראה גם זהר לך פג, ב."],["4788","193","<b>דנפש. . מרוח כנוק'. . מדכר</b>: באוה\"ת תצוה כאן (ס\"ע א'תרנט) מציין כמ\"ש בזהר דמשפטים בהסבא. ראה גם מאמרי אדה\"א נ\"ך ע' לב. וש\"נ."],["4789","194","<b>גידי'</b>: ביא: אידים."]]],[2300550398,"ורוחני' שבו שעולים מן הלב אל המוח ונעשה מזה אור וחיות חדש במוחין שבראש, ומסיבת העלא' זו חוזר ונמשך אור וחיות חדש לגמרי מן המוח אל הלב ברוח החיים שבחלל הימיני שמוסיף אור חדש באור ורוח רוחני זה שבחלל זה הריקן מכל דם<sup data-n=\"4790\">195</sup> ומחמת זה חוזר ונמשך תוס' אור וחיות רוחני מרוח החיים לבחי' נפש שבדם בחלל השמאלי כנ\"ל. וזהו ענין ב' הדפיקות שבלב בבחי' רו\"ש בכללות, דפיקו הא' בבחי' רצוא מלמטה למעלה מן הלב אל המוח ע\"י העלאה דנפש ברוח כנ\"ל ומרוח לנשמה שבמוח ועי\"ז נעשה דפיקו הב' בבחי' שוב שהוא המשכה חדשה מן המוח אל הלב ברוח החיים ומרוח החיים שבחלל הימני לחלל השמאלי, ומחיבור ב' דפיקות הללו יחד נעשה ונמשך בחי' המשכת אור וחיות חדש בדם הוא הנפש בהילוך וסיבוב בכל האברים וכך חוזר חלילה תמיד (וזהו בחי' העלאה דנר\"נ נפש ברוח ורוח בנשמה והמשכה דנשמה ברוח ורוח בנפש בתמידות כו' וכמ\"ש במ\"א שזהו כמ\"ש כל הנחלים<sup data-n=\"4791\">196</sup> הולכים שם הם שבים כו').\n<b>וכך</b> יובן למעלה בשרש הקרבנות דכתיב בהו לריח ניחוח להוי'<sup data-n=\"4792\">197</sup> כמשל המאכל שנברר מן הדם שנעשה ממנו חיות המובחר ועולה <span data-k=\"pg\">1030</span> ּ ללב כנ\"ל, והקרבנות נק' לחמי לאשי<sup data-n=\"4793\">198</sup> כו' וכמ\"ש בזהר דג' שליטין אינון לעילא<sup data-n=\"4794\">199</sup> מוחא וליבא וכבדא שהן בחי' הכלים לנר\"נ דאדם דאצי' כו', והעלאת הקרבנו' שנברר ועולה מהקרבת הדם ע\"ג המזבח שזהו העלאת נה\"ב בשרשה הראשון בבחי' פני שור<sup data-n=\"4795\">200</sup> שבמרכבה, ומבחי' פני שור עולה למעלה מבריאה לאצי' להיות תוס' אור וחיות חדש בדם הוא הנפש [בבחי' לב ד]אדה\"ע ומנפש עולה ונכלל ברוח דאדה\"ע ומרוח לנשמה שהוא בחי' מוחין חדשים דהוי' דאדם דאצי'<sup data-n=\"4796\">201</sup>. וזהו לריח ניחוח [להוי' כמו וירח ה' את ריח הניחוח<sup data-n=\"4797\">202</sup> ] כו' וחוזר ונמשך ממוחא ללבא ומליבא לכבדא בדם הוא הנפש אור וחיות אלקי חדש להחיות כל העולמות כמשל התפשטו' החיות [מחדש] באדם למטה מרוח בנפש לכל האברים כנ\"ל. וזהו פי' ניחוח לשון נחות<sup data-n=\"4798\">204</sup> דרגא<sup data-n=\"4799\">203</sup> כו', דהיינו בחי' ירידה והמשכה תוס' אור וחיות חדש בשם הוי' בד' אותיות עד ה\"א האחרונה בבי\"ע למלאכים ונשמות עד גם שפע וברכה גשמי' לכל העולם השפל כו' (וכמ\"ש בזהר דמעשן הקרבנות<sup data-n=\"4800\">205</sup> הי' יוצא תמצית השפע האלקי' לע' שרים<sup data-n=\"4801\">206</sup> דנוגה כו'), וכמו\"כ בפנימי' השפע לנשמות בקטרת ע\"ג",[["4790","195","<b>שבחלל זה הריקן מכל דם</b>: ראה הערה 188."],["4791","196","<b>כל הנחלים </b>[ביב: אל מקום שהנחלים]: קהלת א, ז."],["4792","197","<b>הקרבנות. . לריח ניחוח להוי'</b>: ויקרא ד, לא."],["4793","198","<b>והקרבנות נק' לחמי לאשי</b>: פינחס כח, ב. ראה גם לעיל פ' בא צג, ד. וש\"נ."],["4794","199","<b>דג' שליטין אינון לעילא</b>: ראה זהר תרומה קנג, א. (מדהנ\"ע) תולדות קלח, א. ז\"ח רות פ, א."],["4795","200","<b>נה\"ב בשרשה. . פני שור</b>: נסמן לעיל פ' יתרו רסג, ג."],["4796","201","<b>דאצי'</b>: ביא: ליתא."],["4797","202","<b>וירח ה' את ריח הניחוח</b>: נח ח, כא."],["4798","204","<b>נחות דרגא</b>: יבמות סג, א."],["4799","203","<b>ניחוח לשון נחות דרגא</b>: ראה גם לעיל פ' תרומה שה, ד. וש\"נ."],["4800","205","<b>דמעשן הקרבנות</b>: ראה גם לעיל פ' בא קכז, א. וש\"נ."],["4801","206","<b>לע' שרים</b>: ראה זהר בראשית מו, סע\"ב. לעיל לז, ג הערה 52."]]],[2300550415,"המזבח הפנימי שזהו כענין מיכאל מקריב נשמות ע\"ג המזבח<sup data-n=\"4802\">207</sup> לאשתאבא בגופא דמלכא<sup data-n=\"4803\">208</sup> כו' (וכמ\"ש במ\"א). וז\"ש דוד צור לבבי וחלקי אלקים<sup data-n=\"4804\">209</sup> כו', פי' צור לבבי כמו הלב שמשפיע רב שפע חיות חדש תמיד בכל האברים מפני שמקבל מרוח החיים תוס' אור חדש (ע\"י שעולה הנפש ברוח כנ\"ל) שבא ונמשך [מ]תוס' אור חדש שבמוח החכ', [כך] הוא בחי' תוס' אור ההמשכה במוחא עילאה שהוא שם הוי' דאדה\"ע מעצמו' המאציל שהוא למעלה מעלה מבחי' אדם כמ\"ש כי לא אדם הוא<sup data-n=\"4805\">210</sup> [כו'], שנמשך למטה ברוח ונפש ע\"י העלאה דקרבן הבהמה בשרשו בחי' פני שו\"ר כו'. והיינו לפי שיש כח בקרבן דבהמה לגרום תוס' אור חדש במוחין דאדם מלמעלה מבחי' אד\"ם (כמו שיש כח בחיות הקדש לנשאות את הכסא<sup data-n=\"4806\">211</sup> כו' שהוא בחי' אד\"ם שעל<sup data-n=\"4807\">212</sup> הכסא מטעם המבואר במ\"א ששרשם מבחי' ב\"ן שלמעלה<sup data-n=\"4808\">213</sup> ממ\"ה דאדם וע\"כ האדם מקבל חיותו מן החי והצומח כו', וכן מה שיש בכח קרבן הבהמה לכפר על נפש האדם כו'. וכן ראי' מביטושי הגוף בתשו' דסליק נהורא דנשמתא<sup data-n=\"4809\">214</sup> כו' מצד יתרון האור מן החשך<sup data-n=\"4810\">215</sup> דוקא לפי ששרש הבהמה בבחי' ב\"ן<sup data-n=\"4811\">216</sup> דתהו לפני כו'). וזהו שנק' צור לבבי דוקא בחי' מקור האור וחיות דלב האדה\"ע שמאיר לכנ\"י שנק' לב ג\"כ כמ\"ש לך אמר לבי<sup data-n=\"4812\">217</sup> כו' בבחי' תוס' אור [חדש] מלמעלה מבחי' המוחין דשם הוי' דאד\"ם מאחר שנק' רי\"ח ניחו\"ח להוי' דחכ' דתיקון כנ\"ל וד\"ל.\n(ז) <b>וזהו</b> וביום שמחת לבו זה בנין בהמ\"ק דוקא, להיות מבואר למעלה בענין צור לבבי שע\"י הקרבן שנעשה לריח ניחוח להוי' היינו שנמשך תוס' אור במוחין דאדה\"ע מלמעלה מבחי' אדם ועי\"ז ממילא נמשך תוס' אור חדש במדות שבלב שיהפך מדין לחסד ולהיות תוס' אור גם בדם הוא הנפש גם באברים כו'<sup data-n=\"4813\">218</sup>. וזהו שנק' שמחת לבו דייקא כידוע דהשמחה הוא<sup data-n=\"4814\">219</sup> בלב הוא העושה <span data-k=\"pg\">תקטו</span> ּ פתיחת הלב בבחי' תוס' אור וחיות גדול, לפי ששמחה זו עושה תיקון בחיות שבדם שיאיר בו בחי' הפנימי' עד שיצהב[ו] פני[ו] מחמת השמחה שבלב, וצה[י]בת הפנים זה הוא בא מחמת טוב האור וחיות שבדם שמאיר בפנים כמו מבשורה טובה שישמח לבו ביותר יגלה בחי' פנימי' חיות הנפש בדם שבפנימי'<sup data-n=\"4815\">220</sup> שזהו יותר פנימי' מן הארת הפנים שמאיר מאור התענוג שבחכ' שבמוח (כמ\"ש [במ\"א] ע\"פ ויין ישמח לבב אנוש להצהיל פנים משמן<sup data-n=\"4816\">221</sup> כו'). וראי' לזה ממה",[["4802","207","<b>מיכאל מקריב נשמות ע\"ג המזבח</b>: ראה גם לעיל פ' שמות ה, א. וש\"נ."],["4803","208","<b>לאשתאבא בגופא דמלכא</b>: נסמן לעיל פ' יתרו רסט, ד."],["4804","209","<b>צור לבבי וחלקי אלקים</b>: תהלים עג, כו."],["4805","210","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["4806","211","<b>כח בחיות הקדש לנשאות את הכסא</b>: ראה גם לעיל פ' בשלח רמט, ד. מאמרי אדה\"ז תקס\"ט ע' קנג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370320\" data-slug=\"torah-or\" data-id=\"3901370320\">תו\"א יתרו עב, א</a>. מאמרי אדה\"א במדבר ח\"ג ע' תתקיח ואילך. דברים ח\"ד ע' א'רז ואילך. שער האמונה ע, ב. וראה גם לקמן פ' ויקהל שצג, ד."],["4807","212","<b>שעל</b>: שם: שע\"ג."],["4808","213","<b>ששרשם מבחי' ב\"ן שלמעלה</b>: שם: ששרש יש לבחי' ב\"ן למעלה."],["4809","214","<b>מביטושי </b>[שם: מן ביטוש]<b>. . דסליק נהורא דנשמתא</b>: ראה זהר שלח קסח, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ\"ט</a>."],["4810","215","<b>יתרון האור מן החשך</b>: נסמן לעיל פ' יתרו רנא, ד."],["4811","216","<b>ששרש הבהמה בבחי' ב\"ן</b>: ראה גם לעיל פ' משפטים רפא, ד. שיט, ד. וש\"נ."],["4812","217","<b>לכנ\"י שנק' לב. . לך אמר לבי</b>: תהלים כז, ח. ראה זהר (רע\"מ) פינחס רלד, א. מאמרי אדה\"א דברים ח\"ד ע' א'שס. וש\"נ. הנחות תקע\"ז ע' קלג. וש\"נ."],["4813","218","<b>גם באברים כו'</b>: ביא: כו' באברים."],["4814","219","<b>הוא</b>: שם: ליתא."],["4815","220","<b>שבפנימי'</b>: שם: שבפנים."],["4816","221","<b>ויין ישמח. . פנים משמן</b>: תהלים קד, טו. ראה גם מאמרי אדה\"א נ\"ך ע' רפא ואילך (ובהנסמן בריש המאמר שם)."]]],[2300550432,"ש[מ]סיבת השמחה שבלב שנתקן הדם הרי נתקן גם הקלקול שהי' בדם באברים כי נתקן עי\"ז כל הילוך אור וחיות שבדמים בכל האברים ביתר שאת וביתר עז באופן שיוכל לרפאות ולתקן גם את כל ליקותא וריעותא [ש]באברים פנימי' וחיצוני' שאין כח זה כלל באור הארת הפנים שמחמת התענוג שבשכל שבמוח כו' וד\"ל. וא\"כ הרי יובן מזה הנמשל למעלה במ\"ש ביום שמחת לבו זו בנין בהמ\"ק בקטרת וקרבנות לריח ניחוח ששמחה זו למעלה גם ממ\"ת אע\"פ שהי' בהארת פנים מח\"ע<sup data-n=\"4817\">222</sup> ממקורה בפנימי' התענוג העליון, וזהו שמן וקטורת ישמח לב [ה]אדה\"ע שמן למאור להאיר בתוס' אור באור החכ' דתורה הגם שבא מזה ג\"כ שמחה ללב כמו שאדם ישמח בשכל חדש שמחדש במוח חכמתו אבל הקטורת לריח כו' תשמח לבו הרבה יותר מטעם הנ\"ל וד\"ל. והנה עכשיו שאין לנו בהמ\"ק להקריב קרבנות ע\"ג המזבח תקנו תפלות במקום קרבן [התמיד]<sup data-n=\"4818\">223</sup>, תפלה של שחרית במקום קרבן תמיד כו'<sup data-n=\"4819\">224</sup>, והוא מטעם שמקריב האד\"ם שהוא הנשמה את הבהמה שהוא נה\"ב הטבעי' להעלותה למעלה במה שנכללת באש האלקי דהיינו בחי' דביקות והתלהבות הנה\"א<sup data-n=\"4820\">225</sup> בבחי' רשפי אש שלהבת י\"ה<sup data-n=\"4821\">226</sup> דוקא שנק' אש שלמעלה כמו קרבן בהמה הגשמי' שנשרפת באש שלמעלה.\n<b>וביאור</b> הענין הנה זהו כללות ענין התפלה שבמקום קרבן רק שנחלק לד' מדרגות בסדר התפלה שתיקנו אנשי כנה\"ג (שהן ד' תיקוני' דשכינתא מטה ושולחן וכסא ומנורה<sup data-n=\"4822\">227</sup> כמשי\"ת<sup data-n=\"4823\">228</sup>, מטה היינו לפני ב\"ש ושולחן הוא בפסוד\"ז כסא בשתים שלפני' וק\"ש<sup data-n=\"4824\">229</sup> ומנורה בש\"ע), וד' מדרגות הללו מלפני ב\"ש עד ש\"ע, יובן ע\"ד הסדר שא' והנה רוח גדולה<sup data-n=\"4825\">230</sup> כו' לא ברוח ה' ואחרי הרוח רעש<sup data-n=\"4826\">231</sup> לא ברעש ה' ואחר הרעש אש לא באש ה' ואחרי<sup data-n=\"4827\">232</sup> האש קול דממה דקה שהן ד' מדרגות רוח [ו]רעש ואש [ו]קול דממה דקה כו'. וביאור כ\"ז הנה בחי' רוח הוא בפסוד\"ז שמסדר שבחו ש\"מ<sup data-n=\"4828\">233</sup> שמשובח ומפואר בשיר ושבח הנבראי' שנבראו כולם רק מרוח פיו ית' כמ\"ש וברוח פיו כל צבאם<sup data-n=\"4829\">334</sup> שכל צבאות העליוני' מלאכים ועולמות רבים לאין מספר הכל נתהווה מבחי' הבל ורוח אלקי לבד, וע\"כ גם המלאכים נק' בשם רוח כמ\"ש עושה מלאכיו רוחות<sup data-n=\"4830\">235</sup> משרתיו אש כו' שמורכבים מרוח ואש<sup data-n=\"4831\">236</sup> כו'. אך כ\"ז אינו ברוח הוי' רק ברוח אלקי' בלבד שהרי כל עיקר התהוותם מאין ליש אינו רק",[["4817","222","<b>מח\"ע</b>: ביא: דחכ'."],["4818","223","<b>תפלות במקום קרבן [התמיד]</b>: ברכות כו, ב."],["4819","224","<b>כו'</b>: ב: של שחרית. יא: ש\"ש."],["4820","225","<b>הנה\"א</b>: שם: הנשמ' האלקי'."],["4821","226","<b>רשפי אש שלהבת י\"ה</b>: שה\"ש ח, ו."],["4822","227","<b>מטה ושלחן וכסא ומנורה</b>: ראה זהר תרומה קלג, א. לעיל פ' וארא עד, ב. וש\"נ."],["4823","228","<b>כמשי\"ת</b>: ביא: כמ\"ש בזוהר."],["4824","229","<b>שלפני' וק\"ש</b>: שם: שלפני ק\"ש."],["4825","230","<b>והנה רוח גדולה</b>: מל\"א יט, יא [ושם: והנה ה' עובר ורוח גדולה]."],["4826","231","<b>ואחרי הרוח רעש</b>: מל\"א שם [ושם: ואחר — ראה גם מאמרי אדה\"א קונטרסים ע' שה. וש\"נ]."],["4827","232","<b>ואחר הרעש אש. . ואחרי</b>: מל\"א שם, יב [ושם: ואחר — ראה גם לעיל פ' בא קכב, ד. וש\"נ]."],["4828","233","<b>בפסוד\"ז שמסדר שבחו ש\"מ</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר סנ\"א, ס\"א."],["4829","334","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["4830","235","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד."],["4831","236","<b>שמורכבים מרוח ואש</b>: ראה מאמרי אדה\"א בראשית ע' קיב. וש\"נ. קונטרסים ע' רצב. וש\"נ."]]],[2300550448,"ע\"י הצמצום דשם אלקי'<sup data-n=\"4832\">237</sup> דוקא, והיינו בחי' ה\"א אחרונה דשם הוי' שבה\"א בראם<sup data-n=\"4833\">238</sup> כידוע [ונק'] אתא קלילא דלית בי' מששא<sup data-n=\"4834\">239</sup> שאין הה\"א נרגש במבטא כלל להיותו רק <span data-k=\"pg\">1032</span> ּ הבל חיצוני שז\"ש וברוח פיו כו', וע\"כ גם העבודה דמלאכים היינו [ב]בחי' רוח שאומרים שירה בהתכללו' וביטול דרוח שה[וא] התעוררות קול ורוח, ואמנם אינו נק' רוח הוי' רק רוח אלקי' כמו ברן יחד כו' ויריעו כל בני האלקי'<sup data-n=\"4835\">240</sup> וכן כל המלאכים דעשי' שנזכר בפסוד\"ז. וכך גם עבודת האדם בפסוד\"ז בהתבוננו' בביטול כל צבא השמים כמו הללו את ה' מן השמים<sup data-n=\"4836\">241</sup> וכה\"ג זהו התפעלות הנפש בבחי' רוח שלא ברוח הוי' שלא נמשך בזה מרוח דהוי' כנ\"ל וזהו מדרגה הא' וד\"ל.\n<b>ומדרגה</b> הב' הוא מ\"ש ואחר<sup data-n=\"4837\">242</sup> הרוח רעש לא ברעש ה' כו' [ו]זהו בברכת יוצר שאומרים איך [ש]המלאכים דיצי' מקדישים וממליכים את שם המלך כו' וכולם מקבלים עליהם עומ\"ש כו' עד והאופנים ברעש גדול<sup data-n=\"4838\">243</sup> כו', דהנה מה שהשרפים אומרים קדוש<sup data-n=\"4839\">244</sup> והאופנים ברעש גדול [כו'] אומרים ברוך הכל [הוא] בא מצד הפלאת ההשגה שלמעלה מכלי השגתם [המצומצם] מאור ה' שמלובש בתוכם, וע\"כ אומרים קדוש בוי\"ו שהוא וי\"ו דשם הוי' שלמעלה [מ]צמצום ההמשכה דאלקי' הנמשך מה' תתאה הנ\"ל שאינו בגדר ממכ\"ע כו' ומחמת שאינו נתפס בכלי מוחם וקדוש ומופלא מהם לזה או' קדוש אי' מקום כבודו כו', וזהו ג\"כ סיבת התפעלות דאופנים ברעש גדול ואו' ברוך שיומשך [מ]כבוד הוי' ממקומו למטה (אלא שהשרפי' או' קדוש כמו שהוא למעלה ואופני' מתפעלים ברעש יותר מפני שאין משיגים כלל בוי\"ו דקדוש שמאיר בבחי' מקיף עליהם וגם בשרפי' שאו' קדוש וי\"ו זה דשם הוי' לא נמשך רק אפס קצהו בצמצום גדול [כו')]. ו[מ]ובן מזה עכ\"פ שמבחי' ה\"א המצומצם בתוכם ממש לא הי' התפעלות הרעש באופנים ולא היו השרפי' או' קדוש מאחר שמושג ומתיישב בכלי השגתם, אך מבחי' וי\"ו דשם הוי' שקדוש ומובדל מן העולמות להיות למעלה מה\"א האחרונה המלובש בתוכם ממש וזה יבא סיבת התפעלות ברעש גדול כו'. וז\"ש ואחרי הרוח (דמלאכים דעשי' דכתי' עושה מלאכיו רוחות כנ\"ל) רעש דאופנים וחיות דיצי'<sup data-n=\"4840\">245</sup> ואמנם אין זה ברעש הוי' לפי שאין כל שם הוי' נמשך בזה רק הוי\"ו וה\"א וגם [זה] הוי\"ו אינו מאיר רק בבחי' מקיף עליהם מקדש הוי'<sup data-n=\"4841\">246</sup> כנ\"ל וד\"ל.",[["4832","237","<b>התהוותם. . דשם אלקי'</b>: ראה אגה\"ת פ\"ד. לעיל פ' וארא עט, א. וש\"נ."],["4833","238","<b>שבה\"א בראם</b>: ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["4834","239","<b>שבה\"א. . אתא קלילא דלית בי' מששא</b>: ראה פיוט אקדמות. מאמרי אדה\"א דברים ח\"ג ע' תתק. וש\"נ. תו\"ח ח\"ש קכא, ג ובהערה 48."],["4835","240","<b>ברן יחד. . בני האלקי'</b>: איוב לח, ז."],["4836","241","<b>הללו את ה' מן השמים</b>: תהלים קמח, א."],["4837","242","<b>ואחר</b>: ביא: ואחרי — ראה לעיל הערה 231."],["4838","243","<b>גדול</b>: שם: ליתא."],["4839","244","<b>שהשרפים אומרים קדוש</b>: ראה חולין צב, רע\"א ובתוד\"ה ברוך."],["4840","245","<b>דאופני'. . דיצי'</b>: ראה גם לעיל פ' בא צז, ג. וש\"נ."],["4841","246","<b>הוי'</b>: ביא: העליון."]]],[2300550463,"<b>והמדרגה</b> הג' הוא מ\"ש ואחר הרעש אש לא באש הוי' וזהו [ב]ברכה שני' דאה\"ע אהבתנו דקאי בנשמות דוקא שהתפעלותם ברשפי אש שלהבת י\"ה [דוקא] כמו צמאה לך נפשי<sup data-n=\"4842\">247</sup> [כו'] כלתה נפשי<sup data-n=\"4843\">248</sup> כו', להיות שרש הנשמה מבחי' בינה<sup data-n=\"4844\">249</sup> כמ\"ש ונשמת שדי תבינם<sup data-n=\"4845\">250</sup> והוא בחי' אימא עילאה<sup data-n=\"4846\">251</sup> שנק' אם הבנים<sup data-n=\"4847\">252</sup> דמקננא בכורסייא<sup data-n=\"4848\">253</sup> בבריאה שלמעלה מיצי' כו'. והענין הוא כידוע דעיקר [התפעלות] התשוקה בצמאון רשפי אש האלקי יבא מצד פנימי' ההשגה בשם הוי' דוקא משום דבינה ליבא<sup data-n=\"4849\">254</sup> ובה הלב מבין כו' שלמעלה מהתפעלות השרפי' באמרם קדוש, להיות שנשמות דבריאה משיגי' בפנימי' דשם הוי' והוא בה\"א עילאה שלמעלה מוי\"ו שהוי\"ו הוא התפעלו' המדות מן ההשגה השכלי' שזהו התפעלו' השרפי'<sup data-n=\"4850\">255</sup>, אבל התפעלות השכל וההשגה עצמ[ה] שנמשך ללב זהו שלהבת י\"ה דחו\"ב שבלב שמזה בא [ה]אהבה דבכל נפשך ומאדך ביחו\"ע דק\"ש לנשמות דוקא באמרו שמע ישראל כו' וד\"ל.\n<span data-k=\"pg\">תקטז</span> ּ<b>(ח</b> ) וזהו ואחר הרעש אש אחר הרעש דמלאכים אש דנשמות ([ו]כמ\"ש הנביא ואשמע אחרי דוקא קול רעש גדול<sup data-n=\"4851\">256</sup> כו') שהוא אש העליון שנק' אש שלמעלה שבק\"ש אחר הרעש דמלאכים שבברכת יוצר, ואמנם עכ\"ז לא באש הוי' שאינו אש הוי' דחסדים דאבא שהוא היו\"ד דשם הוי' שנק' אש לבנה אלא אש אלקי' דבינ\"ה שבהשגה כמ\"ש שמע ישראל<sup data-n=\"4852\">257</sup> דשמיעה בבינה<sup data-n=\"4853\">258</sup> לבד, ועיקר שם הוי' הוא היו\"ד דוקא שהוא [בחי'] ביטול במציאות כנקודה בהעדר התפשטו' לגמרי וההתלהבות בהשגה אלקי' הנ\"ל שנמשך בבינה הוא בבחי' יש מורגש. וידוע דיש דבינה נכלל באין דחכ' לפי שהה'['א] דבינה נמשך מיו\"ד כמו שמן המעיין הנובע נמשך הנהר שזהו ההמשכה מאין דחכ' ליש דבינה כו', ואע\"פ שממילא אחר ההתלהבות ודביקות ברשפי אש האלקי דבינה יבא [ל]כלל בחי' ביטול במציאות דחכ' כמו אחרי הרצוא שוב כו' כידוע, ונכלל ונתבטל כל התפעלות ההשגה המורגש ובא לכלל אין דביטול דחכ' שזהו עיקר ענין המס\"נ בא[חד] שהוא יו\"ד כו', עכ\"ז לא נק' אש הוי' לפי שעכ\"ז<sup data-n=\"4854\">259</sup> רק בחי' ההעלאות מלמטה למעלה מי\"ש לאי\"ן דיו\"ד דחכ', אבל הרי לא נמשך שם הוי' מלמעלה למטה כמו שהוא היו\"ד עצמו שבו התגלות אוא\"ס עצמו, כידוע דעיקר בחי' גילוי דאוא\"ס עצמו אינו אלא בנקודה דיו\"ד שנק' כ\"ח מ\"ה כו'",[["4842","247","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["4843","248","<b>כלתה נפשי</b>: שם פד, ג."],["4844","249","<b>שרש הנשמה מבחי' </b>[ביא: בבחי']<b> בינה</b>: ראה גם מאמרי אדה\"א במדבר ח\"ג ע' תתקנט. דברים ח\"ב ע' תכח. וש\"נ. ח\"ד ע' א'קסו. שמות ח\"ב ע' תלה. וש\"נ."],["4845","250","<b>ונשמת שדי תבינם</b>: איוב לב, ח. ביא: נשמת — נסמן לעיל עט, ב."],["4846","251","<b>בינה. . אימא עילאה</b>: ראה ע\"ח (שער או\"א) שי\"ד, פ\"ח. לעיל פ' בשלח רמח, רע\"ד בשם הזהר."],["4847","252","<b>בינה. . אם הבנים</b>: נסמן לעיל פ' משפטים רצו, ב."],["4848","253","<b>אימא. . דמקננא בכורסייא</b>: נסמן לעיל פ' יתרו רעא, ד."],["4849","254","<b>דבינה ליבא</b>: ת\"ז בהקדמה (יז, א)."],["4850","255","<b>באמרם. . השרפי'</b>: יא: ליתא. וכנראה נשמט מפני תיבות הדומו': השרפי'. . השרפי'."],["4851","256","<b>ואשמע אחרי. . קול רעש גדול</b>: יחזקאל ג, יב."],["4852","257","<b>שמע ישראל</b>: ואתחנן ו, ד."],["4853","258","<b>דשמיעה בבינה</b>: ראה זהר (אד\"ר) נשא קלח, ב. הנסמן לעיל פ' שמות כז, ג."],["4854","259","<b>שעכ\"ז</b>: ביא: שאין כ\"ז."]]],[2300550478,"(והוא אש הוי' שירד על הר סיני בחכ' שבתורה כמשי\"ת). וזהו שא' ואחרי האש קול דממה דקה דתמן קאתי מלכא<sup data-n=\"4855\">260</sup> שהוא בחי' עצמות אוא\"ס שמתגלה ביו\"ד דחכ' שהוא בחי' ביטול במציאות בתכלית ע\"כ נק' קול דממ\"ה דק\"ה בחי' קלא פנימאה כו', וזהו בצלותא שבלחש כמ\"ש בחנה וקולה לא ישמע<sup data-n=\"4856\">261</sup> מחמת עוצם הביטול במציאות כו' כמו בבואו קרוב לפני המלך ידבר בחשאי כידוע וד\"ל.\n<b>ואמנם</b> הנה עיקר ענין מדריגה זו דקול דממה דקה שהוא בעיקר דשם הוי' שהוא היו\"ד זהו בבחי' קול דתורה דוקא דאורייתא מח\"ע נפקת, והוא ע\"י מצות הקריאה בדברו<sup data-n=\"4857\">263</sup> בד\"ת<sup data-n=\"4858\">262</sup> כמ\"ש ודברת בם<sup data-n=\"4859\">264</sup> כו' שהוא דבר ה' ממש כמ\"ש ואשים דברי בפיך<sup data-n=\"4860\">265</sup> כו' שזהו כמו קול דבר ה' ביו\"ד הדברות, הגם שמשה ידבר אבל האלקי' יעננו בקול שהוא בקולו של משה שזהו שנק' קול דממה דקה דתמן קאתי מלכא שבו מתגלה מבחי' עצמות אוא\"ס ממש, לפי ששרש התו' בחכ' העצמי' דא\"ס כמ\"ש ואהי' אצלו כו' אצלו ממש<sup data-n=\"4861\">266</sup> שבה שורה פנימי' ועצמות דשעשועי המלך<sup data-n=\"4862\">267</sup> בעצמו<sup data-n=\"4863\">268</sup> כו', וז\"ש והחכ' מאין תמצא חכ' דתורה שמאין האמיתי תמצא כו'. וע\"כ בקול דתורה שהוא המשכת החכ' העצמי' דא\"ס המדברת בפיו ואין זה דיבור עצמו כלל כמו תען לשונ\"י אמרתיך<sup data-n=\"4864\">269</sup> כעונה אחר הקורא (כמו [שא'] בב\"ש וב\"ה אלו ואלו דא\"ח<sup data-n=\"4865\">270</sup> כו' [ש]דבר ה' מדבר בם ולא שהן המדברים [מ]עצמם כו') בזה נמשך עיקר שם הוי' גם קש\"י [היא] מבחי' מקור החכ' כמו שה[י]א בבחי' אין האמיתי ממש כנ\"ל. וזהו קול דממה דק\"ה כו' בבחי' ביטול במציאות [ממש] להיות כמו הדומם (וכמ\"ש מה להלן באימה<sup data-n=\"4866\">271</sup> כו') ממש ע\"כ נק' דממ\"ה דקה<sup data-n=\"4867\">272</sup> וגם לשון שתיקה כי אינו רק כלי לדבר ה' כו', וזהו בחי' משה שהי' בבחי' פנימי' דכ\"ח <span data-k=\"pg\">1034</span> ּ מ\"ה דחכ' (והוא שנק' קולו של משה שלמעלה מקול צלותא שבלחש כמ\"ש השמיעני את קולך<sup data-n=\"4868\">273</sup> דא קלא דאורייתא כו' והוא שנק' אש הוי' כמו קול ה' חוצב<sup data-n=\"4869\">274</sup> כו' שהתו' ניתנה באש [כמ\"ש] וההר עשן<sup data-n=\"4870\">275</sup> כו' ונק' אש לבנה ע\"ג אש שחורה<sup data-n=\"4871\">276</sup> (וז\"ש על ב\"ע כשהי' שונה הי' אש מתלהטת סביביו<sup data-n=\"4872\">277</sup> שהוא אש דתורה כו', וכן זהו הטעם שא' ביונתן בן עוזיאל כשהי' לומד כל עוף הפורח עליו נשרף<sup data-n=\"4873\">278</sup> שהוא עוף דמלאך שנק' אש אלקי' שנכלל ונתבטל באש הוי' דתורה כו') (ובאמת בחי' קול דממה דק\"ה ה[ו]א בפנימי' הכת\"ר",[["4855","260","<b>דתמן קאתי מלכא</b>: ראה זהר (רע\"מ) פינחס רכג, ב. ת\"ז בהקדמה (ג, ב)."],["4856","261","<b>וקולה לא ישמע</b>: שמו\"א א, יג."],["4857","263","<b>בדברו</b>: ביא: ליתא."],["4858","262","<b>מצות הקריאה. . בד\"ת</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. לעיל פ' וארא פ, ג. וש\"נ."],["4859","264","<b>ודברת בם</b>: ואתחנן ו, ז."],["4860","265","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["4861","266","<b>כו' אצלו ממש</b>: ביא: ממש כו'."],["4862","267","<b>דשעשועי המלך</b>: נסמן לעיל פ' תרומה שיח, ב."],["4863","268","<b>בעצמו</b>: ביא: ליתא."],["4864","269","<b>תען לשונ\"י אמרתיך</b>: תהלים קיט, קעב."],["4865","270","<b>אלו ואלו דא\"ח</b>: ערובין יג, ב."],["4866","271","<b>מה להלן באימה</b>: ברכות כב, א."],["4867","272","<b>דקה</b>: ביא: ליתא."],["4868","273","<b>השמיעני את קולך</b>: נסמן לעיל שטז, ג."],["4869","274","<b>קול ה' חוצב</b>: תהלים כט, ז."],["4870","275","<b>וההר </b>[ביא: וה\"ס]<b> עשן [ב ניתוסף</b>: כולו]: יתרו יט, יח. ראה גם לעיל פ' בשלח רלח, ב ובהערה 1027."],["4871","276","<b>אש לבנה ע\"ג אש שחורה</b>: ראה רש\"י שה\"ש ה, טז [ד\"ה שחורות]. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקעח."],["4872","277","<b>ב\"ע. . אש מתלהטת סביביו</b>: ויק\"ר פט\"ז, ד. ראה גם לקמן פ' ויקהל תי, ד."],["4873","278","<b>ביונתן. . כל עוף הפורח עליו נשרף</b>: סוכה כח, א. ראה גם לעיל רלט, ג. וש\"נ."]]],[2300550493,"דקש\"י שלמעלה גם מאש יו\"ד דחכ' (וכפשט<sup data-n=\"4874\">279</sup> הכתוב דיעננו בקול קאי על קול השופר<sup data-n=\"4875\">280</sup> שהי' חזק בקול רם וכמו לע\"ל שנק' קול גדול<sup data-n=\"4876\">281</sup> כו').\n<b>אך</b> הנה מי הוא הגורם להיות המשכת גילוי עצמות אוא\"ס בשם הוי' בחכ' שבתורה בקול תורה שהוא בחי' קול דממה דק\"ה כנ\"ל גם למטה [מטה] בכל מי שיושב ושונה וקורא<sup data-n=\"4877\">282</sup> כו' ([ש]זהו בחי' או\"מ<sup data-n=\"4878\">283</sup> דמשפיע מלמעלה למטה), הנה זהו ע\"י העלאה דקול התפלה בכוונה שבלב לעומק[ו] בנקוד' הרצון הפנימי בלב נשבר ונדכה כו' והוא מ\"ש דסנד\"ל יושב וקושר כתרים<sup data-n=\"4879\">284</sup> לקונו מתפלות של ישראל<sup data-n=\"4880\">285</sup> דוקא. והענין הוא כידוע ומבואר במ\"א ע\"פ צאינה וראינה כו' בעטרה שעטרה לו אמו<sup data-n=\"4881\">286</sup> ביום חתונתו כו' שהן ב' מיני עטרות, א' עטרה (מאמו הוא תושבע\"פ) מאבנים טובות המאירים בעצם הווייתם והן אותיות דתושב\"כ שנק' כת\"ר תורה, ועטרה שעטרה לו אמו מתושבע\"פ שנק' תור\"ת אמ\"ך<sup data-n=\"4882\">287</sup> שהן כמו אבנים טובות שנזדככו וכמו אבני החושן כנ\"ל כמו<sup data-n=\"4883\">288</sup> הבירורי' דמעשה המצות בדברים גשמי' דק\"נ שנק' מע\"ט, וכן התשובה מעומקא דלבא שנהפך גם הרע לטוב כמו שנזדככו כל הפסולת שנק' טהרה שבאה מן הטומאה שנק' בר לבב<sup data-n=\"4884\">289</sup> כו' כנ\"ל שזהו כאבן ספי\"ר שמבריק בעין (וז\"ש ותחת רגליו בחי' תשובה ומע\"ט כלבנת הספי\"ר כנ\"ל), [ו]זהו ג\"כ ענין התפלה (כמשי\"ת) (ויש בחי' ממוצע מאו\"י ואו\"ח והוא כמו הכדכ\"ד שא' להוי כדין וכדין<sup data-n=\"4885\">290</sup> כו' וע\"ז רמזו ב\"פ<sup data-n=\"4886\">291</sup> ע\"פ קדושים תהיו<sup data-n=\"4887\">292</sup> כו' משל למלך כו' ג' עטרות<sup data-n=\"4888\">293</sup> שתים נתן לבניו שהן תו\"מ וא' נטל לעצמו כו' שהן ב' כתרים דנעשה ונשמע<sup data-n=\"4889\">294</sup> כל[ו]לי' שנתן לבניו וכאשר<sup data-n=\"4890\">295</sup> מאו\"י ואו\"ח יחד שז\"ש בעטרה שעטרה לו אמו כו' זהו עטרה שנטל לעצמו כו'), וזהו בעטרה שעטרה לו אמו למלך שלמה שהוא כלול מב' מדרגות דתורה ותפלה. והנה עיקר יופי הדרת מלך בעטרה של מלך הוא באבנים טובות המאירים ע\"י הזדככות כשהוא מתנוצץ בגוונים שונים בהארה והבהקה יתירה מפני שזיככו בתכלית גם שהוא אבן פשוט בחי' דומם גשמי זהו יותר יקר ות\"ת<sup data-n=\"4891\">296</sup> ונק' עטרת תפארת בבחי' כתר ועטרה ע\"ג הראש שנק' כתר מל'.\n<b>וכך</b> יובן בתפלות ישראל שעושה המלאך מהם כתרים לקונו בראשו לפי שאותיות דיבור התפלה עצמו הרי הן [ב]בחי'",[["4874","279","<b>(וכפשט</b>: ביא: וכפשט."],["4875","280","<b>דיעננו בקול. . קול השופר</b>: ראה אור החיים עה\"פ (יתרו יט, יט)."],["4876","281","<b>לע\"ל שנק' קול גדול</b>: ראה גם סידור דרושים לחתונה קלב, ב."],["4877","282","<b>בכל מי שיושב ושונה וקורא</b>: ראה תדא\"ר רפי\"ח. לעיל פ' וארא נח, ג הערה 18."],["4878","283","<b>או\"מ</b>: ביא: או\"י."],["4879","284","<b>דסנד\"ל יושב וקושר כתרים</b>: ראה זהר וישלח קסז, ב. סה\"מ ה'תש\"ח ע' 202 בהערה. מאמרי אדה\"א נ\"ך ע' שיג. וש\"נ."],["4880","285","<b>מתפלות של </b>[ביא: ליתא]<b> ישראל</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' מד ואילך. ע' נ. הנחות הר\"פ ע' מז. הנסמן במ\"מ <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380047\" data-slug=\"likkutei-torah\" data-id=\"4001380047\">לקו\"ת בשלח ב, ב</a>."],["4881","286","<b>צאינה. . בעטרה שעטרה לו אמו</b>: שה\"ש ג, יא."],["4882","287","<b>תור\"ת אמ\"ך</b>: משלי א, ח."],["4883","288","<b>כמו</b>: ב: שהן כמו. יא: שהן בחי'."],["4884","289","<b>בר לבב</b>: תהלים כד, ד."],["4885","290","<b>הכדכ\"ד שא' להוי כדין וכדין</b>: ישעי' נד, יב. ב\"ב עה, א."],["4886","291","<b>ב\"פ</b>: ביא: במ\"ש."],["4887","292","<b>קדושים תהיו</b>: קדושים יט, ב."],["4888","293","<b>משל למלך כו' </b>[ביא: שעשה]<b> ג' עטרות</b>: ראה ויק\"ר פכ\"ד, ח. לקמן פ' פקודי תנו, ב. מאמרי אדה\"א הנחות תקע\"ז ע' עה. וש\"נ."],["4889","294","<b>ב' כתרים דנעשה ונשמע</b>: שבת פח, א."],["4890","295","<b>כל[ו]לי' שנתן לבניו וכאשר</b>: ביא: שנתן לבניו כל[ו]לי'."],["4891","296","<b>ות\"ת</b>: ביא: ותפארת."]]],[2300550507,"דומם פשוט שהן קול בלא חיות כלל, אך כאשר הדברים יוצאים מקירות הלב בכוונה גדולה ברעותא דלבא<sup data-n=\"4892\">297</sup> בכל נקודות פנימי' הרצון הרי מאיר בכל אות ואות מפנימי' אור הרצון ההוא שבפנימי' הלב והמוח [ו]ה\"ז כמו אבן טוב הגשמי שזיוו יבהיק ביותר מצד הזדככות [כו']. וזהו שהמלאך סנד\"ל (שהוא ביצי'<sup data-n=\"4893\">298</sup> עולם הדיבור<sup data-n=\"4894\">299</sup> ) מעלה <span data-k=\"pg\">תקיז</span> ּ כל התפלות שיוצאים מקירות הלב כל א' ועושה מכל הצירופי' שלהם כתרים לקונו לעשות מהם עטר\"ה וכת\"ר בראשו של הקב\"ה, פי' עושה<sup data-n=\"4895\">300</sup> עטרה וכת\"ר היינו כמ\"ש כצנה רצון תעטרנו<sup data-n=\"4896\">301</sup> שהוא בחי' אור רצה\"ע שמאיר ונמשך ע\"ג הראש בבחי' עטרה מקיף<sup data-n=\"4897\">302</sup> דאו\"י, לפי שהעלאה זו דרצון הפנימי' שעולה מלמטה נעשה עטרה בבחי' או\"ח כאבן טוב המתנוצץ ומעורר מלמעלה המשכת רצה\"ע ג\"כ בבחי' או\"י כאבן השהם כנ\"ל. וכמו שמבקשים יהי רצון מלפניך<sup data-n=\"4898\">303</sup> כו', פי' יהי רצון ממקור כל הרצונות [העליוני'] שנק' רעדכ\"ר<sup data-n=\"4899\">304</sup> כו', יורד אור הרצה\"ע הזה מלמעלמ\"ט בכל ההשתל' בכל עולם ועולם עד שיורד ומתלבש גם למטה מטה [ממש] בעולם העשי' הגשמי' להיות רצון ה' לרפא חולים ולברך השנים בפרנסה באו' ברוך אתה ה' כו' מברך השנים וכה\"ג כל ח\"י ברכאן דצלותא<sup data-n=\"4900\">305</sup> שזהו ההמשכה מרצה\"ע שנמשך בשם<sup data-n=\"4901\">306</sup> הוי' באבי\"ע, וזהו בא\"י רופא כו' כידוע בפי' אתה ה' לנוכח שהוא שאו' יה\"ר כו' דהיינו מלפניך ממש שיורד אור הרצה\"ע עד למטה בפו\"מ לרפאות חולים או לברך השנים, [אך] אין רצה\"ע בא מלמעלה רק ע\"י התעוררו' רצון דכנ\"י [מלמטה] למעלה שעולה עם אותיות התפלה בנקודת הלב כנ\"ל שנעשה מזה עטרה [וכתר] בראש וכמ\"ש<sup data-n=\"4902\">307</sup> דרוח אייתי רוח<sup data-n=\"4903\">308</sup> כו', וע\"י מלאך זה שקושר הכת\"ר לקונו מתפלה זו העולה ע\"י ג\"כ [נמשך ג\"כ אור] הרצה\"ע מלמעלה למטה מחסד עליון לשמוע תפלת כל פה בחסד וברחמים להיות מתקיימת הבקשה בפו\"מ דוקא ונמצא עטרה דתפלה כלול מעלי' וירידה או\"ח [ו]או\"י כו' וד\"ל. אך הנה הגם שנמשך אור הרצה\"ע בבחי' כתר לכל העולמות עד עוה\"ז השפל להשפיע פרנסה וחיים גשמי' זה אינו אלא חיי שעה ואין לו ערך לגבי בחי' המשכת אור דתורה שהוא נק' חיי עולם<sup data-n=\"4904\">309</sup> כו', כי בחי' רצה\"ע וח\"ע שבתומ\"צ הוא בחי' [ה]פנימי' ועצמות דאוא\"ס ומה שנמשך רחמים וחסד עליון מרצה\"ע להמשכת חסד בעולם העשי' זהו רק בחי' חיצוני' אפי' הרצון וחכ' למע\"ב בעש\"מ כידוע וע\"כ אמר למי שהאריך בתפלה ביותר שמניח חיי",[["4892","297","<b>ברעותא דלבא</b>: זהר וירא ק, א."],["4893","298","<b>שהמלאך סנד\"ל. . ביצי'</b>: ראה גם ע\"ח (שער סדר אבי\"ע) שמ\"ז, פ\"ו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670193\" data-slug=\"torat-chaim\" data-id=\"2300670193\">תו\"ח וירא צט, ג</a> ובהערה 20. שעה\"י קמה, ב."],["4894","299","<b>ביצי' עולם הדיבור</b>: ראה בהנסמן לעיל פ' בשלח קמד, ב."],["4895","300","<b>פי' עושה</b>: ביא: ופי'."],["4896","301","<b>כצנה רצון תעטרנו</b>: תהלים ה, יג."],["4897","302","<b>עטרה מקיף</b>: ביא: מקיף בבחי' עטרה."],["4898","303","<b>יהי רצון מלפניך</b>: בברכות השחר. ועוד."],["4899","304","<b>רעדכ\"ר</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670202\" data-slug=\"torat-chaim\" data-id=\"2300670202\">תו\"ח בראשית לו, ג</a> הערה 23."],["4900","305","<b>ח\"י ברכאן דצלותא</b>: זהר בראשית כו, א."],["4901","306","<b>בשם</b>: ביא: משם."],["4902","307","<b>וכמ\"ש</b>: שם: כו'."],["4903","308","<b>דרוח אייתי רוח</b>: נסמן לעיל פ' יתרו רנא, א."],["4904","309","<b>חיי שעה. . חיי עולם</b>: נסמן בהערה הבאה."]]],[2300550521,"עולם דתורה ועוסק בחיי שעה<sup data-n=\"4905\">310</sup> כו'. אך הנה עכ\"ז הרי אמר דהאומר אין לי אלא תורה<sup data-n=\"4906\">311</sup> בלא תפלה<sup data-n=\"4907\">312</sup> אפי' תורה אין לו דהיינו תורה בלא תפלה להיות שבחי' העלאה דאו\"ח בתפלה בהתפעלו' בנקודת הרצון הפנימי באותיות התפלה שמקר[י]ב ומעלה לנה\"ב להעלות לה' כקרבן ממש, והן ד' מדרגות דתפלה ברוח ורעש ואש דאלקי' עד ש\"ע בלחש כנ\"ל הוא הגורם להיות המשכת אור דתורה בבחי' קול דממה דקה הנ\"ל, שזהו בחי' גילוי אוא\"ס בתורה (שהן [אותיות] עצמי' דאו\"י שהוא התענוג שבח\"ע דתורה שהאיר במ\"ת). וזהו בעטרה שעטרה לו אמו [ביום חתונתו וביום שמחת לבו דמשמע דמ\"ש בעטרה כו' קאי על שניהם ביום חתונתו וגם ביום שמחת לבו שזהו בביהמ\"ק, והענין הוא דבמ\"ת היו ב' מיני עטרה שעטרה לו אמו] מבחי' או\"י ואו\"ח נגד ב' כתרים דנעשה ונשמע כנ\"ל הכל בבחי' אור דתורה [שהוא בא מן המשפיע אל המקבל כמ\"ש כחתן יכהן פאר כו' (והוא בחי' המשכת בחי' המאו\"ר לאור ואז יוכל להיות ההעלאה וביטול האור דנש\"י במאור ע\"י אהרן כנ\"ל). ואמנם ב' מיני עטרות הללו הי' גם ביום שמחת לבו בבנין בהמ\"ק והן הקרבנו' שישמח לב מלמטה למעלה יותר משמן למאור ואור כנ\"ל, ועכשיו התפלות במקום קרבן<sup data-n=\"4908\">313</sup> להעלות לנה\"ב בהזדככות החומר בתשו' ותפלה כנ\"ל אז התפלה קודם לתו' שע\"י התפלה בבחי' או\"ח למעלה נמשך או\"י דתו' כמו שא' אם רץ לבך שו\"ב<sup data-n=\"4909\">314</sup> שמלמטה למעלה רצוא קודם לשוב כו'. וזהו שקושר כתרי' לקונו מתפלות ישראל עי\"ז נמשך ג\"כ אור דתו'] ולא בתורה לבד וכאבא בנימין שהי' תפלתו סמוך למטתו<sup data-n=\"4910\">315</sup> כו'. ואע\"פ שרצה\"ע דתפלה הוא חיי שעה גורם ירידת אור פנימי' רצה\"ע דתורה שנק' חיי עולם מצד בחי' העלאה דעומ\"ת שממשיך מעומ\"ר כו'. וראי' לזה שהרי יש מעלה גבוה בתפלה מה שאין זה בתורה במה שמבקשים בש\"ע <span data-k=\"pg\">1036</span> ּ סלח לנו כו' רפאנו ברך עלינו וגואל ישראל<sup data-n=\"4911\">316</sup> [גם] שאינו כפי משפט התורה רק מצד ר\"ר דרעדכ\"ר שלמעלה ממשפט התו', א\"כ הרי [יש] מקום<sup data-n=\"4912\">317</sup> לרצון זה בר\"ר העליוני' שאו' יה\"ר מלפניך למעלה גם מרצה\"ע שבתו\"מ למחול ולסלוח לעוברי רצונו העליון שבתו\"מ ולברך השנים בפרנסה או גאולה ורפואה גם שהוא נגד משפט התו' וד\"ל.\n(ט) <b>וזהו</b> כללות ענין הפ' הזאת במה שמתחיל במצות שמן למאור להעלות נר תמיד ואח\"כ בבגדי אהרן ובניו",[["4905","310","<b>שמניח חיי עולם. . בחיי שעה</b>: שבת י, א."],["4906","311","<b>דהאומר אין לי אלא תורה</b>: ראה גם לעיל פ' משפטים רפו, ב. וש\"נ."],["4907","312","<b>בלא תפלה</b>: ביא: ליתא. וראה בסמוך בפנים."],["4908","313","<b>התפלות במקום קרבן</b>: נסמן לעיל פ' יתרו רסח, ב."],["4909","314","<b>אם רץ לבך שו\"ב</b>: ס\"י פ\"א, מ\"ח. לעיל פ' בשלח קסד, ג הערה 22."],["4910","315","<b>וכאבא בנימין. . סמוך למטתו</b>: ראה ברכות ה, ב. מאמרי אדה\"א שמות ח\"א ע' קפד. וש\"נ. ח\"ב ע' תקעא ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670447\" data-slug=\"torat-chaim\" data-id=\"2300670447\">תו\"ח נח נד, ב</a>."],["4911","316","<b>סלח לנו. . וגואל ישראל</b>: ב: רפאנו סלח לנו ברך עלינו וגואל ישראל. ו: סלח לנו ברך עלינו רפאנו וגואל ישראל."],["4912","317","<b>מקום</b>: יא: מקור."]]],[2300550534,"בבחי' מקיפים דלבושים ואח\"כ במצות חושן ואפוד, בהיות מבואר למעלה בענין בעטרה כו' שיש בזה ב' מדרגות, הא' ביום חתונתו במ\"ת שבאור פניו האיר לנש\"י בבחי' מאור ואור, וכך הי' ענין שמן למאו\"ר שיהי' המשכות מאו\"ר דאור דתורה לדורות בכ\"מ<sup data-n=\"4913\">318</sup> שיושב וקורא ושונה ע\"י משה שוש' דמלכא כנ\"ל, ואח\"כ יכול להיות ביטול האור במאור כנר בפני האבוקה, וזהו כדי להעלות נר דנש\"י תמיד במצות ת\"ת כנ\"ל ובק\"ש שחרית וערבית כנ\"ל. והב' ביום שמחת לבו בקרבנות בבהמ\"ק ועכשיו הן התפלות שזהו התלבשות נר ה' נה\"א<sup data-n=\"4914\">319</sup> בנה\"ב להעלות[ה] כקרבן בהמה ממש. וזהו ענין האבנים דחושן ואפוד [ש]זהו ג\"כ בבחי' דו\"נ משפיע ומקבל או\"י ואו\"ח כנ\"ל כמו בשמן למאור ואור כ[ו'. ו]הענין הוא דאבני שוהם [ש]בב' כתפות האפוד הוא בבחי' אור משפיע כמו המאור לאור להיות שאבן השוהם הוא [בחי'] אור בהיר בעצם הווייתו והן כלל[ו]' הכולל לכללות נש\"י כמו שהן במקורן הראשון ממש בפנימי' אור אבא כמ\"ש כי את\"ה אבינ\"ו שנק' מאור לפרטי ס\"ר ניצוצ[ו]' הכלולי' בי\"ב שבטים בחושן כו'. וזהו שא' ונתת את שתי האבנים<sup data-n=\"4915\">320</sup> על כתפות האפוד אבני זכרון לבנ\"י ונשא אהרן את שמותם על שתי כתפיו לזכרון, פי' אבני זכרו\"ן שהאבנים<sup data-n=\"4916\">321</sup> מצ\"ע שרשן בבחי' הזכרון שהוא בפנימי' מוח אבא וכידוע דשרש הזכרון באור אבא<sup data-n=\"4917\">322</sup> עצמו כו', וז\"ש ונשא אהרן כו' לזכרון להעלותם במקורם הראשון<sup data-n=\"4918\">323</sup> במוח אבא ששם הזכרו\"ן [ה]תמיד[י ו]כמאמר אין שכחה<sup data-n=\"4919\">324</sup> לפני כסא כבודך<sup data-n=\"4920\">325</sup> כו'<sup data-n=\"4921\">326</sup> השכחה הוא באחוריי' דאבא<sup data-n=\"4922\">327</sup> כו' כמ\"ש במ\"א, וזהו הטעם [ש]בפ' קדש לי כל בכור שהוא בחי' החכ'<sup data-n=\"4923\">328</sup> נא' ולזכרון בין עיניך<sup data-n=\"4924\">329</sup> ובפ' שמע וגם בוהי'<sup data-n=\"4925\">330</sup> כי יביאך א' לטוטפות בין עיניך<sup data-n=\"4926\">331</sup> וד\"ל. אבל אבני החושן הוא [ב]בחי' אור דנש\"י כמו שהן בנה\"ב וע\"כ הי[ו] על לב אהרן והאבנים טובות היו מזוככים מחומריות שלהם ביותר, שזהו ענין הזדככות חומר נפשם בטהרת הלב מכל סיג בתכלית שנק' בר לבב בתשובה ותפלה [שבלב]. ולנגד י\"ב שבטים היו י\"ב אבנים טובות חקוקים בחשן המשפט שמות השבטים ונשא אהרן את שמות<sup data-n=\"4927\">332</sup> כו' בחשן המשפט על לבו לזכרון לפני ה' תמיד דהיינו שיעלה אותם כמו שהם למטה גם<sup data-n=\"4928\">333</sup> בחומר גופם בהעלאה דתשובה ותפלה בהתעוררו' דאה\"ר דאהרן שוש' דמטרוניתא כנ\"ל. וע\"כ היו האבנים הללו על לבו דוקא כי בלב הוא משכן נה\"ב בחלל השמאלי<sup data-n=\"4929\">334</sup> שבו הדם הוא הנפש ועולה ונכלל ברוח החיים שבחלל הימני כנ\"ל בענין הקרבנות, והכל",[["4913","318","<b>בכ\"מ</b>: ביא: ב(ש)כל מי."],["4914","319","<b>נה\"א</b>: שם: נשמת אדם."],["4915","320","<b>ונתת </b>[ביא: ושמת]<b> את שתי האבנים</b>: תצוה כח, יב [בדילוג]."],["4916","321","<b>שהאבנים</b>: ב: שכנ\"י. יא: שהוא כנ\"י. או: כבפנים."],["4917","322","<b>הזכרון באור אבא</b>: ראה גם אוה\"ת תצוה כאן (ע' א'תרנה־ א'תרסג). לעיל פ' שמות כג, ד. וש\"נ."],["4918","323","<b>הראשון</b>: ביא: ליתא."],["4919","324","<b>אין שכחה</b>: תפלת מוסף לר\"ה (ברכת זכרונות). ברכות לב, ב."],["4920","325","<b>לפני כסא כבודך</b>: ביא: ליתא."],["4921","326","<b>כו'</b>: ב: ניתוסף: כי. יא: ניתוסף: פי'."],["4922","327","<b>השכחה הוא באחוריי' דאבא</b>: ראה גם לקמן שנד, ג. מאמרי אדה\"ז תקס\"ה ח\"א ר\"ע מו. ע' שפז וע' שצז. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תפד."],["4923","328","<b>[ש]בפ' קדש. . בחי' החכ'</b>: בא יג, א ואילך. ראה זהר ואתחנן רסב, א."],["4924","329","<b>ולזכרון בין עיניך</b>: בא שם, ט."],["4925","330","<b>בוהי'</b>: יא: כתב: בוא\"ש [ בוהי' אם שמוע] ומחקה."],["4926","331","<b>לטוטפות בין עיניך</b>: ואתחנן ו, ח. בא שם, טז."],["4927","332","<b>את שמות</b>: ביא: את שמותם. ועפ\"ז הוא חיבור שני כתובים תצוה כח, יב. כט. וראה לקמן רפי\"ז. א: שמות השבטים. ו: כבפנים."],["4928","333","<b>גם</b>: יא ניתוסף: כמו שהן. אבו: כבפנים. וראה בפנים ארבע תיבות לפנ\"ז."],["4929","334","<b>בלב. . נה\"ב בחלל השמאלי</b>: <a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא פ\"ט</a>."]]],[2300550547,"הוא ענין א' להעלותם לזכרון לפנימי' אבא כנ\"ל. וע\"כ הי' כל אבן טוב מיוחד במראהו ומינו<sup data-n=\"4930\">335</sup> כפי שרש אותו השבט למעלה, וכמו עכשיו בעליות התפלות בי\"ב שערים <span data-k=\"pg\">תקיח</span> ּ שכל שבט עולה כפי מדרגתו ושרשו למעלה כו'. וזהו שא' לזכרון לפני ה' תמיד בבקר ובערב אע\"פ שהתפלות הן רק בוקר וערב, פי'<sup data-n=\"4931\">336</sup> התמידים נק' עולת תמיד שתמיד של שחר [הי'] מכפר על עבירות דלילה<sup data-n=\"4932\">337</sup> כו' וכמו מצות ת\"ת שהיא תמידי' וע\"כ אמר להעלות נר תמיד לפי שהזכרון הוא תמידי בלא הפסק וביטול לעולם וד\"ל.\n(יו\"ד) <b>והנה</b> מעתה יש להבין הטעם מה שבחושן המשפט על לבו היו י\"ב אבנים מחולקים במיניהם אודם פטדה וברקת כו' וכל א' משמות השבטים הי' קבוע באבן מיוחד אליו ובשתי כתפות [האפוד] הי' ששה משמותם [יחד] על האבן הא' שהוא אבן השוהם כו', ויש להבין<sup data-n=\"4933\">338</sup> תחלה שרש ענין השבטי' דכתיב ששם עלו שבטים כו' עד\"מ שבטי האילן שהענפים פונים כלפי מעלה ושרש יניקתם מן הארץ שמתפשטים שם שרשי האילן, כך הוא האבות הם גופו של אילן ושרשיו ולזה אין קורין אבות אלא לג'<sup data-n=\"4934\">339</sup> והשבטים הם כענפים המסתעפים משרש האילן, וזהו בחי' השבטים דעולם הבריאה שנק' בזהר כורסייא<sup data-n=\"4935\">340</sup> (והוא בחי' י\"ב בקר שתחת ים של שלמה<sup data-n=\"4936\">341</sup> שהן ד' מחנות שכינה<sup data-n=\"4937\">342</sup> שנחלקים לי\"ב והן ד' חיות שבמרכבה<sup data-n=\"4938\">343</sup> כידוע). וידוע דעולם הבריאה הוא ענין ראשית הגילוי מאור האלקי דבחי' המל' להוות ולהחיות מאין ליש נשמות ומלאכים, ונשמות הם בחי' פנימי' דעולם הבריא' והן האבות שהן המרכבה<sup data-n=\"4939\">344</sup> פנימי' בו\"ק דבריאה שמתחלקים לי\"ב שבטים ועיקרם בחי' חג\"ת דאבות<sup data-n=\"4940\">345</sup> כו', והתחלקות זו הוא בהתכללות<sup data-n=\"4941\">346</sup> דוקא, והיינו ענין י\"ב גבולי אלכסון (כמשי\"ת). ואמנם ידוע שבחי' הביטול במציאות שבמרכבה דבריאה הוא רק בבחי' ביטול היש לאי\"ן בלבד, מאחר שבעולם הבריאה בא אור האלקי בבחי' המל' ע\"י צמצום והסתר להיות התהוות בריאה ממש מאין ליש גמור, א\"כ גם בביטול הבריאה אינו אלא ביטול היש לאי\"ן בלבד שאינו בחי' ביטול עצמי בבחי' אין ממש רק שנתבטל מישות שלו לבד כמו המתבטל לפני המלך בבואו לפניו",[["4930","335","<b>כל אבן טוב. . ומינו</b>: תצוה כח, יז ואילך."],["4931","336","<b>פי'</b>: ביא: כי."],["4932","337","<b>תמיד של שחר. . עבירות דלילה</b>: במד\"ר פכ\"א, כא ובהנסמן במתנות כהונה שם. מאמרי אדה\"א שמות ח\"ב ע' תקעא. וש\"נ."],["4933","338","<b>להבין</b>: יא: להקדים."],["4934","339","<b>אין קורין אבות אלא לג'</b>: ברכות טז, ב. ראה גם לעיל פ' וארא סו, א. וש\"נ."],["4935","340","<b>דעולם הבריאה. . כורסייא</b>: ראה זהר (רע\"מ) בא מג, א. אור החמה שם. ע\"ח (שער כסה\"כ) שמ\"ו, פ\"א."],["4936","341","<b>י\"ב בקר שתחת ים של שלמה</b>: מל\"א ז כה, מד. דהי\"ב ד, טו. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680291\" data-slug=\"torat-chaim\" data-id=\"2300680291\">תו\"ח וישב רט, א</a> ובהערה 9. מאמרי אדה\"א ויקרא ח\"א ע' רכג. שה\"א פז, א. לעיל פ' בשלח רנ, א."],["4937","342","<b>ד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["4938","343","<b>ד' חיות שבמרכבה</b>: יחזקאל א, ה ואילך."],["4939","344","<b>האבות שהן המרכבה</b>: נסמן לעיל פ' יתרו רנא, ג."],["4940","345","<b>חג\"ת דאבות</b>: ראה גם לעיל פ' וארא סא, ד. וש\"נ."],["4941","346","<b>זו הוא בהתכללות</b>: יא: זאת. ביא: יש בה התכללות."]]],[2300550560,"כנודע. אבל בחי' הביטול שבבחי' האצי' הוא ביטול [עצמי בבחי' אין ממש מצד] עצמו' אוא\"ס שבאצי' דאיהו וחיוהי חד<sup data-n=\"4942\">347</sup> ממש שמיוחדים בעצמות המאציל בתכלית כמו שלהבת הקשורה בגחלת<sup data-n=\"4943\">348</sup> וכה\"ג ונק' יחו\"ע [כידוע] (כמו משה שא' ונחנו מה מ\"ה בעצם<sup data-n=\"4944\">349</sup> כו'), והוא ג\"כ בחי' ביטול עצמי דאבות הן המרכבה כמו שהן בבחי' חג\"ת דאצי' שהוא בבחי' אי[ל]ן דאצי' ונק' בזהר אילנא דחיי<sup data-n=\"4945\">350</sup> (שהאבות הן בחי' שרש אילן זה והענפים שמסתעפים ממנו הן בחי' השבטים דאצי' שנק' שבטי י\"ה ממש כו'). ופי' אילנ\"א דחי\"י שהוא עה\"ח שבתוך הגן ש[מ]אילן זה ימצא ממנו<sup data-n=\"4946\">351</sup> מקור כל מציאות חיים העליוני' ותחתונים והוא שממנו יומשך מקור כל<sup data-n=\"4947\">352</sup> מציאות אור האלקי הנמשך להתהוות הנבראים <span data-k=\"pg\">1038</span> ּ מאין לי\"ש, וז\"ש כי עמך מקור חיים<sup data-n=\"4948\">353</sup> ונק' חיי העולמות<sup data-n=\"4949\">354</sup> חי בעצם שזהו נק' עה\"ח בעצם טרם שמתפשט ונמשך בגילוי אור וחיות [ה]אלקי בעולמות, וכידוע דבחי' מל' דאצי' בבי\"ע נק' אלקים חיים<sup data-n=\"4950\">355</sup> שזהו הבא בגילוי אור בהתפשטו' למטה להחיות כל העולמות כמ\"ש ואתה מחי' את כולם<sup data-n=\"4951\">356</sup> כו' שזהו בחי' יחו\"ת דמל' בבי\"ע והוא בשכמל\"ו<sup data-n=\"4952\">357</sup>, אבל שרש גילוי אור זה דבחי' המל' בבי\"ע נמשך מאילנא דחיי דאצי' עצמו וד\"ל (ומאילנא דחיי זה שבאצי' הענפים שלו מתפשטים למטה ושרשיו באצי' היפך האילן דבריאה שענפיו פונים למעלה וענפי אילן זה דאצי' יורד[י'] מלמעלה למטה וע\"כ גם שבטים דבריאה אמרו כשם שאין בלבך<sup data-n=\"4953\">358</sup> אלא א'<sup data-n=\"4954\">359</sup> כו' (כמשי\"ת).\n<b>והנה</b> ידוע שהשבטים אמרו ליעקב כשם שאין בלבך אלא א' כך אין בלבינו אלא א' (וז\"ש בשכמל\"ו), וזה פלא לכאורה איך יוכלו להדמות ליעקב לומר כשם כו' והלא יעקב הי' מרכבה בבחי' האצי' דשם איהו וחיוהי חד<sup data-n=\"4955\">360</sup> בביטול העצמי כנ\"ל והשבטים שהם בעולם הבריאה כנ\"ל אינם רק בחי' ביטול הי\"ש לאין בלבד שהוא בחי' [י]ח[ו]\"ת דמל' בבי\"ע. אמנם הענין הוא שמפני זה אמרו ליעקב דוקא כשם שאין בלבך אלא א'<sup data-n=\"4956\">361</sup>, להיות שיעקב הי' בחי' מרכבה לבחי' ת\"ת דז\"א שנק' קו האמצעי<sup data-n=\"4957\">362</sup> בריח התיכון שמבריח מ[ן ה]קצה<sup data-n=\"4958\">363</sup> העליון דכת\"ר לקצה התחתון דבחי' המל' בבי\"ע כו', דהיינו שבוקע גם המסך",[["4942","347","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["4943","348","<b>שלהבת הקשורה בגחלת</b>: ס\"י פ\"א, מ\"ז."],["4944","349","<b>ונחנו מה </b>[ביא: ליתא]<b> מ\"ה בעצם</b>: בשלח טז, ז. ח. ראה גם לעיל פ' שמות מג, א. וש\"נ."],["4945","350","<b>אילנא דחיי</b>: ראה גם זהר בהקדמה ח, א־ יד, א ובאור החמה שם (רא\"ג). בראשית כו, א ובמק\"מ שם. לז, ב ובמק\"מ שם. ויצא קנא, א ובאוה\"ח שם. וישלח קעח ובאוה\"ח שם (רא\"ג). ראה גם פלח הרמון בשלח ע' קמ."],["4946","351","<b>ממנו</b>: ב: כבפנים. יא: כתבו ומחקו."],["4947","352","<b>מציאות. . כל</b>: ב: ליתא. וכנראה נשמט מפני תיבות הדומות: מקור כל. . מקור כל."],["4948","353","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["4949","354","<b>חיי העולמות</b>: ביא: חי העולמי\"ם."],["4950","355","<b>מל'. . אלקים חיים</b>: ואתחנן ה, כג. ראה גם מאמרי אדה\"א בראשית ע' שעו. ויקרא ח\"ב ע' תקמד. וש\"נ. דברים ח\"ג ע' א'כא."],["4951","356","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["4952","357","<b>יחו\"ת. . בשכמל\"ו</b>: זהר בראשית יח, ב. פסחים נו, א."],["4953","358","<b>כשם שאין בלבך</b>: נסמן לעיל פ' משפטים רצ, ב. ראה גם לקמן פ' ויקהל תד, ד."],["4954","359","<b>אלא א'</b>: ביא: ליתא."],["4955","360","<b>איהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["4956","361","<b>אלא א'</b>: ביא: כו'."],["4957","362","<b>ת\"ת. . קו האמצעי</b>: ראה השמטות לזח\"א רנז, א. ש\"א — לר\"י גיקטלייא — ש\"ה ע' סג ואילך."],["4958","363","<b>ת\"ת. . בריח התיכון שמבריח מ[ן ה]קצה</b>: ע\"פ תרומה כו, כח. ויקהל לו, לג. ראה זהר בלק קפו, ב ובהגהת הרח\"ו שם."]]],[2300550573,"שמפסיק בין אצי' לבי\"ע<sup data-n=\"4959\">364</sup> כידוע דיעקב אותיות יבקע<sup data-n=\"4960\">365</sup> כמ\"ש בזהר שז\"ש אז יבקע<sup data-n=\"4961\">366</sup> כו', ולזה אמרו ליעקב כשם שאין בלבך בבחי' יחו\"ע דאצי' אלא א' פשוט כנ\"ל דשם איהו וחיוהי חד ע\"י בחי' קו\"ח שעובר בכל האצי' כו', כך אין בלבינו גם שנשמותם מורכבת<sup data-n=\"4962\">367</sup> בעולם הבריאה ג\"כ אלא א' פשוט שבאצי' ממש ואע\"פ שבמרכבה דבריאה אין שם רק בחי' ביטול היש לאין [ב]לבד כו'. אך באמת גם זה שיש בהם בחי' ביטול היש לאין בא ונמשך מאור דיחו\"ע דאצי', ואמנם אינה באה רק ע\"י צמצום דמסך המבדיל שאינו רק הארה דהארה כידוע, אבל ע\"י בחי' יעקב שנק' בריח התיכון כו' מבריח גם לבחי' המל' שבבריאה שיאיר שם ג\"כ כמו באור יחו\"ע דאצי' ממש בלי חילוק מדרגות כלל וכמ\"ש ה' א' ושמו אחד<sup data-n=\"4963\">368</sup> למהוי אחד באחד<sup data-n=\"4964\">369</sup> ממש. וראי' לזה ממ\"ש כגוונא דאינון מתייחדין לעילא<sup data-n=\"4965\">370</sup> ביחו\"ע דע\"ס דאצי' אוף הכי ממש אתייחדת המל' בכורסייא שהוא בעולם הבריאה ברזא דאחד דיחו\"ע ממש כי אין המסך מפסיק בפני בחי' יעקב שנק' בריח התיכון כו', אע\"פ שמחמת הצמצום דשם אלקי' נמשך שם האור האלקי בבחי' גבול מ\"מ יבקע אור האצי' במסך זה ויאיר שם כמו באצי' ממש להיותו בבחי' ביטול עצמי, וזהו כשם שאין בלבך בלבך<sup data-n=\"4966\">371</sup> ממש אלא א' כך ממש אין בלבינ\"ו כו'. וזהו ענין<sup data-n=\"4967\">372</sup> כי הוי' דאצי' הוא האלקי' שבבריאה כולא חד<sup data-n=\"4968\">373</sup> ממש (וכמו בשבת <span data-k=\"pg\">תקיט</span> ּ דחסדים דהוי' בוקעות בצמצום דשם אלקים ע\"כ אומרים ך\"ו כל\"ח בשבת<sup data-n=\"4969\">374</sup> כידוע. וזהו טעם המאמר דכגוונא דאינון כו' שהוא בשבת<sup data-n=\"4970\">375</sup> דוקא. וז\"ש אז תתענג על הוי' כו' והאכלתיך נחלת יעקב אביך<sup data-n=\"4971\">376</sup> שנק' נחלה בלי מצרים<sup data-n=\"4972\">377</sup> למעלה ולמטה כו' (והוא בחי' הרחמים שעולה למעלה [מעלה] ביותר ויורד ונמשך למטה מטה כו' ביותר כמ\"ש במ\"א), והוא מפני שיעקב נק' איש ת\"ם<sup data-n=\"4973\">378</sup> שאין שרש יניקה לק\"נ בו כלל כי מטתו שלימה<sup data-n=\"4974\">379</sup> בי\"ב שבטים, משא\"כ בחי' ב' הקוין ימין ושמאל דאברהם ויצחק יצאו מהם מותרי השפע בחי' חו\"ג דק\"נ עשו [וישמעאל]<sup data-n=\"4975\">380</sup>, כו' וע\"כ אין אור האצי' בא להדי' בבי\"ע בב' הקוין דחו\"ג דאצי' כ\"א ע\"י מסך מבדיל לפי שיכולים גם החיצונים לקבל [ב]בחי' נוגה דבי\"ע, אבל יעקב יכול לייחד<sup data-n=\"4976\">381</sup> למטה מטה ואין המסך מבדיל כלל וזהו שנק' מבריח גם לקצה התחתון כו'). וע\"כ אמרו השבטים כך אין בלבינו כו' אפי' בניצוץ הקטן",[["4959","364","<b>המסך שמפסיק בין אצי' לבי\"ע</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ד. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["4960","365","<b>דיעקב אותיות יבקע</b>: ראה ע\"ח (שער הארת המוחין) של\"ב, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680299\" data-slug=\"torat-chaim\" data-id=\"2300680299\">תו\"ח וישלח קפה, ב</a> הערה 17."],["4961","366","<b>אז יבקע</b>: ישעי' נח, ח."],["4962","367","<b>שנשמותם מורכבת</b>: ביא: שנשמתם מרכבה."],["4963","368","<b>ה' א' ושמו אחד</b>: נסמן לעיל פ' יתרו רסב, א."],["4964","369","<b>למהוי אחד באחד</b>: ראה זהר תרומה קלג, סע\"ב ואילך. קלה, סע\"א."],["4965","370","<b>כגוונא דאינון מתייחדין לעילא</b>: ראה זהר תרומה קלה, סע\"א."],["4966","371","<b>בלבך</b>: ביא: ליתא."],["4967","372","<b>ענין</b>: שם: ע\"י."],["4968","373","<b>כי הוי'. . הוא האלקי'. . כולא חד</b>: ואתחנן ד, לה. לט. ראה זהר בהקדמה יב, א. תרומה קסא, ב. לעיל פ' וארא ס, א. וש\"נ."],["4969","374","<b>ך\"ו כל\"ח בשבת</b>: ראה גם לעיל פ' בשלח קמד, א. וש\"נ."],["4970","375","<b>דכגוונא. . בשבת</b>: ראה גם לעיל פ' יתרו רסד, סע\"ג ואילך."],["4971","376","<b>אז תתענג. . נחלת יעקב אביך</b>: ישעי' נח, יד."],["4972","377","<b>נחלה בלי מצרים</b>: שבת קיח, סע\"א. ראה מאמרי אדה\"א במדבר ח\"ג ע' א'קח ואילך."],["4973","378","<b>שיעקב נק' איש ת\"ם</b>: תולדות כה, כז."],["4974","379","<b>שיעקב. . מטתו שלימה</b>: רש\"י ויחי מז, לא. פסחים נו, א."],["4975","380","<b>חו\"ג דק\"נ עשו [וישמעאל]</b>: ראה גם לעיל פ' בא קיז, ג. וש\"נ."],["4976","381","<b>לייחד</b>: ביא: לירד."]]],[2300550584,"דישראל בבחי' נפש דעשי' הרי יכול למס\"נ בא' ביחו\"ע אע\"פ ששרש נשמתו רק מבחי' מל' דעשי' כו' (וזהו עכ\"פ ההפרש בין חול לשבת דבחול אין בנש\"י דבי\"ע רק בביטול היש לאין מצד המסך המבדיל וגם כח זה נמשך מיחו\"ע דאצי' כנ\"ל ובשבת נמשך ביחו\"ת כמו ביחו\"ע ממש [כנ\"ל]. וזהו ג\"כ בכל יום בק\"ש בפסוק דשמע [ישראל] למס\"נ באחד לפי שהק\"ש יש בה מבחי' השבת שנש\"י עולים בשרשם בפנימי' דאו\"א שנק' קדש מלה בגרמי'<sup data-n=\"4977\">382</sup> כו') (וזהו ששם עלו שבטים [כו'] שבקיעת המסך הנ\"ל הוא בב' אופנים, א' מלמעלה למטה [מ]יעקב לשבטים כמ\"ש כשם שאין בלבך כו' והיינו מאילן דאצי' שמתפשטים הענפי' בבריאה בלי מסך מפסיק כלל, ולפ\"ז מ\"ש ששם עלו שבטים קאי בשבטי י\"ה דאו\"א ששם עולים י\"ב גבולי אלכסון דז\"א ומשם יכולים לירד מאצי' לבריאה, והב' שבטים דבריאה שעולים באצי' מלמטה למעלה ובוקעים המסך כמו עליות הנשמות בכל ליל שבת<sup data-n=\"4978\">383</sup> כמ\"ש השתחוו לה' בהדרת קדש<sup data-n=\"4979\">384</sup> [כו'] וד\"ל).\n(יא) <b>והנה</b> ידוע בטעם מספר השבטים י\"ב דוקא שהן בחי' י\"ב גבולי אלכסון שבו\"ק העליונים כו', וביאור הענין הנה ידוע דמדות העליונים דאצי' הם רק ששה כמ\"ש לך ה' הגדולה<sup data-n=\"4980\">385</sup> והגבורה והת\"ת כו' עד כי כל בחי' יסוד<sup data-n=\"4981\">386</sup> שהוא בחי' ו\"ק מעלה ומטה מזרח ומערב צפון ודרום כידוע שנק' בחי' מקום גשמי שהוא בגדר ו\"ק הללו והוא הנק' עולם, ולכך עיקר הכוונה בא[חד] להמליכו<sup data-n=\"4982\">387</sup> בשמים וארץ וד' רוחות העולם כידוע. והנה בחי' מקום כזה יש ברוחני' בכל עולם ועולם דבי\"ע עד רום המעלות והיינו בחי' ו\"ק דבריאה ויצי' עד ו\"ק דאצי' [כו' ו]למעלה שעז\"א הנה מקום אתי<sup data-n=\"4983\">388</sup> שבחי' המקום העליון בטל ונכלל בעצמות אוא\"ס שלמעלה מבחי' מקום וכמא' הוא מקומו ש\"ע<sup data-n=\"4984\">389</sup> ואין העולם מקומו, וע\"כ צריך להמשיך מלמעלה להיותו בחי' מקום כמו שהתהוות הזמן בא ממקור הזמן כך בחי' מקום שנק' עולם כידוע בענין עש\"ן<sup data-n=\"4985\">390</sup> כו', וז\"ש ברו\"ך המקו\"ם<sup data-n=\"4986\">391</sup> שנמשך להיות ממנו בחי' התהוות מקום דבחי' ו\"ק מעלה ומטה כו'. וזהו תמליכהו בשמים ובארץ<sup data-n=\"4987\">392</sup> כו' לפי שאין העולם מקומו, ולכך א' ברוך כבוד ה' ממקומו<sup data-n=\"4988\">393</sup> דוקא <span data-k=\"pg\">1040</span> ּ כמו הנה ה' יוצא ממקומו<sup data-n=\"4989\">394</sup> כו' וכן אלכה אשובה אל מקומי<sup data-n=\"4990\">395</sup> כו', והוא בחי'",[["4977","382","<b>קדש מלה בגרמי</b>: זהר אמור צד, ב."],["4978","383","<b>עליות הנשמות בכל ליל שבת</b>: ראה ע\"ח (שער קיצור אבי\"ע) ש\"נ, ספ\"ו. לעיל פ' בשלח קצו, ד (בקבלת שבת). לקמן פ' ויקהל תטו, ד (בכל שבת). תכג, ב (שבת). וראה גם לעיל פ' שמות לה, ב. וש\"נ."],["4979","384","<b>השתחוו לה' בהדרת קדש</b>: תהלים כט, ב."],["4980","385","<b>לך ה' הגדולה</b>: דהי\"א כט, יא."],["4981","386","<b>כי כל בחי' יסוד</b>: ראה זהר בראשית לא, א. לעיל פ' וארא נג, ד הערה 39."],["4982","387","<b>הכוונה בא[חד] להמליכו</b>: ברכות יג, ב."],["4983","388","<b>הנה מקום אתי</b>: תשא לג, כא."],["4984","389","<b>הוא מקומו ש\"ע</b>: ראה ב\"ר פס\"ח, ט. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670491\" data-slug=\"torat-chaim\" data-id=\"2300670491\">תו\"ח בראשית מג, א</a> הערה 2."],["4985","390","<b>עש\"ן</b>: עולם שנה נפש — ראה גם לעיל שכא, ב. וש\"נ."],["4986","391","<b>ברו\"ך המקו\"ם</b>: מדות ספ\"ה. הגש\"פ (פסקא זו). ראה גם לעיל פ' בשלח רלד, ב."],["4987","392","<b>תמליכהו בשמים ובארץ</b>: ראה זהר (רע\"מ) פינחס רכג, סע\"ב. עקב ערב, א. הנסמן במאמרי אדה\"א בראשית ע' לד."],["4988","393","<b>ברוך כבוד ה' ממקומו</b>: יחזקאל ג, יב."],["4989","394","<b>הנה ה' יוצא ממקומו</b>: ישעי' כו, כא."],["4990","395","<b>אלכה אשובה </b>[ביא: ואשובה]<b> אל מקומי</b>: הושע ה, טו [ושם: אלך אשובה — ראה גם לעיל פ' שמות לט, א. וש\"נ]."]]],[2300550595,"המדות דאוא\"ס בעצמו שקודם הצמצום דקו\"ח כו', ועז\"א ממקומך דוקא תופיע ותמלוך<sup data-n=\"4991\">396</sup> כו' וז\"ש הנה מקו\"ם את\"י ממש שכל בחי' מקום דאבי\"ע בטל ונכלל שם, וז\"ש לך ה' הגדולה והגבורה כו', אך בק\"ש צ\"ל בחי' העלאה דו\"ק למעלה באח\"פ ובחי' ההמשכה<sup data-n=\"4992\">397</sup> בד' דא[חד] להמשיכו<sup data-n=\"4993\">398</sup> בו\"ק מעלה ומטה כו' כמ\"ש במ\"א וד\"ל.\n<b>והנה</b> הגם שבחי' מקום אינו אלא בעל ו\"ק [לבד] שהן ו' מדות דחג\"ת כו' עכ\"ז יש בזה מספר י\"ב מצד בחי' [ה]התכללות דו' מדות זע\"ז שנק' ששה כפולות, והוא ע\"י בחי' התכללו' די\"ב ג\"א כידוע שזהו ג\"כ בו\"ק דמעלה ומטה מזרח ומערב צפון ודרום כו' [דהיינו] כמו מזרחית רומית עם מערבית תחתית ומערבית רומית עם מזרחי' תחתית הרי ב'<sup data-n=\"4994\">399</sup> וכן בצפון ודרום דרומית רומי' עם צפוני' תחתית וצפוני' רומי' עם דרומי' תחתית הרי עוד ב' כו'. וכמו\"כ במעלה ומטה א' קו מלמטלמ\"ע וב' קו ההולך מלמעלה למטה (ולא באלכסון שא\"כ היינו אלכסון [ד]דרום וצפון ומזרח ומערב כנ\"ל). וכמו\"כ התכללו' המדות<sup data-n=\"4995\">400</sup> בציור קוין דימין ושמאל ואמצע דאמצע כולל ב' הקוין שהן ו' מדות דחסד דרועא ימינא<sup data-n=\"4996\">401</sup> קו ימין<sup data-n=\"4997\">402</sup> שנכללים עם ו' מדות דגבורה דרועא שמאלא ג\"כ באופן די\"ב ג\"א כנ\"ל כמו מחסד שבחסד עם הוד שבגבו' (שזהו כמו דרומי' רומי' עם צפוני' תחתי' כו') וכן מחסד שבגבו' קו השמאל עם נו\"ה שבחסד קו הימין (וכה\"ג בת\"ת ומל' שהוא מזרח ומערב<sup data-n=\"4998\">403</sup> ומעלה ומטה [שהן] נו\"ה<sup data-n=\"4999\">404</sup> כמ\"ש בפרד\"ס<sup data-n=\"5000\">405</sup> ומבואר במ\"א בדרך פרטיות). וזהו ענין מספר הי\"ב שבטים שהן בחי' ו\"ק כפולים שהוא ע\"י התכללו' די\"ב ג\"א הנ\"ל והן הסדר הד' דגלים שבמדבר כמ\"ש בזהר ע\"פ איש על דגלו<sup data-n=\"5001\">406</sup> כו' (וכ\"ז בו\"ק דבריאה שהוא בחי' י\"ב שבטי' דבריאה וכמו\"כ ממש הוא בו\"ק דאצי' יש י\"ב ג\"א ונק' שבטים דאצי' כנ\"ל וד\"ל) (והיינו י\"ב צירופי' דשם הוי'<sup data-n=\"5002\">407</sup> שמטעם זה יש יתרון מעלה בשבטים יותר גם מאבות כמ\"ש בפ' משפטים<sup data-n=\"5003\">408</sup> שנק' פני אדם שלמעלה מאבות שהן המרכבה דפני ארי' ושור ונשר כו', לפי שיש בהתכללו' ו\"ק דשבטים דוקא בחי' שם הוי' ממש ונק' צבאות ה'<sup data-n=\"5004\">409</sup> והוי' צבאות<sup data-n=\"5005\">410</sup> שאין זה באבות שהן רק חג\"ת כו', וראי' ממ\"ש שוב למען עבדיך<sup data-n=\"5006\">411</sup> שבטי",[["4991","396","<b>ממקומך. . תופיע ותמלוך</b>: נוסח הקדושה לשויו\"ט [בדילוג — ראה גם לעיל קפה, ב. וש\"נ]."],["4992","397","<b>בק\"ש צ\"ל בחי' העלאה. . ההמשכה</b>: ראה גם סידור פז, א. אמ\"ב פתח השער י, א."],["4993","398","<b>להמשיכו</b>: יא: להמליכו."],["4994","399","<b>הרי ב'</b>: יא: ליתא. אבו: כבפנים."],["4995","400","<b>המדות</b>: ביא: בו' מדות."],["4996","401","<b>דחסד דרועא ימינא</b>: ת\"ז בהקדמה (יז, א)."],["4997","402","<b>קו ימין</b>: ב: ליתא. יא: דקו הימין."],["4998","403","<b>בת\"ת ומל' שהוא מזרח ומערב. . בפרד\"ס</b>: ראה פרדס (שער ערכי הכנויים) שכ\"ג, מערכת מזרח. מערב."],["4999","404","<b>ומעלה ומטה [שהן] נו\"ה. . בפרד\"ס</b>: ראה פרדס (שער פרטי השמות) שכ\"א, פ\"ו. מאמרי אדה\"א במדבר ח\"ג ע' א'קעט."],["5000","405","<b>בפרד\"ס</b>: כ\"ה בכ\"מ בהנחות ודרושי כ\"ק אדה\"א. ראה גם לעיל פ' בא צ, א. וש\"נ."],["5001","406","<b>בזהר ע\"פ איש על דגלו</b>: במדבר ב, ב. זהר שם קיח, ב. ביאוה\"ז שם פה, א ואילך."],["5002","407","<b>שבטים. . י\"ב צירופי' דשם הוי'</b>: ראה רקאנטי תצוה כח, ב. לעיל פ' שמות כא, ד. וש\"נ."],["5003","408","<b>מעלה בשבטים. . בפ' משפטים</b>: לעיל רפו, ד."],["5004","409","<b>צבאות ה'</b>: בא יב, מא."],["5005","410","<b>והוי' </b>[ב: הוי'. יא: או הוי']<b> צבאות</b>: שמו\"א א, (ג). יא."],["5006","411","<b>שוב למען עבדיך</b>: ישעי' סג, יז."]]],[2300550606,"נחלתיך דוקא אע\"פ שמקבלים מיחו\"ע דאצי' בחי' יעקב בריח התיכון כנ\"ל. ולכך ס\"ר נש\"י היו ראוים לקבלת התורה<sup data-n=\"5007\">412</sup> פנים בפנים שלא הי' זה באבות דכתי' בהם ושמי הוי' לא נודעתי להם<sup data-n=\"5008\">413</sup> שהן תומ\"צ בגשמיות שניתן לס\"ר נש\"י במ\"ת שלמעלה מן המצות ברוחניות דיחו\"ע דאצי' שקיימו האבות כו'. וז\"ש ששם עלו שבטים למעלה מחג\"ת דאבות דאצי' וכמ\"ש כסו הרים צלה<sup data-n=\"5009\">414</sup> כו' וע\"כ נק' שבטי י\"ה דחו\"ב דאצי' המולידי' המדות ומהן נמשך לעדות לישראל דלעילא להודות לשם הוי' דבחי' ז\"א הוא שמקבל מוחי' מאו\"א כו' כידוע (משום דא\"ח עט\"ב<sup data-n=\"5010\">415</sup> ובינה יתירה ניתנה באשה<sup data-n=\"5011\">416</sup> כו') וזהו שרש בחי' י\"ב אבני החשן שבלב אהרן שיש להם שרש למעלה מ[ן] אבני שוהם דכתפות האפוד מטעם הנ\"ל וד\"ל<sup data-n=\"5012\">417</sup>.\n<span data-k=\"pg\">תקכ</span> ּ<b>(יב)</b> והנה בחי' התכללות ו' מדות הנ\"ל שנק' י\"ב ג\"א אינו אלא כשהם בלב דוקא, אז באים לכלל גילוי אור בדרך פרט להיות כלול כ\"א מהיפוכו כמו מחסד שבגבו' עם גבורה שבחסד שהן כמו ב' הפכים ומתכללים יחד בענין מעשה א' לשניהם, דהיינו כמו משלם לשונאיו אל פניו להאבידו<sup data-n=\"5013\">418</sup> שמשלם חסד וטוב בעוה\"ז בחיצוני' ותוכ[ו] רצוף דין קשה כדי להאבידו בעוה\"ב, וכמו מאריך אף לרשעים<sup data-n=\"5014\">419</sup> כו', וכמ\"ש בפרוח רשעים כו' להשמדם<sup data-n=\"5015\">420</sup> כו', וכן אם רעב שונאך האכילהו לחם<sup data-n=\"5016\">421</sup> כו' כי גחלים<sup data-n=\"5017\">422</sup> כו' שמלובש הדין בחסד דהיינו שעושה פעולת [כח] הדין ע\"י לבוש מעשה דחסד דוקא. ולהיפך ממש הוא מה שמלובש החסד בדין כמו יסורים של אהבה<sup data-n=\"5018\">423</sup> לצדיק[י'] שאשר יאהב ה' יוכיח<sup data-n=\"5019\">424</sup> ביסורים לטובתם דוקא, וכן תוכחת מוסר קשה דאב לבנו שתוכו רצוף אהבה וחסד דוקא ומלבישו בלבוש דדין קשה כו', וא\"כ ה\"ז ב' הפכים בתכלית ובאים כא' בלב כמו אב שמייסר<sup data-n=\"5020\">425</sup> את בנו לאוהבו<sup data-n=\"5021\">426</sup> לעשות בו דין קשה לייסרו שפנימיותו חסד למרק עון בנו ומשלם לאוהב<sup data-n=\"5022\">427</sup> חסד בחיצוני' ותוכו [ו]פנימיו' דין קשה על שמשל בקושי על בנו לייסרו בנותר<sup data-n=\"5023\">428</sup> כו'. וכך הוא בכל גלות ישראל שנק' בנים<sup data-n=\"5024\">429</sup> באוה\"ע לייסרם בלחץ ודוחק לטובתם בפנימיות וכתיב עת אשר שלט האדם<sup data-n=\"5025\">430</sup> באדם לרע לו שזהו כמו שמשלם לשונאיו כו', וביציא[ה מן] הגלות נתהפך להיפך לפי שמתגלה בחי' הפנימי' דהיינו",[["5007","412","<b>ס\"ר נש\"י. . לקבלת התורה</b>: ראה שבת פח, א. הנסמן לעיל פ' תרומה שיא, ד."],["5008","413","<b>ושמי הוי' לא נודעתי להם</b>: וארא ו, ג. ראה גם לעיל פ' יתרו רנא, ב. וש\"נ."],["5009","414","<b>כסו הרים צלה</b>: תהלים פ, יא."],["5010","415","<b>דא\"ח עט\"ב</b>: משלי יב, ד."],["5011","416","<b>ובינה יתירה ניתנה באשה</b>: נדה מה, ב."],["5012","417","<b>כו'). . וד\"ל</b>: ביא: כו'. . וד\"ל)."],["5013","418","<b>משלם לשונאיו אל פניו להאבידו</b>: ואתחנן ז, י [ושם: ומשלם — נסמן בסמוך]. ראה גם לעיל פ' שמות ל, ד. וש\"נ."],["5014","419","<b>מאריך אף לרשעים</b>: סנהדרין קיא, סע\"א."],["5015","420","<b>בפרוח רשעים כו' להשמדם</b>: תהלים צב, ח."],["5016","421","<b>אם רעב שונאך האכילהו לחם</b>: משלי כה, כא. ראה ביאוה\"ז חוקת צו, ב. שע\"ת קכח, א ובהערה 4."],["5017","422","<b>כי גחלים</b>: משלי שם, כב. ראה גם ע\"ח (שער ק\"נ) שמ\"ט, פ\"ח."],["5018","423","<b>יסורים של אהבה</b>: ברכות ה, א. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' מב. וש\"נ. לקמן פ' ויקהל תט, ד."],["5019","424","<b>שאשר יאהב ה' יוכיח</b>: משלי ג, יב."],["5020","425","<b>שמייסר</b>: ביא: שמוסר."],["5021","426","<b>לאוהבו</b>: שם: לאויבו."],["5022","427","<b>לאוהב</b>: שם: לאויב."],["5023","428","<b>לייסרו בנותר</b>: שם: ויסרו ביותר."],["5024","429","<b>ישראל שנק' בנים</b>: פ' ראה יג, א. שמות ד, כב."],["5025","430","<b>עת אשר שלט האדם</b>: קהלת ח, ט. ראה גם לעיל פ' שמות ל, ד. וש\"נ."]]]]});
